    @Test
    public void testRejectInMemoryAboveCap() throws Exception {
        // Default cap is 60min, which the formatter renders as the largest clean
        // divisor "1h". The reject must include the value so the operator knows
        // what they need to override.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            try {
                execute("CREATE LIVE VIEW lv FLUSH EVERY 1s IN MEMORY 2h START FROM NOW AS " +
                        "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");
                Assert.fail("expected IN MEMORY > cap reject");
            } catch (SqlException e) {
                Assert.assertTrue(e.getMessage(), e.getMessage().contains(
                        "IN MEMORY must be at most cairo.live.view.in.memory.max (1h)"));
            }
        });
    }

    @Test
    public void testRejectDefaultInMemoryAboveCap() throws Exception {
        // When IN MEMORY is omitted it defaults to FLUSH EVERY. FLUSH EVERY has no
        // upper bound of its own, so a large FLUSH EVERY with no explicit IN MEMORY
        // must still hit the cairo.live.view.in.memory.max cap (default 60min = 1h)
        // rather than silently retaining 2h of computed output in RAM.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            try {
                execute("CREATE LIVE VIEW lv FLUSH EVERY 2h START FROM NOW AS " +
                        "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");
                Assert.fail("expected defaulted IN MEMORY > cap reject");
            } catch (SqlException e) {
                Assert.assertTrue(e.getMessage(), e.getMessage().contains(
                        "FLUSH EVERY must be at most cairo.live.view.in.memory.max (1h) because IN MEMORY defaults to FLUSH EVERY"));
            }
        });
    }

    @Test
    public void testRejectInMemoryBelowFlushEvery() throws Exception {
        // The asserted message requires the FLUSH EVERY value in parentheses so the
        // operator sees what the floor was (1s in this case).
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            try {
                execute("CREATE LIVE VIEW lv FLUSH EVERY 1s IN MEMORY 500ms START FROM NOW AS " +
                        "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");
                Assert.fail("expected IN MEMORY < FLUSH EVERY reject");
            } catch (SqlException e) {
                Assert.assertTrue(e.getMessage(), e.getMessage().contains(
                        "IN MEMORY must be at least FLUSH EVERY (1s)"));
            }
        });
    }

    @Test
    public void testWalPurgeHonorsLvConsumedSeqTxnFloor() throws Exception {
        assertMemoryLeak(() -> {
            // Override the class default (epoch): the WAL purge job's interval gate
            // only fires once the clock is past one check interval (30s), so a clock
            // frozen at epoch would skip every sweep. Pin it below the data so the
            // view still materializes the rows, but far enough past epoch for the
            // purge to run.
            setCurrentMicros(MicrosTimestampDriver.floor("2026-05-31T00:00:00.000000Z"));
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");

            // First insert + drain — base table applies seqTxn 1.
            execute("INSERT INTO base (ts, x) VALUES ('2026-06-01T00:00:00.000000Z', 1)");
            drainWalQueue();
            // Force a fresh segment for the next insert by releasing pooled writers.
            engine.releaseInactive();
            // Second insert + drain — base table applies seqTxn 2 in segment 1.
            execute("INSERT INTO base (ts, x) VALUES ('2026-06-01T00:01:00.000000Z', 2)");
            drainWalQueue();
            engine.releaseInactive();

            // Purge with the LV still at lvConsumedSeqTxn = 0: segment 0 must be
            // retained because the LV hasn't consumed seqTxn 1 yet.
            drainPurgeJob();
            assertSegmentExistence(true, "base", 1, 0);

            // Refresh + persist. lvConsumedSeqTxn advances to base's head.
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            drainWalQueue();

            // Now the LV no longer needs the old segment. Purge must reap it.
            engine.releaseInactive();
            drainPurgeJob();
            assertSegmentExistence(false, "base", 1, 0);

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testInvalidatedViewReleasesWalRetentionFloor() throws Exception {
        // An INVALID live view releases its WAL purge floor, mirroring the
        // mat-view arm in WalPurgeJob.getSafeToPurgeUpToTxn. Invalidation is
        // terminal: there is no in-place revalidation path, the refresh worker
        // permanently skips an invalid view, and its lvConsumed / head checkpoint
        // would otherwise freeze forever - clamping safeToPurgeTxn to that frozen
        // value and blocking base WAL purging indefinitely while the base keeps
        // ingesting (unbounded WAL growth). Re-CREATE requires a DROP first and
        // seeds through an MVCC snapshot reader of the applied base table,
        // not the raw base WAL, so the retained WAL is never load-bearing.
        assertMemoryLeak(() -> {
            // Pin the clock past epoch + one purge interval so drainPurgeJob's
            // interval gate actually fires (a clock frozen at epoch skips every
            // sweep), but below the data so the view still materializes the rows.
            setCurrentMicros(MicrosTimestampDriver.floor("2026-05-31T00:00:00.000000Z"));
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");

            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);
            // Initial published floor for a non-SEED view is subscribeFromSeqTxn
            // - 1. The view never refreshes, so the floor stays at this value.
            long floorBefore = instance.getStateReader().getLvConsumedSeqTxn();
            Assert.assertTrue("LV must publish an initial floor", floorBefore > -1);

            // Two base commits land in separate segments, both above the LV's
            // floor and never consumed by the view. The purge only reaps a segment
            // once a later one exists, so segment 1 must be present for segment 0 to
            // become eligible.
            execute("INSERT INTO base (ts, x) VALUES ('2026-06-01T00:00:00.000000Z', 1)");
            drainWalQueue();
            engine.releaseInactive();
            execute("INSERT INTO base (ts, x) VALUES ('2026-06-01T00:01:00.000000Z', 2)");
            drainWalQueue();
            engine.releaseInactive();

            // While the view is still valid, its floor pins segment 0: the
            // unconsumed seqTxn sits above the floor, so the segment survives.
            drainPurgeJob();
            assertSegmentExistence(true, "base", 1, 0);

            // Invalidate the LV. The in-memory floor value is unchanged, but the
            // purge job now skips this view entirely.
            engine.invalidateLiveView(instance, "test retention floor");
            Assert.assertTrue("LV must be invalid", instance.isInvalid());
            Assert.assertEquals(
                    "invalidation does not move the LV's published floor",
                    floorBefore,
                    instance.getStateReader().getLvConsumedSeqTxn()
            );

            // Purge again: with the invalid view's floor released, safeToPurgeTxn
            // clamps only to the base head, so segment 0 is reaped. Were the floor
            // still held, the segment would survive as it did above.
            drainPurgeJob();
            assertSegmentExistence(false, "base", 1, 0);

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testInvalidationFreesRuntimeState() throws Exception {
        // An INVALID view frees its non-cursor-pinned runtime state (compiled
        // factory, anchor window, anchor function, in-mem tier) instead of
        // pinning it until DROP / shutdown. The view stays in the registry and
        // queryable from the on-disk tier.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, sym SYMBOL, x DOUBLE) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms IN MEMORY 1h START FROM NOW AS " +
                    "SELECT ts, sym, sum(x) OVER w AS s FROM base " +
                    "WINDOW w AS (PARTITION BY sym ORDER BY ts ANCHOR EXPRESSION timestamp_floor('1d', ts))");
            execute("INSERT INTO base (ts, sym, x) VALUES " +
                    "('2026-11-01T00:00:10.000000Z', 'a', 1.0), " +
                    "('2026-11-01T00:00:20.000000Z', 'a', 2.0)");
            drainWalQueue();

            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }

            // After a refresh the anchored LV holds all four runtime-state fields.
            Assert.assertNotNull("compiled factory populated after refresh", instance.getCompiledFactory());
            Assert.assertNotNull("anchor window populated after refresh", instance.getAnchorWindow());
            Assert.assertNotNull("anchor function populated after refresh", instance.getAnchorFunction());
            Assert.assertNotNull("in-mem tier populated after refresh", instance.getInMemoryTier());

            // Invalidate. The unified path frees the runtime state.
            engine.invalidateLiveView(instance, "test free runtime state");
            Assert.assertTrue("view must be invalid", instance.isInvalid());
            Assert.assertNull("invalidation frees the compiled factory", instance.getCompiledFactory());
            Assert.assertNull("invalidation frees the anchor window", instance.getAnchorWindow());
            Assert.assertNull("invalidation frees the anchor function", instance.getAnchorFunction());
            Assert.assertNull("invalidation frees the in-mem tier", instance.getInMemoryTier());

            // The view stays queryable from the on-disk tier and reports INVALID.
            assertQuery("SELECT ts, sym, s FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns("ts\tsym\ts\n" +
                    "2026-11-01T00:00:10.000000Z\ta\t1.0\n" +
                    "2026-11-01T00:00:20.000000Z\ta\t3.0\n");
            assertQuery("SELECT view_status FROM live_views() WHERE view_name = 'lv'").noLeakCheck().noRandomAccess().returns("view_status\n" +
                    "invalid\n");

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testLiveViewAheadOfBaseInvalidates() throws Exception {
        // A role migration onto a partially-uploaded object store can leave a live view's durable
        // watermark (last_processed_seqtxn) ahead of the base seqTxn that actually replicated: the
        // ex-primary flushed + uploaded derived rows for base commits whose own base-table WAL upload
        // lagged and was cut, and a replica applied that LIVE_VIEW_DATA -- advancing _lv.s via
        // CairoEngine.applyLiveViewData -- without ever holding the base beyond what replicated. The base
        // can never reach that seqTxn, so the promoted primary's refresh must invalidate the view rather
        // than sit active forever serving derived rows for base commits it no longer holds, mirroring the
        // mat-view "view is ahead of base table and cannot be synchronized" guard. Drives
        // applyLiveViewData directly -- the same call the replica apply job makes -- to construct the
        // ahead state without an object store.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x LONG, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");
            execute("INSERT INTO base (ts, x) VALUES ('2026-06-01T00:00:01.000000Z', 1), ('2026-06-01T00:00:02.000000Z', 2)");
            drainWalQueue();

            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            Assert.assertFalse("view active after catching up to the base", instance.isInvalid());

            final TableToken baseToken = engine.verifyTableName("base");
            final long baseHead = engine.getTableSequencerAPI().lastTxn(baseToken);
            // Force _lv.s ahead of the base head: simulate a replica having applied a LIVE_VIEW_DATA block
            // whose base seqTxn (baseHead + 3) this node's base never received.
            final long aheadSeqTxn = baseHead + 3;
            final TableToken lvToken = engine.verifyTableName("lv");
            try (
                    BlockFileWriter w = new BlockFileWriter(engine.getConfiguration().getFilesFacade(), engine.getConfiguration().getCommitMode());
                    Path path = new Path()
            ) {
                engine.applyLiveViewData(lvToken, aheadSeqTxn, w, path);
            }
            Assert.assertEquals("watermark now ahead of the base head", aheadSeqTxn, instance.getLastProcessedSeqTxn());

            // The promote-hydrate guard in scanForLaggingViews must invalidate the ahead view.
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            Assert.assertTrue("a live view ahead of its base must be invalidated", instance.isInvalid());
            TestUtils.assertContains(instance.getInvalidationReason(), "ahead of base table");
            assertQuery("SELECT view_status FROM live_views() WHERE view_name = 'lv'")
                    .noLeakCheck().noRandomAccess().returns("view_status\ninvalid\n");

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testWriterStallWhenBothSlotsPinned() throws Exception {
        // When both slots are reader-pinned, the
        // slow-path tryAcquireWrite returns null and the refresh worker
        // records the start of the stall streak. writer_stall_micros surfaces
        // the duration via live_views(). We pin both slots through the test
        // by manipulating the tier directly, then run a refresh — the in-mem
        // populate path stalls but the on-disk apply still advances.
        // Force slow-path on every cycle (growth=0 disables fast-path) so the
        // setup's "publishedIdx flipped after each cycle" precondition holds.
        setProperty(PropertyKey.CAIRO_LIVE_VIEW_IN_MEMORY_BUFFER_GROWTH_BYTES, 0);
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms IN MEMORY 5s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");

            // Seed the tier via an initial refresh so both slots have valid
            // shapes (the second slot is allocated but never written-to without
            // this seed; the test pins the seeded slot + the other one).
            setCurrentMicros(0L);
            execute("INSERT INTO base (ts, x) VALUES ('2026-05-12T00:00:00.000001Z', 1)");
            drainWalQueue();
            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
                LiveViewInMemoryTier tier = instance.getInMemoryTier();
                Assert.assertNotNull(tier);
                int publishedAfterSeed = tier.getPublishedIdx();

                // A second cycle so both slots have been writer-touched
                // (publishedIdx flips on each swap, so this seeds the
                // currently-non-published slot).
                setCurrentMicros(200_000L);
                execute("INSERT INTO base (ts, x) VALUES ('2026-05-12T00:00:00.000002Z', 2)");
                drainWalQueue();
                drainJob(job);
                Assert.assertNotEquals("publishedIdx flipped after second cycle",
                        publishedAfterSeed, tier.getPublishedIdx());

                // Pin both slots — first the currently-published one, then
                // flip publishedIdx via a noop pseudo-publish (we just pin
                // both). Standard usage doesn't expose this state, but the
                // test mirrors what concurrent long readers do in production.
                int pinA = tier.acquireRead();
                int pinB;
                // Force a "phantom" reader on the OTHER slot by manipulating
                // publishedIdx via a write+swap cycle while still pinning A.
                // The simplest way is: take write sentinel on otherIdx, swap,
                // then acquireRead on the now-current slot.
                int otherIdx = 1 - pinA;
                LiveViewInMemoryBuffer otherWrite = tier.tryAcquireWrite(otherIdx);
                Assert.assertNotNull("seed write on other slot must succeed", otherWrite);
                tier.publishSwap(otherIdx);
                pinB = tier.acquireRead();
                Assert.assertEquals("pinB must land on the now-published slot",
                        otherIdx, pinB);

                try {
                    // Now both slots are reader-pinned. A new refresh cycle
                    // cannot take the writer sentinel on either. The on-disk
                    // tier still advances; only the in-mem swap stalls.
                    Assert.assertEquals("writer_stall_micros must start at 0",
                            Numbers.LONG_NULL, instance.getWriterStallStartUs());

                    setCurrentMicros(500_000L);
                    execute("INSERT INTO base (ts, x) VALUES ('2026-05-12T00:00:00.000003Z', 3)");
                    drainWalQueue();
                    drainJob(job);

                    Assert.assertEquals(
                            "writerStallStartUs must equal the wall-clock at refresh time",
                            500_000L,
                            instance.getWriterStallStartUs()
                    );

                    // live_views() must surface the stall duration (now - stallStart).
                    setCurrentMicros(700_000L);
                    assertQuery("SELECT writer_stall_micros FROM live_views() WHERE view_name = 'lv'").noLeakCheck().noRandomAccess().returns("writer_stall_micros\n200000\n");
                } finally {
                    tier.releaseRead(pinA);
                    tier.releaseRead(pinB);
                }
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testInMemEvictionPastInMemoryWindow() throws Exception {
        // Rows whose ts falls below latest - IN_MEMORY are
        // not copied into the new write slot during the slow-path swap. With
        // IN MEMORY 100ms and a 200ms gap between the two inserts (data ts),
        // the first row's ts is below the eviction threshold by the time the
        // second refresh cycle runs, so only the second row survives.
        // IN_MEMORY eviction runs on slow-path edges only — the
        // fast-path append leaves prior rows intact regardless of age. Force
        // slow-path (growth=0) to exercise the eviction policy.
        setProperty(PropertyKey.CAIRO_LIVE_VIEW_IN_MEMORY_BUFFER_GROWTH_BYTES, 0);
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms IN MEMORY 100ms START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");

            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                setCurrentMicros(0L);
                execute("INSERT INTO base (ts, x) VALUES ('2026-05-12T00:00:00.000000Z', 1)");
                drainWalQueue();
                drainJob(job);

                LiveViewInMemoryTier tier = instance.getInMemoryTier();
                Assert.assertNotNull(tier);
                Assert.assertEquals("first cycle: one row in tier", 1, tier.getSlot(tier.getPublishedIdx()).rowCount());

                // Second insert: data ts 200ms after the first, so latest -
                // IN_MEMORY = +100ms is past the first row's ts. Advance the
                // wall clock by 200ms so the FLUSH EVERY 100ms gate passes.
                setCurrentMicros(200_000L);
                execute("INSERT INTO base (ts, x) VALUES ('2026-05-12T00:00:00.200000Z', 2)");
                drainWalQueue();
                drainJob(job);

                LiveViewInMemoryBuffer published = tier.getSlot(tier.getPublishedIdx());
                Assert.assertEquals("post-second-cycle: only the new row survives", 1, published.rowCount());
                Assert.assertEquals("surviving row is the second insert", 2, published.getInt(0, 1));
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testEvictionRetainsAgedUnflushedLead() throws Exception {
        // The load-bearing eviction clamp: a slot's trailing leadRowCount rows are
        // the un-flushed lead (refreshed into RAM but not yet on the LV's on-disk
        // tier), which have no durable disk copy, so they must never age out - even
        // when their ts falls below latest - IN MEMORY. Only the overlap (rows
        // already on disk) ages. growth.bytes = 0 forces the slow-path swap on
        // every publish so the eviction runs each cycle.
        setProperty(PropertyKey.CAIRO_LIVE_VIEW_IN_MEMORY_BUFFER_GROWTH_BYTES, 0);
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            // Pin the CREATE-moment wall clock below the data so every row is in
            // frame. With the wall clock frozen at 0, no flush fires after the first
            // cycle (IN MEMORY must be >= FLUSH EVERY, so both are 100ms), and the
            // second and third refreshes accumulate the lead in RAM. The data spans
            // more than 100ms, so the earliest lead row ends up below the IN MEMORY
            // window while still un-flushed - exactly the case the clamp protects.
            setCurrentMicros(0L);
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms IN MEMORY 100ms START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");

            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                // Cycle 1: the first tick flushes row A to disk (it becomes overlap).
                execute("INSERT INTO base (ts, x) VALUES ('2026-05-12T00:00:00.000000Z', 1)");
                drainWalQueue();
                drainJob(job);

                // Refresh B as the lead: within FLUSH EVERY (clock still 0), so it
                // publishes to the tier without flushing. B's ts keeps A in the
                // IN MEMORY window, so the slow-path retains both.
                execute("INSERT INTO base (ts, x) VALUES ('2026-05-12T00:00:00.050000Z', 2)");
                drainWalQueue();
                drainJob(job);

                // Refresh C as the lead. Now latest - IN MEMORY = C.ts - 100ms sits
                // above both A and B: A (overlap, on disk) ages out, but B (lead,
                // un-flushed) is below the window yet must be retained.
                execute("INSERT INTO base (ts, x) VALUES ('2026-05-12T00:00:00.200000Z', 3)");
                drainWalQueue();
                drainJob(job);

                LiveViewInMemoryTier tier = instance.getInMemoryTier();
                Assert.assertNotNull(tier);
                LiveViewInMemoryBuffer published = tier.getSlot(tier.getPublishedIdx());
                Assert.assertEquals(
                        "aged durable overlap evicted; both un-flushed lead rows retained",
                        2,
                        published.rowCount()
                );
                Assert.assertEquals("both retained rows are the un-flushed lead", 2, published.leadRowCount());
                Assert.assertEquals("oldest retained row is the aged lead row B", 2, published.getInt(0, 1));
                Assert.assertEquals("newest retained row is C", 3, published.getInt(1, 1));
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testInMemFootprintPlateausUnderGrowthBudget() throws Exception {
        // Under a NON-ZERO growth budget the refresh worker appends to the
        // published slot via the fast-path and defers the slow-path
        // evict-and-swap until a growth-budget's worth of AGED, reclaimable
        // overlap has piled up (isCompactionWorthwhile). Each cycle's rows flush
        // to disk (become overlap) and, spaced 2s apart under a 1s IN MEMORY
        // window, age out; the fast-path holds them in place until roughly
        // growth.bytes / approxRowSizeBytes aged rows accumulate, then a single
        // slow-path swap evicts them. So the published slot oscillates between a
        // fresh cycle and ~a growth-budget's worth of aged overlap, and its peak
        // is bounded by the growth budget in rows plus one cycle - NOT by IN
        // MEMORY or by the number of rows ingested.
        //
        // footprintBytes() sums ALLOCATED column pages and reset() retains them,
        // so a slot's footprint is a monotonic high-water mark. Once both N=2
        // slots have each reached their bounded peak the tier footprint plateaus
        // and never grows again, however many more rows are ingested. That
        // decoupling of RAM from ingested volume is the no-leak property under
        // test.
        //
        // The shipped defaults (64 KiB initial page / 16 MiB growth) would need
        // millions of rows to cross, so this test scales both budgets down to
        // exercise the same fills-then-evicts regime cheaply. Every other
        // eviction test forces growth.bytes = 0, which takes the slow-path on
        // every cycle and so never enters this regime.
        final long initialBytes = 4 * 1024;  // per-column page granule
        final long growthBytes = 64 * 1024;  // slow-path growth backstop
        setProperty(PropertyKey.CAIRO_LIVE_VIEW_IN_MEMORY_BUFFER_INITIAL_BYTES, initialBytes);
        setProperty(PropertyKey.CAIRO_LIVE_VIEW_IN_MEMORY_BUFFER_GROWTH_BYTES, growthBytes);
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            // Pin the CREATE-moment wall clock at 0 so the view's lower bound
            // sits well below the data timestamps, keeping every row in-frame.
            setCurrentMicros(0L);
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms IN MEMORY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");

            // Data timestamps: a fixed positive epoch (the exact calendar date
            // is irrelevant, only that it is above the floor of 0). Each cycle's
            // rows are spaced 2s after the prior cycle's, comfortably beyond the
            // 1s IN MEMORY window, so the slow-path evicts the previous cycle's
            // rows and the published slot retains only the current cycle.
            final long dataStart = 1_700_000_000_000_000L;
            final long rowsPerCycle = 1024;
            final long cycleSpanMicros = 2_000_000L;

            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                long wallMicros = 0L;
                int cycle = 0;

                // Warm-up: drive enough cycles to push both slots past the
                // growth budget. Crossing needs ~3 cycles per slot and both
                // slots saturate by ~cycle 9; 20 cycles clears it with margin.
                final int warmCycles = 20;
                for (; cycle < warmCycles; cycle++) {
                    long base = dataStart + cycle * cycleSpanMicros;
                    execute("INSERT INTO base (ts, x) SELECT (" + base + " + x)::timestamp, x::int FROM long_sequence(" + rowsPerCycle + ")");
                    drainWalQueue();
                    wallMicros += 250_000L; // > FLUSH EVERY 100ms so the flush fires each cycle
                    setCurrentMicros(wallMicros);
                    drainJob(job);
                }

                LiveViewInMemoryTier tier = instance.getInMemoryTier();
                Assert.assertNotNull("tier must be allocated after refreshes", tier);
                long warmFootprint = tier.footprintBytes();

                // The fast-path actually filled past the budget (this is NOT the
                // growth=0 slow-path-only regime), and both slots saturated.
                Assert.assertTrue(
                        "footprint must cross the growth budget [footprint=" + warmFootprint + ", growth=" + growthBytes + "]",
                        warmFootprint >= growthBytes
                );
                // Bounded near ~2 x growth.bytes. The generous 8x ceiling still
                // rules out growth proportional to the ~20k rows ingested, which
                // with no eviction would exceed 1 MiB.
                Assert.assertTrue(
                        "footprint must stay bounded by a small multiple of the growth budget [footprint=" + warmFootprint + "]",
                        warmFootprint <= 8 * growthBytes
                );

                // RAM is growth-bound, not IN-MEMORY- or data-volume-bound: the
                // published slot retains at most a growth-budget's worth of aged
                // overlap plus the freshest cycle appended on top before the next
                // compaction - far below the ~40k rows ingested. The bound tracks
                // the gate's own math: budgetRows = growth.bytes / approxRowSize.
                long approxRowSize = tier.getSlot(tier.getPublishedIdx()).approxRowSizeBytes();
                long maxRetainedRows = growthBytes / approxRowSize + rowsPerCycle;
                long publishedRows = tier.getSlot(tier.getPublishedIdx()).rowCount();
                Assert.assertTrue(
                        "published slot must retain only a growth-budget window, not all ingested rows"
                                + " [rows=" + publishedRows + ", bound=" + maxRetainedRows + "]",
                        publishedRows <= maxRetainedRows
                );

                // Plateau: many more cycles must NOT grow the footprint. Pages
                // are a monotonic high-water mark and the slow-path refills
                // within them, so the value is exactly stable. This is the
                // no-leak / bounded proof: footprint is decoupled from the
                // (ever growing) ingested row count.
                final int plateauCycles = 20;
                for (int i = 0; i < plateauCycles; i++, cycle++) {
                    long base = dataStart + cycle * cycleSpanMicros;
                    execute("INSERT INTO base (ts, x) SELECT (" + base + " + x)::timestamp, x::int FROM long_sequence(" + rowsPerCycle + ")");
                    drainWalQueue();
                    wallMicros += 250_000L;
                    setCurrentMicros(wallMicros);
                    drainJob(job);
                }

                long lateFootprint = tier.footprintBytes();
                Assert.assertEquals(
                        "footprint must plateau once both slots cross the growth budget (no unbounded growth)",
                        warmFootprint, lateFootprint
                );

                // live_views().in_mem_bytes surfaces the same bounded footprint.
                assertQuery("SELECT in_mem_bytes FROM live_views() WHERE view_name = 'lv'")
                        .noLeakCheck().noRandomAccess()
                        .returns("in_mem_bytes\n" + lateFootprint + "\n");

                // in_mem_rows tracks the live logical content, not the arena
                // capacity: it stays at the small retained window (one cycle),
                // decoupled from the plateaued footprint. This is the pairing that
                // lets an operator tell a view actively buffering rows from one
                // holding capacity retained from a past burst.
                long liveRows = tier.publishedRowCount();
                Assert.assertTrue(
                        "published row count must stay within the growth-budget window [rows=" + liveRows + ", bound=" + maxRetainedRows + "]",
                        liveRows <= maxRetainedRows
                );
                assertQuery("SELECT in_mem_rows FROM live_views() WHERE view_name = 'lv'")
                        .noLeakCheck().noRandomAccess()
                        .returns("in_mem_rows\n" + liveRows + "\n");
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testLiveViewsExposesInMemBytes() throws Exception {
        // in_mem_bytes reports the
        // current footprint of both N=2 slots. Zero before any refresh; > 0
        // in_mem_bytes reports the
        // current footprint of both N=2 slots. Zero before any refresh; > 0
        // once a refresh has populated the tier.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");

            // Before any refresh: tier is unallocated; in_mem_bytes must read 0.
            assertQuery("SELECT in_mem_bytes FROM live_views() WHERE view_name = 'lv'").noLeakCheck().noRandomAccess().returns("in_mem_bytes\n0\n");

            execute("INSERT INTO base (ts, x) VALUES " +
                    "('2026-05-12T00:00:00.000001Z', 1), " +
                    "('2026-05-12T00:00:00.000002Z', 2)");
            drainWalQueue();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }

            // After refresh, the tier is non-empty and footprint must be > 0.
            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);
            Assert.assertNotNull("tier must be allocated after refresh", instance.getInMemoryTier());
            long footprint = instance.getInMemoryTier().footprintBytes();
            Assert.assertTrue("footprint must be > 0 after a refresh", footprint > 0);
            assertQuery("SELECT in_mem_bytes FROM live_views() WHERE view_name = 'lv'").noLeakCheck().noRandomAccess().returns("in_mem_bytes\n" + footprint + "\n");

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testLiveViewsExposesInMemRows() throws Exception {
        // in_mem_rows reports the live row count of the published slot - the
        // logical content of the in-mem tier, the companion to the peak-sticky
        // in_mem_bytes footprint. Zero before any refresh allocates the tier;
        // equals the published slot's rowCount once a refresh has populated it.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");

            // Before any refresh: tier is unallocated; in_mem_rows must read 0.
            assertQuery("SELECT in_mem_rows FROM live_views() WHERE view_name = 'lv'").noLeakCheck().noRandomAccess().returns("in_mem_rows\n0\n");

            // Two rows match the WHERE filter; a third is filtered out.
            execute("INSERT INTO base (ts, x) VALUES " +
                    "('2026-05-12T00:00:00.000001Z', 1), " +
                    "('2026-05-12T00:00:00.000002Z', 2), " +
                    "('2026-05-12T00:00:00.000003Z', -1)");
            drainWalQueue();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }

            // After refresh, in_mem_rows equals the published slot's rowCount.
            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);
            LiveViewInMemoryTier tier = instance.getInMemoryTier();
            Assert.assertNotNull("tier must be allocated after refresh", tier);
            long liveRows = tier.publishedRowCount();
            Assert.assertEquals("only the two filter-matching rows are held in memory", 2, liveRows);
            assertQuery("SELECT in_mem_rows FROM live_views() WHERE view_name = 'lv'").noLeakCheck().noRandomAccess().returns("in_mem_rows\n" + liveRows + "\n");

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testInMemTierReceivesRowsAfterRefresh() throws Exception {
        // Refresh worker mirrors LV outputs into a worker-local
        // staging buffer and runs a slow-path swap into the LV's N=2 in-mem
        // tier after the inline apply commits. Two rows match the WHERE
        // filter; both must show up in the published slot, in ts-ascending
        // order, with seamTs = the lowest ts.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s IN MEMORY 5s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");
            execute("INSERT INTO base (ts, x) VALUES " +
                    "('2026-05-12T00:00:00.000001Z', 1), " +
                    "('2026-05-12T00:00:00.000002Z', 2), " +
                    "('2026-05-12T00:00:00.000003Z', -1)");
            drainWalQueue();

            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            LiveViewInMemoryTier tier = instance.getInMemoryTier();
            Assert.assertNotNull("in-mem tier must be allocated after refresh", tier);
            LiveViewInMemoryBuffer published = tier.getSlot(tier.getPublishedIdx());
            Assert.assertEquals("published slot must have two rows", 2, published.rowCount());
            // ts column is col 0; matches the LV's designated ts.
            long ts0 = published.getLong(0, 0);
            long ts1 = published.getLong(1, 0);
            Assert.assertTrue("rows must be ordered by ts", ts0 < ts1);
            Assert.assertEquals("seamTs must equal the lowest retained ts", ts0, published.seamTs());
            // x column is col 1 — survived the WHERE filter (x > 0)
            Assert.assertEquals(1, published.getInt(0, 1));
            Assert.assertEquals(2, published.getInt(1, 1));
            // row_number outputs at col 2 — the SELECT's third column
            Assert.assertEquals(1L, published.getLong(0, 2));
            Assert.assertEquals(2L, published.getLong(1, 2));

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test(timeout = 120_000)
    public void testO3ReplayDefersOnBaseApplyLagInsteadOfDeadlocking() throws Exception {
        // Cooperative apply-lag handoff (regression for the LiveViewFuzzTest
        // waitForApply self-deadlock). When a lead refresh detects an O3 base
        // commit whose seqTxn ApplyWal2TableJob has not applied yet, the O3
        // replay must NOT block-spin in waitForApply waiting for the apply: on
        // the single-threaded drain model the same thread has to advance that
        // apply, so spinning deadlocks (and, with the flush clock frozen, the
        // retry budget never trips). Instead ensureBaseApplied throws a
        // cooperative signal that unwinds the cycle untouched - no watermark
        // advance, no lead discard, no invalidation - and the next tick retries
        // once the base apply lands, converging on the correct result.
        assertMemoryLeak(() -> {
            setCurrentMicros(MicrosTimestampDriver.floor("2026-01-01T00:00:00.000000Z"));
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms IN MEMORY 60s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");
            final LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                // Establish the in-RAM lead and the O3 detection watermark from
                // three strictly in-order rows. Pin lastFlushTimeUs to the frozen
                // clock so FLUSH EVERY does not fire this cycle - the lead stays
                // in RAM, so the apply-lag path below has a real lead to preserve.
                execute("INSERT INTO base (ts, x) VALUES " +
                        "('2026-06-01T00:00:00.000010Z', 1), " +
                        "('2026-06-01T00:00:00.000020Z', 2), " +
                        "('2026-06-01T00:00:00.000030Z', 3)");
                drainWalQueue();
                instance.setLastFlushTimeUs(currentMicros);
                drainJob(job);
                Assert.assertEquals("lead must accumulate in RAM", 3L, instance.getLeadRowCount());

                final long leadBefore = instance.getLeadRowCount();
                final long processedBefore = instance.getLastProcessedSeqTxn();
                final long refreshedBefore = instance.getRefreshedUpToSeqTxn();
                final long latestSeenBefore = instance.getLatestSeenTs();

                // Commit an out-of-order row BELOW the frontier but do NOT apply
                // it to the base table (skip drainWalQueue): the base sequencer
                // head advances while the applied base reader lags the O3 seqTxn.
                execute("INSERT INTO base (ts, x) VALUES ('2026-06-01T00:00:00.000005Z', 4)");

                // The refresh detects the O3 commit and takes the replay path,
                // whose ensureBaseApplied gate observes the apply lag and unwinds
                // cooperatively. With the old block-spin this call never returns
                // (the frozen clock keeps the retry budget from tripping). It must
                // return, and it must leave the view exactly as it was.
                drainJob(job);

                Assert.assertFalse("apply lag must not invalidate the view", instance.isInvalid());
                Assert.assertEquals("lead must survive the deferred replay", leadBefore, instance.getLeadRowCount());
                Assert.assertEquals("watermark must not advance on apply lag", processedBefore, instance.getLastProcessedSeqTxn());
                Assert.assertEquals("refresh cursor must not advance on apply lag", refreshedBefore, instance.getRefreshedUpToSeqTxn());
                // The single O3 commit trips detection before any in-cycle latestSeenTs
                // bump, so the watermark is simply left untouched here; the drainBaseWal
                // rollback of in-cycle bumps is exercised by the multi-commit O3 tests.
                Assert.assertEquals("O3 detection watermark must not advance on apply lag", latestSeenBefore, instance.getLatestSeenTs());

                // Apply the base commit, advance the clock past the apply-lag
                // back-off, then let the next tick converge the replay.
                drainWalQueue();
                setCurrentMicros(currentMicros + 1_000_000);
                drainJob(job);
                drainWalQueue();
                Assert.assertFalse("view must stay valid after the replay converges", instance.isInvalid());
            }

            // The O3 row lands in ts order with a gapless row_number sequence.
            assertQuery("SELECT ts, x, rn FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns("ts\tx\trn\n" +
                    "2026-06-01T00:00:00.000005Z\t4\t1\n" +
                    "2026-06-01T00:00:00.000010Z\t1\t2\n" +
                    "2026-06-01T00:00:00.000020Z\t2\t3\n" +
                    "2026-06-01T00:00:00.000030Z\t3\t4\n");

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testRefreshDefersWhenLiveViewApplyBackedOff() throws Exception {
        // The refresh worker drives the view's OWN WAL apply inline (applyWalDirect)
        // after committing a flushed lead. When that apply is backed off under memory
        // pressure it silently no-ops at ApplyWal2TableJob's isReadyToProcess gate, so a
        // flush this cycle would commit rows to the LV WAL that never reach disk while the
        // tier is stamped as if they had -- size()/count()/LIMIT would then undercount
        // them until the pressure eased. refreshInstance must instead defer the whole
        // cycle while the LV apply is backed off, leaving the last published lead in RAM,
        // and converge once the pressure eases. Deleting the pre-latch readiness guard
        // lets the backed-off cycle advance the watermark over an un-applied commit, which
        // the watermark assertion below catches.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (val INT, ts TIMESTAMP, pg SYMBOL) TIMESTAMP(ts) PARTITION BY HOUR WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT val, ts, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");
            final LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                // Fully refresh and flush a first row so the LV table exists on disk with
                // an established watermark.
                execute("INSERT INTO base (val, ts) VALUES (10, '2026-01-01T00:00:01.000000Z')");
                drainWalQueue();
                setCurrentMicros(2_000_000L);
                drainJob(job);
                drainWalQueue();

                final long processedBefore = instance.getLastProcessedSeqTxn();
                final TableWriterPressureControl lvPressure = engine.getTableSequencerAPI()
                        .getTxnTracker(instance.getLiveViewToken()).getMemPressureControl();

                // Advance past FLUSH EVERY first, then back off the LV apply AT this frozen
                // clock, exactly as a prior OOM apply would. Arming at the current tick makes
                // the back-off floor (now + a randomised delay) strictly future-dated, so the
                // deferral is deterministic regardless of the random delay.
                setCurrentMicros(4_000_000L);
                lvPressure.onOutOfMemory();
                Assert.assertFalse("test setup: LV apply must be backed off", lvPressure.isReadyToProcess());

                // A second base row arrives and is applied to the base. A normal cycle
                // would drain it, flush, and inline-apply -- but the inline apply is backed
                // off, so the cycle must defer rather than commit a row that cannot reach
                // disk. The durable watermark must not advance.
                execute("INSERT INTO base (val, ts) VALUES (20, '2026-01-01T00:00:02.000000Z')");
                drainWalQueue();
                drainJob(job);
                Assert.assertEquals("a backed-off LV apply must defer the refresh, not advance the watermark",
                        processedBefore, instance.getLastProcessedSeqTxn());
                Assert.assertFalse("the deferral must not invalidate the view", instance.isInvalid());

                // Ease the memory pressure and let the next tick converge.
                lvPressure.onEnoughMemory();
                setCurrentMicros(6_000_000L);
                drainJob(job);
                drainWalQueue();
                Assert.assertFalse("the view must stay valid after convergence", instance.isInvalid());
            }
            // Both rows land in ts order with a gapless row_number sequence.
            assertQuery("SELECT val, ts, rn FROM lv ORDER BY ts")
                    .noLeakCheck()
                    .timestamp("ts")
                    .expectSize()
                    .returns("val\tts\trn\n" +
                            "10\t2026-01-01T00:00:01.000000Z\t1\n" +
                            "20\t2026-01-01T00:00:02.000000Z\t2\n");
            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testReadReopensDiskWhenSlotAdvancesDuringCursorOpen() throws Exception {
        // Regression for the reader-visible view shrink (LiveViewFuzzTest
        // reader-vs-refresh). A cursor opens its disk (LV-table) snapshot before it
        // pins the tier slot; a flush landing in that window advances the on-disk
        // tier and republishes the slot with the newer seqTxn, so the disk snapshot
        // ends up OLDER than the pinned slot. The seqTxn fence then disengages
        // (slot seqTxn != disk seqTxn) and the read serves disk-only against the
        // stale, smaller snapshot - dropping the un-flushed lead an earlier read
        // already showed, so the live view appears to shrink. The factory must
        // re-open the disk against a fresh snapshot when the slot is newer than the
        // disk. This test injects that exact flush through a one-shot hook that runs
        // between the disk open and the slot pin.
        assertMemoryLeak(() -> {
            setCurrentMicros(MicrosTimestampDriver.floor("2026-01-01T00:00:00.000000Z"));
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms IN MEMORY 60s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                // Flush an initial two rows so the LV table and the published slot
                // sit at a stable seqTxn (call it S1).
                execute("INSERT INTO base (ts, x) VALUES " +
                        "('2026-06-01T00:00:00.000010Z', 1), ('2026-06-01T00:00:00.000020Z', 2)");
                drainWalQueue();
                setCurrentMicros(currentMicros + 1_000_000);
                drainJob(job);
                drainWalQueue();

                // Stage two more base rows but refresh them into the LV only from
                // inside the hook - i.e. AFTER the reader opens its disk cursor at S1
                // and BEFORE it pins the slot. The flush advances the LV table and
                // republishes the slot to S2, so the reader's disk snapshot (S1) is
                // now older than the pinned slot (S2).
                execute("INSERT INTO base (ts, x) VALUES " +
                        "('2026-06-01T00:00:00.000030Z', 3), ('2026-06-01T00:00:00.000040Z', 4)");
                drainWalQueue();

                try (RecordCursorFactory factory = select("SELECT * FROM lv")) {
                    LiveViewRecordCursorFactory.setOnDiskCursorOpenedHook(() -> {
                        setCurrentMicros(currentMicros + 1_000_000);
                        drainJob(job);
                        drainWalQueue();
                    });
                    try (RecordCursor cursor = factory.getCursor(sqlExecutionContext)) {
                        long count = 0;
                        while (cursor.hasNext()) {
                            count++;
                        }
                        // With the staleness retry the read re-opens against the fresh
                        // S2 disk and returns all four rows. Without it the fence
                        // disengages to the stale S1 snapshot and the read returns only
                        // the pre-flush two.
                        Assert.assertEquals("read must reflect the flush that landed during cursor open", 4L, count);
                    } finally {
                        LiveViewRecordCursorFactory.setOnDiskCursorOpenedHook(null);
                    }
                }
            }
            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testCursorPinKeepsTierAliveAcrossDrop() throws Exception {
        // A reader
        // holding an in-mem tier pin must survive a concurrent DROP LIVE VIEW
        // without segfault. The tier's deferred-close protocol marks it
        // closed on DROP but keeps native memory alive until the last pin
        // drains. Without the protocol, tier.releaseRead after DROP would
        // dereference a freed Unsafe pointer.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s IN MEMORY 5s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");
            execute("INSERT INTO base (ts, x) VALUES ('2026-05-12T00:00:00.000001Z', 7)");
            drainWalQueue();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }

            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);
            LiveViewInMemoryTier tier = instance.getInMemoryTier();
            Assert.assertNotNull("tier must be allocated after refresh", tier);

            // Acquire a pin manually — stands in for a LiveViewRecordCursor
            // that opens before DROP and finishes its scan after.
            int pin = tier.acquireRead();
            Assert.assertTrue("acquireRead must succeed before DROP", pin >= 0);
            // Sanity: contents reachable while pinned.
            Assert.assertEquals(1L, tier.getSlot(pin).rowCount());
            Assert.assertEquals(7, tier.getSlot(pin).getInt(0, 1));

            // DROP LIVE VIEW now: liveViewRegistry.removeView -> markAsDropped ->
            // tryCloseIfDropped -> tier.close(). With deferred close the native
            // memory stays alive because the pin count is 1.
            execute("DROP LIVE VIEW lv");

            // Reader can still inspect the pinned slot — no use-after-free.
            Assert.assertEquals("pinned slot contents survive DROP",
                    7, tier.getSlot(pin).getInt(0, 1));
            // New acquires reject cleanly post-close.
            Assert.assertEquals("post-close acquireRead must return -1",
                    -1, tier.acquireRead());

            // Releasing the last pin triggers the actual native free.
            // assertMemoryLeak verifies no leak — the deferred-free path runs.
            tier.releaseRead(pin);
        });
    }

    @Test
    public void testLeadPublishFailureEmergencyFlushesToDisk() throws Exception {
        // When publishToInMemoryTier's slow-path swap throws mid-publish on the
        // lead path, the catch releases the writer sentinel and rethrows;
        // finishLeadRefresh recovers by flushing the just-drained rows straight to
        // disk (the emergency flush), so no row is lost and the window state stays
        // consistent (no re-drain that would double-advance the window functions).
        // The published slot is left intact and marked stale; a subsequent refresh
        // takes the freed sentinel, drops the stale slot, and rebuilds cleanly.
        // The publishSwap injection fires only on the slow-path, so force it with
        // growth.bytes = 0.
        setProperty(PropertyKey.CAIRO_LIVE_VIEW_IN_MEMORY_BUFFER_GROWTH_BYTES, 0);
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            setCurrentMicros(0L);
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms IN MEMORY 5s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");

            execute("INSERT INTO base (ts, x) VALUES ('2026-05-12T00:00:00.000001Z', 7)");
            drainWalQueue();
            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                // Cycle 1: flush row 7 to disk; the tier holds it as overlap.
                drainJob(job);

                LiveViewInMemoryTier tier = instance.getInMemoryTier();
                Assert.assertNotNull("tier must be allocated after first refresh", tier);
                int publishedBeforeFailure = tier.getPublishedIdx();
                LiveViewInMemoryBuffer pubSlotBeforeFailure = tier.getSlot(publishedBeforeFailure);
                Assert.assertEquals("first refresh seeded one row", 1, pubSlotBeforeFailure.rowCount());
                Assert.assertEquals(7, pubSlotBeforeFailure.getInt(0, 1));
                Assert.assertEquals("no retries before injection", 0, instance.getFlushRetryCount());

                // Cycle 2: arm a one-shot publishSwap failure. The lead publish
                // throws; finishLeadRefresh catches it and emergency-flushes row 13
                // to disk rather than re-draining it.
                tier.setFailNextPublishSwap(new RuntimeException("test: simulated mid-swap failure"));
                setCurrentMicros(200_000L);
                execute("INSERT INTO base (ts, x) VALUES ('2026-05-12T00:00:00.000002Z', 13)");
                drainWalQueue();
                drainJob(job);

                // The failed swap did not flip publishedIdx, and the
                // previously-published slot still holds its row (the publish wrote
                // to the other slot, then released the sentinel on the throw).
                Assert.assertEquals(
                        "publishedIdx must not flip after the failed swap",
                        publishedBeforeFailure,
                        tier.getPublishedIdx()
                );
                Assert.assertEquals(
                        "previously-published slot must still hold its row",
                        1,
                        tier.getSlot(tier.getPublishedIdx()).rowCount()
                );
                Assert.assertEquals(7, tier.getSlot(tier.getPublishedIdx()).getInt(0, 1));
                // The emergency flush recovered the cycle, so the retry budget did
                // not tick - the row landed on disk instead of being retried.
                Assert.assertEquals("emergency flush recovers without ticking the retry budget",
                        0, instance.getFlushRetryCount());

                // No data lost: the emergency flush put row 13 on disk, so both
                // rows are queryable.
                assertQuery("SELECT x, rn FROM lv ORDER BY ts").noLeakCheck().expectSize().returns("x\trn\n" +
                        "7\t1\n" +
                        "13\t2\n");

                // Cycle 3: a subsequent refresh succeeds (the sentinel was
                // released, no deadlock), drops the stale slot, and rebuilds. All
                // three rows are present and correctly sequenced - no corruption
                // from a double-advanced window.
                setCurrentMicros(400_000L);
                execute("INSERT INTO base (ts, x) VALUES ('2026-05-12T00:00:00.000003Z', 21)");
                drainWalQueue();
                drainJob(job);
                assertQuery("SELECT x, rn FROM lv ORDER BY ts").noLeakCheck().expectSize().returns("x\trn\n" +
                        "7\t1\n" +
                        "13\t2\n" +
                        "21\t3\n");
                Assert.assertEquals(0, instance.getFlushRetryCount());
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testSqlCursorPinKeepsTierAliveAcrossDrop() throws Exception {
        // A SQL
        // RecordCursor opened against an LV pins the in-mem tier slot for its
        // lifetime; concurrent DROP LIVE VIEW marks the tier closed but
        // deferred-frees native memory until the cursor releases. The unit-
        // adjacent test testCursorPinKeepsTierAliveAcrossDrop drives the pin
        // directly through the tier API; this smoke test exercises the same
        // contract through the SQL path that production cursors take
        // (LiveViewRecordCursorFactory.getCursor -> LiveViewRecordCursor.of
        // -> tier.acquireRead, then on close -> tier.releaseRead).
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s IN MEMORY 5s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");
            execute("INSERT INTO base (ts, x) VALUES " +
                    "('2026-05-12T00:00:00.000001Z', 4), " +
                    "('2026-05-12T00:00:00.000002Z', 9)");
            drainWalQueue();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }

            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);
            LiveViewInMemoryTier tier = instance.getInMemoryTier();
            Assert.assertNotNull("tier must be allocated after refresh", tier);

            // Open the cursor via the SQL path. LiveViewRecordCursorFactory
            // wraps the disk factory and pins the tier slot at getCursor; the
            // pin survives until cursor.close().
            try (RecordCursorFactory factory = select("SELECT x FROM lv ORDER BY ts")) {
                RecordCursor cursor = factory.getCursor(sqlExecutionContext);
                try {
                    // Consume the first row to confirm the cursor is live.
                    Assert.assertTrue("cursor must yield first row", cursor.hasNext());
                    Record record = cursor.getRecord();
                    Assert.assertEquals(4, record.getInt(0));

                    // DROP while the cursor is mid-scan. Registry-level
                    // visibility is gone immediately; the tier is marked
                    // closed but native memory is held by the cursor's pin.
                    execute("DROP LIVE VIEW lv");

                    // A fresh acquireRead after DROP must reject cleanly.
                    Assert.assertEquals(
                            "post-DROP acquireRead must return -1",
                            -1,
                            tier.acquireRead()
                    );

                    // The cursor still works: the disk-side TableReader holds
                    // its partition versions independently of the LV
                    // registry, and DROP defers physical deletion until all
                    // readers release.
                    Assert.assertTrue("cursor must yield second row after DROP", cursor.hasNext());
                    Assert.assertEquals(9, record.getInt(0));
                    Assert.assertFalse("cursor must terminate after the second row", cursor.hasNext());
                } finally {
                    // Closing the cursor releases the tier pin; deferred-free
                    // runs because no other reader holds the tier. assertMemoryLeak
                    // verifies the native refcount block and column buffers are
                    // ultimately freed.
                    cursor.close();
                }
            }
        });
    }

    @Test
    public void testReadClonedSymbolTableResolvesSymbols() throws Exception {
        // newSymbolTable(int) on the LV read cursor must return a usable
        // symbol-table clone (the contract a parallel cursor consumer relies
        // on), not the throwing default. The cursor delegates the clone to the
        // disk cursor, which holds the LV table's symbol map; the same map also
        // resolves the in-mem tier's raw symbol ids (see getSymA), so a clone
        // is valid for either tier.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, sym SYMBOL, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, sym, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");
            execute("INSERT INTO base (ts, sym, x) VALUES " +
                    "('2026-04-01T00:00:00.000000Z', 'aapl', 1), " +
                    "('2026-04-01T00:00:01.000000Z', 'msft', 2), " +
                    "('2026-04-01T00:00:02.000000Z', 'aapl', 3), " +
                    "('2026-04-01T00:00:03.000000Z', 'goog', 4)");
            drainWalQueue();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            drainWalQueue();

            final int symCol = 1;
            try (
                    RecordCursorFactory factory = select("SELECT ts, sym, x, rn FROM lv ORDER BY ts");
                    RecordCursor cursor = factory.getCursor(sqlExecutionContext)
            ) {
                final SymbolTable clone = cursor.newSymbolTable(symCol);
                Assert.assertNotNull("newSymbolTable must return a clone, not null", clone);

                final SymbolTable live = cursor.getSymbolTable(symCol);
                final Record record = cursor.getRecord();
                int probeKey = SymbolTable.VALUE_NOT_FOUND;
                String probeValue = null;
                int rows = 0;
                while (cursor.hasNext()) {
                    final int key = record.getInt(symCol);
                    // The clone resolves the same value the record reports and
                    // the cursor's own (live) symbol table reports.
                    TestUtils.assertEquals(record.getSymA(symCol), clone.valueOf(key));
                    TestUtils.assertEquals(live.valueOf(key), clone.valueOf(key));
                    if (probeValue == null) {
                        probeKey = key;
                        probeValue = Chars.toString(record.getSymA(symCol));
                    }
                    rows++;
                }
                Assert.assertEquals(4, rows);

                // The clone is independent of the cursor's iteration state: it
                // still resolves keys after the cursor is exhausted, which is
                // exactly what a concurrent consumer relies on.
                TestUtils.assertEquals(probeValue, clone.valueOf(probeKey));
            }
            execute("DROP LIVE VIEW lv");
        });
    }

