    @Test
    public void testFirstValueIgnoreNullsWrappedRangeRingSurvivesRestart() throws Exception {
        // The IGNORE NULLS RANGE accumulator writes its ring in logical order - from firstIdx
        // forward, size entries - and reloads it rebased onto physical index 0. Only a wrapped ring
        // tells that apart from a verbatim physical copy, and the fixtures beside this one leave
        // firstIdx at 0. A sixteen-slot buffer plus a ten-second look-behind over one-second rows
        // evicts on nearly every row, so by the checkpoint firstIdx sits several slots past the
        // start and the frame's entries straddle the end of the buffer. Restart rehydrates the
        // accumulator from that checkpoint; the appended rows below still read frame entries the
        // restore laid down, so a rotation lost in the round trip diverges from the recompute.
        setProperty(PropertyKey.CAIRO_SQL_ANALYTIC_INITIAL_RANGE_BUFFER_SIZE, 16);
        assertMemoryLeak(() -> {
            setCurrentMicros(0L);
            execute("CREATE TABLE base (ts TIMESTAMP, sym SYMBOL, val DOUBLE) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, sym, first_value(val) IGNORE NULLS OVER w AS a FROM base " +
                    "WINDOW w AS (PARTITION BY sym ORDER BY ts RANGE BETWEEN '10' SECOND PRECEDING AND '1' SECOND PRECEDING)");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                // 60 rows per symbol one second apart, every seventh value NULL so IGNORE NULLS
                // actually skips entries and the ring holds fewer rows than the frame spans.
                execute("""
                        INSERT INTO base
                        SELECT dateadd('s', ((x - 1) / 2)::int, '2026-01-01T00:00:00.000000Z'::timestamp),
                               CASE WHEN x % 2 = 0 THEN 'a' ELSE 'b' END,
                               CASE WHEN x % 7 = 0 THEN NULL ELSE x::double END
                        FROM long_sequence(120)""");
                drainWalQueue();
                setCurrentMicros(250_000L);
                drainJob(job);
                drainWalQueue();
                assertFirstValueWrappedRangeLvMatchesRecompute();
            }

            // Simulated restart: rebuild the registry from on-disk state, then drive one refresh so
            // the head checkpoint rehydrates the wrapped ring.
            engine.getLiveViewRegistry().clear();
            engine.buildViewGraphs();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                setCurrentMicros(500_000L);
                drainJob(job);
                drainWalQueue();

                // Each appended row's frame still holds entries the restore laid down, so the
                // restored ring - not a fresh one - decides its first_value.
                execute("INSERT INTO base (ts, sym, val) VALUES " +
                        "('2026-01-01T00:01:00.000000Z', 'a', 101.0), " +
                        "('2026-01-01T00:01:00.000000Z', 'b', 102.0), " +
                        "('2026-01-01T00:01:01.000000Z', 'a', 103.0), " +
                        "('2026-01-01T00:01:01.000000Z', 'b', 104.0)");
                drainWalQueue();
                setCurrentMicros(750_000L);
                drainJob(job);
                drainWalQueue();
            }
            assertFirstValueWrappedRangeLvMatchesRecompute();

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testGlobalApplyDoesNotTouchLiveView() throws Exception {
        // The global ApplyWal2TableJob.doRun skips LV tokens. We
        // ingest into the base, write a LIVE_VIEW_DATA block via the refresh worker,
        // then capture the LV's applied seqTxn. A subsequent drainWalQueue must NOT
        // advance the LV's _txn, since global apply ignores LV notifications.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");
            execute("INSERT INTO base (ts, x) VALUES ('2026-05-12T00:00:00.000000Z', 11)");
            drainWalQueue();

            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);
            // Refresh writes + applies inline.
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            long lvConsumedAfterInline = instance.getStateReader().getLvConsumedSeqTxn();
            long lastProcessedAfterInline = instance.getLastProcessedSeqTxn();
            Assert.assertEquals(
                    "inline apply must advance lvConsumed to lastProcessed",
                    lastProcessedAfterInline,
                    lvConsumedAfterInline
            );

            // Run global apply repeatedly — must be a no-op for the LV.
            for (int i = 0; i < 8; i++) {
                drainWalQueue();
            }
            Assert.assertEquals(
                    "global apply must not advance lvConsumed for LV tokens",
                    lvConsumedAfterInline,
                    instance.getStateReader().getLvConsumedSeqTxn()
            );
            Assert.assertEquals(
                    "global apply must not advance lastProcessed",
                    lastProcessedAfterInline,
                    instance.getLastProcessedSeqTxn()
            );

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testRefreshAppliesInlineAndAdvancesLvConsumedSeqTxn() throws Exception {
        // LV apply runs inline on the refresh worker after the
        // LIVE_VIEW_DATA block is written. The global ApplyWal2TableJob.doRun skips
        // LV tokens, so drainWalQueue is a no-op for the LV's own WAL. The temporal
        // contract: lvConsumedSeqTxn advances within a single refresh cycle, not on
        // a subsequent global apply tick.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");
            execute("INSERT INTO base (ts, x) VALUES ('2026-04-01T00:00:00.000000Z', 4), " +
                    "('2026-04-01T00:01:00.000000Z', 8)");
            drainWalQueue();

            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);
            long preLvConsumed = instance.getStateReader().getLvConsumedSeqTxn();

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            Assert.assertTrue(
                    "lastProcessedSeqTxn must advance after refresh",
                    instance.getLastProcessedSeqTxn() > preLvConsumed
            );
            Assert.assertEquals(
                    "lvConsumedSeqTxn must advance inline with refresh",
                    instance.getLastProcessedSeqTxn(),
                    instance.getStateReader().getLvConsumedSeqTxn()
            );

            // drainWalQueue is a no-op for the LV's own WAL — global apply
            // skips LV tokens. Calling it must not change anything.
            long lvConsumedPostRefresh = instance.getStateReader().getLvConsumedSeqTxn();
            drainWalQueue();
            Assert.assertEquals(
                    "lvConsumedSeqTxn must not change on global drainWalQueue",
                    lvConsumedPostRefresh,
                    instance.getStateReader().getLvConsumedSeqTxn()
            );

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testDedupForwardRefreshAtMaxTimestampDoesNotWrapLowerBound() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL " +
                    "DEDUP UPSERT KEYS(ts)");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");

            final TableToken baseToken = engine.verifyTableName("base");
            final LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                setCurrentMicros(0L);
                execute("INSERT INTO base (ts, x) VALUES ('2026-01-01T00:00:00.000000Z', 1)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();
                assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n1\n");

                // SQL ingestion caps designated timestamps at year 9999, so
                // install the arithmetic boundary directly. This is the same
                // persisted frontier value the drain must handle defensively.
                instance.setLatestSeenTs(Long.MAX_VALUE);
                Assert.assertEquals(Long.MAX_VALUE, instance.getLatestSeenTs());
                final long lastProcessedBefore = instance.getLastProcessedSeqTxn();
                final long rawWalCyclesBefore = instance.getDedupRawWalCleanCycles();

                // This unreferenced schema change contributes no DATA rows but
                // still advances the base sequencer. The forward applied-base
                // drain must treat (Long.MAX_VALUE, +inf) as empty; adding one
                // to the frontier wraps to Long.MIN_VALUE and re-appends the
                // terminal row.
                setCurrentMicros(2_000_000L);
                execute("ALTER TABLE base ADD COLUMN y INT");
                drainWalQueue();
                // Force the conservative applied-base route used for a cold or
                // diverged dedup signal. The ALTER itself is non-DATA, so the
                // resulting scan range above the synthetic MAX frontier is empty.
                final SeqTxnTracker tracker = engine.getTableSequencerAPI().getTxnTracker(baseToken);
                final long structuralSeqTxn = tracker.getSeqTxn();
                tracker.recordApplied(
                        instance.getLastProcessedSeqTxn() + 1,
                        structuralSeqTxn,
                        true
                );
                engine.releaseAllReaders();
                final IntList openedBasePartitions = new IntList();
                engine.setReaderListener((tableToken, partitionIndex) -> {
                    if (baseToken.equals(tableToken)) {
                        openedBasePartitions.add(partitionIndex);
                    }
                });
                try {
                    drainJob(job);
                } finally {
                    engine.setReaderListener(null);
                }
                drainWalQueue();

                Assert.assertFalse(instance.isInvalid());
                Assert.assertEquals(Long.MAX_VALUE, instance.getLatestSeenTs());
                Assert.assertTrue(
                        "the non-DATA seqTxn must be consumed",
                        instance.getLastProcessedSeqTxn() > lastProcessedBefore
                );
                Assert.assertEquals(structuralSeqTxn, instance.getLastProcessedSeqTxn());
                Assert.assertEquals(
                        "the regression must exercise drainAppliedBase, not the raw-WAL fast path",
                        rawWalCyclesBefore,
                        instance.getDedupRawWalCleanCycles()
                );
                Assert.assertEquals("an empty MAX-frontier suffix must open no base partition",
                        "[]", openedBasePartitions.toString());
                assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n1\n");
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testLvConsumedAdvancesPastNonDataCommit() throws Exception {
        // Regression: an ALTER on the base table rides through the WAL as a non-DATA
        // event. The LV refresh worker walks past the seqTxn (no rows to process) and
        // emits no LIVE_VIEW_DATA block, so the apply path has nothing to consume.
        // Pre-fix, lvConsumedSeqTxn stayed at the CREATE-time floor and held base WAL
        // retention forever. Post-fix, the no-row branch advances lvConsumedSeqTxn
        // directly via engine.advanceLiveViewConsumedSeqTxn on base-table data
        // removal.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");

            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);
            long baselineFloor = instance.getStateReader().getLvConsumedSeqTxn();

            // ALTER ADD COLUMN of a column the LV does not reference: dependency-set
            // narrowing keeps the LV ACTIVE; the SQL seqTxn lands on the base sequencer.
            execute("ALTER TABLE base ADD COLUMN y INT");
            drainWalQueue();
            Assert.assertFalse(
                    "LV must stay valid after ALTER touching only non-dependency columns",
                    instance.isInvalid()
            );

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            // Apply runs even though no LV WAL block was written, so we drain to make
            // sure the assertion does not race the post-cycle state publication.
            drainWalQueue();

            long postFloor = instance.getStateReader().getLvConsumedSeqTxn();
            Assert.assertTrue(
                    "lvConsumedSeqTxn must advance past the non-DATA seqTxn [baseline=" + baselineFloor
                            + ", post=" + postFloor + ']',
                    postFloor > baselineFloor
            );
            Assert.assertEquals(
                    "lvConsumedSeqTxn must catch up to lastProcessedSeqTxn",
                    instance.getLastProcessedSeqTxn(),
                    postFloor
            );

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testLvConsumedAdvancesWhenAllRowsFilteredOut() throws Exception {
        // Regression: a DATA commit whose rows the LV's WHERE clause rejects produces
        // zero output rows. Pre-fix, no LIVE_VIEW_DATA block was emitted and
        // lvConsumedSeqTxn stalled, holding the base WAL segment that contained the
        // filtered seqTxn. Post-fix, the no-row branch advances lvConsumedSeqTxn so
        // base WAL purge can release the segment.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 1000000");

            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);
            long baselineFloor = instance.getStateReader().getLvConsumedSeqTxn();

            execute("INSERT INTO base (ts, x) VALUES ('2026-04-01T00:00:00.000000Z', 5)");
            drainWalQueue();

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            drainWalQueue();

            long postFloor = instance.getStateReader().getLvConsumedSeqTxn();
            Assert.assertTrue(
                    "lvConsumedSeqTxn must advance past the all-rows-filtered seqTxn [baseline="
                            + baselineFloor + ", post=" + postFloor + ']',
                    postFloor > baselineFloor
            );
            Assert.assertEquals(
                    "lvConsumedSeqTxn must catch up to lastProcessedSeqTxn",
                    instance.getLastProcessedSeqTxn(),
                    postFloor
            );

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testLvRowsTotalSurvivesRestart() throws Exception {
        // Drive a refresh that writes N rows, restart, confirm the counter is
        // restored from the selected timeline root, then write M more rows and
        // confirm it accumulates against the restored total.
        //
        // Force the row-trigger cadence to 1 so each batch seals its own
        // boundary; the default cadence is too high for a few-row check.
        setProperty(PropertyKey.CAIRO_LIVE_VIEW_CHECKPOINT_ROWS, 1);
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, sym SYMBOL, x INT) " +
                    "TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, sym, x, row_number() OVER w AS rn FROM base " +
                    "WINDOW w AS (PARTITION BY sym ORDER BY ts ANCHOR DAILY '00:00')");

            final long firstBatch = 4;
            execute("INSERT INTO base (ts, sym, x) VALUES " +
                    "('2026-06-01T00:00:00.000000Z', 'a', 1), " +
                    "('2026-06-01T00:00:01.000000Z', 'a', 2), " +
                    "('2026-06-01T00:00:02.000000Z', 'b', 3), " +
                    "('2026-06-01T00:00:03.000000Z', 'b', 4)");
            drainWalQueue();

            final long firstHeadLvSeqTxn;
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
                drainWalQueue();
                final LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(instance);
                firstHeadLvSeqTxn = instance.getHeadCheckpointLvSeqTxn();
                Assert.assertNotEquals(Numbers.LONG_NULL, firstHeadLvSeqTxn);
                Assert.assertEquals(
                        "in-memory counter matches the rows produced this cycle",
                        firstBatch,
                        instance.getLvRowsTotal()
                );
            }

            // Simulated restart re-seeds the counter from the timeline root's
            // effective row position on the first post-restart refresh cycle.
            engine.getLiveViewRegistry().clear();
            engine.buildViewGraphs();
            final LiveViewInstance reloaded = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(reloaded);
            Assert.assertEquals(0L, reloaded.getLvRowsTotal()); // fresh in-mem state pre-restore
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            Assert.assertEquals(
                    "post-restart counter restored from the timeline root",
                    firstBatch,
                    reloaded.getLvRowsTotal()
            );

            // A follow-up commit advances the counter, accumulating against the
            // restored total.
            final long secondBatch = 3;
            execute("INSERT INTO base (ts, sym, x) VALUES " +
                    "('2026-06-02T00:00:00.000000Z', 'a', 5), " +
                    "('2026-06-02T00:00:01.000000Z', 'a', 6), " +
                    "('2026-06-02T00:00:02.000000Z', 'b', 7)");
            drainWalQueue();

            final long secondHeadLvSeqTxn;
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
                drainWalQueue();
                secondHeadLvSeqTxn = reloaded.getHeadCheckpointLvSeqTxn();
                Assert.assertNotEquals("a follow-up boundary must be sealed", firstHeadLvSeqTxn, secondHeadLvSeqTxn);
                Assert.assertEquals(
                        "counter accumulates against the restored total",
                        firstBatch + secondBatch,
                        reloaded.getLvRowsTotal()
                );
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testWalPurgeHoldsBaseWalAtHeadCheckpointForRestartReplay() throws Exception {
        // Regression: a live view must not go permanently INVALID after a restart
        // when the durable head checkpoint lags the applied watermark. The head
        // checkpoint advances only on its own cadence, while the applied watermark
        // advances every FLUSH, so restart recovery replays the
        // (headBaseSeqTxn, applied] base WAL to re-seed the accumulator gap.
        // WalPurgeJob must hold the base WAL purge floor at the durable head's
        // base seqTxn, not the applied point: lvConsumed advances to applied
        // every flush, so a floor at lvConsumed lets the (headBase, applied]
        // segments be purged out from under the next restart's replayToApplied,
        // which then cannot open the purged _event file and invalidates the view
        // forever.
        //
        // Roll a fresh base WAL segment per commit (rollover row count = 1) so the
        // gap seqTxn lands in its own segment: WalPurgeJob purges at segment
        // granularity. An un-refreshed trailing commit rolls the writer off the
        // gap segment so it becomes a deletion candidate (the active writer
        // segment is never purged).
        setProperty(PropertyKey.CAIRO_WAL_SEGMENT_ROLLOVER_ROW_COUNT, 1);
        assertMemoryLeak(() -> {
            // Pin the clock well past the epoch: the WAL purge sweep's interval
            // gate (30s) skips every sweep while the clock sits near epoch. Data
            // timestamps sit above this so the non-SEED view keeps every row.
            setCurrentMicros(MicrosTimestampDriver.floor("2026-05-31T00:00:00.000000Z"));
            execute("CREATE TABLE base (ts TIMESTAMP, sym SYMBOL, x DOUBLE) " +
                    "TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, sym, sum(x) OVER w AS s FROM base " +
                    "WINDOW w AS (PARTITION BY sym ORDER BY ts ANCHOR EXPRESSION timestamp_floor('1d', ts))");

            final long t0 = MicrosTimestampDriver.floor("2026-05-31T00:00:00.000000Z");

            // Batch A -> base seqTxn 1 (WAL segment wal1/0). The first flush
            // writes the first head checkpoint (covers base seqTxn 1) and advances the
            // applied watermark to 1.
            execute("INSERT INTO base (ts, sym, x) VALUES " +
                    "('2026-06-01T00:00:00.000000Z', 'a', 1.0), " +
                    "('2026-06-01T00:00:01.000000Z', 'a', 2.0)");
            drainWalQueue();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
                drainWalQueue();
            }

            final LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);
            final long headLvSeqTxnAfterA = instance.getHeadCheckpointLvSeqTxn();
            Assert.assertNotEquals("head checkpoint written for batch A", Numbers.LONG_NULL, headLvSeqTxnAfterA);
            final long headBaseAfterA = instance.getHeadCheckpointBaseSeqTxn();

            // Batch B -> base seqTxn 2 (WAL segment wal1/1). It flushes
            // (applied -> 2, lvConsumed -> 2) but the head cadence (default 1M
            // rows / 5 min, clock advanced only 100ms) does not fire, so the
            // durable head still covers base seqTxn 1: the checkpoint-lags-applied
            // gap the restart replay depends on.
            execute("INSERT INTO base (ts, sym, x) VALUES " +
                    "('2026-06-01T00:00:02.000000Z', 'a', 4.0), " +
                    "('2026-06-01T00:00:03.000000Z', 'a', 8.0)");
            drainWalQueue();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                setCurrentMicros(t0 + 100_000L);
                drainJob(job);
                drainWalQueue();
            }

            Assert.assertEquals("head checkpoint must not advance for batch B",
                    headLvSeqTxnAfterA, instance.getHeadCheckpointLvSeqTxn());
            Assert.assertEquals("head base seqTxn must not advance for batch B",
                    headBaseAfterA, instance.getHeadCheckpointBaseSeqTxn());
            Assert.assertEquals("applied watermark ran ahead of the head",
                    2L, instance.getAppliedWatermark());
            Assert.assertEquals("head still covers base seqTxn 1",
                    1L, instance.getHeadCheckpointBaseSeqTxn());

            // Trailing base commit -> base seqTxn 3 (WAL segment wal1/2). It is
            // applied to the base but NOT refreshed into the view, so the view's
            // applied/lvConsumed stay at 2 and the head stays at 1. Its only role
            // is to roll the base writer off wal1/1 so that segment (holding the
            // gap seqTxn 2) becomes a deletion candidate.
            execute("INSERT INTO base (ts, sym, x) VALUES " +
                    "('2026-06-01T00:00:05.000000Z', 'a', 32.0)");
            drainWalQueue();
            Assert.assertEquals("view must not have consumed the trailing commit",
                    2L, instance.getStateReader().getLvConsumedSeqTxn());

            // Release the pooled base writer so its now-inactive WAL segments
            // unlock and become eligible for purge.
            engine.releaseInactive();

            // Purge base WAL. Pre-fix the floor is lvConsumed (2), which deletes
            // the gap segment wal1/1 (seqTxn 2) the restart replay needs. The fix
            // caps the floor at the head's base seqTxn (1), so wal1/1 survives.
            drainPurgeJob();
            assertSegmentExistence(false, "base", 1, 0); // seqTxn 1: below the head, always purgeable
            assertSegmentExistence(true, "base", 1, 1);  // seqTxn 2: the gap segment the fix must retain
            assertSegmentExistence(true, "base", 1, 2);  // seqTxn 3: still to apply, retained

            // Restart: startup publishes the head from the timeline, then the
            // first refresh runs tryRestoreFromTimeline -> replayToApplied(1, 2) over
            // the retained gap WAL, then drains forward to base seqTxn 3. The view
            // must recover ACTIVE, not invalidate on a purged _event file.
            engine.getLiveViewRegistry().clear();
            engine.buildViewGraphs();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                setCurrentMicros(t0 + 200_000L);
                drainJob(job);
                drainWalQueue();
            }
            LiveViewInstance recovered = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(recovered);
            Assert.assertFalse(
                    "view must stay active after the purge + restart (the gap WAL replay must survive the purge)",
                    recovered.isInvalid()
            );

            final String expected = "ts\tsym\ts\n" +
                    "2026-06-01T00:00:00.000000Z\ta\t1.0\n" +
                    "2026-06-01T00:00:01.000000Z\ta\t3.0\n" +
                    "2026-06-01T00:00:02.000000Z\ta\t7.0\n" +
                    "2026-06-01T00:00:03.000000Z\ta\t15.0\n" +
                    "2026-06-01T00:00:05.000000Z\ta\t47.0\n";
            assertQuery("SELECT ts, sym, s FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns(expected);

            // The restored accumulator must keep advancing: a new row continues
            // the running sum from 47, proving the window state (not just the
            // rows) survived the purge and restart.
            execute("INSERT INTO base (ts, sym, x) VALUES ('2026-06-01T00:00:06.000000Z', 'a', 16.0)");
            drainWalQueue();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                setCurrentMicros(t0 + 300_000L);
                drainJob(job);
                drainWalQueue();
            }
            assertQuery("SELECT ts, sym, s FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns(expected +
                    "2026-06-01T00:00:06.000000Z\ta\t63.0\n");

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testWalPurgeSurvivesRepeatedRestartsBeforeHeadCheckpointAdvance() throws Exception {
        // Regression (handoff item 0): the permanent-INVALID failure only surfaced
        // after >=2 restart events. testWalPurgeHoldsBaseWalAtHeadCheckpointForRestartReplay
        // proves ONE restart survives the purge; this one proves the view still
        // recovers after a SECOND restart taken before the head checkpoint has had a
        // chance to advance past the gap - a deploy/upgrade restart followed by a
        // crash, or two crashes in a row.
        //
        // While the head stays pinned at its old base seqTxn, lvConsumed keeps
        // climbing to the applied point on every flush, so each restart's
        // replayToApplied re-reads the SAME (headBaseSeqTxn, applied] base WAL and
        // every intervening WalPurgeJob must keep retaining it. Pre-fix the second
        // purge - whose floor is lvConsumed, now advanced FURTHER than after the
        // first restart - deletes the gap segments, so the second restart's replay
        // cannot open the purged _event file and the view goes INVALID forever.
        // Post-fix the floor is capped at headBaseSeqTxn on every sweep, so the gap
        // WAL survives an arbitrary number of restarts until a checkpoint moves the
        // manifest past it.
        //
        // What pins the head: the first post-restart flush normally seals a fresh
        // boundary (the restored-head trigger), which is exactly what
        // ends this scenario - once the head covers the applied point there is no
        // gap left to replay and the floor may release the WAL. To hold the view in
        // the pre-advance state across BOTH restarts, fail the seal outright: the
        // timeline is derived state and a failed seal is non-fatal by design (see
        // maybeWriteHeadCheckpoint's catch - "a failure here does not invalidate the
        // view"), so an unwritable checkpoint directory leaves a live view running
        // indefinitely with a lagging head. That is the production shape of
        // "restarts before the head checkpoint has had a chance to advance", and the
        // purge floor must hold the gap WAL through all of it.
        //
        // Roll a fresh base WAL segment per commit (rollover row count = 1) so the
        // gap seqTxn lands in its own segment; WalPurgeJob purges at segment
        // granularity.
        final AtomicBoolean failCpWrite = new AtomicBoolean(false);
        FilesFacade ff = new TestFilesFacadeImpl() {
            @Override
            public long openRW(LPSZ name, int opts) {
                // While armed, refuse to create the timeline's temporary segments
                // so no flush can seal a fresh boundary and the head stays pinned.
                if (failCpWrite.get() && Utf8s.endsWithAscii(name, LiveViewCheckpointLayout.TMP_SUFFIX)) {
                    return -1;
                }
                return super.openRW(name, opts);
            }
        };
        setProperty(PropertyKey.CAIRO_WAL_SEGMENT_ROLLOVER_ROW_COUNT, 1);
        assertMemoryLeak(ff, () -> {
            // Pin the clock past the epoch so the WAL purge interval gate never
            // skips a sweep; data timestamps sit above it so the non-SEED view
            // keeps every row.
            setCurrentMicros(MicrosTimestampDriver.floor("2026-05-31T00:00:00.000000Z"));
            execute("CREATE TABLE base (ts TIMESTAMP, sym SYMBOL, x DOUBLE) " +
                    "TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, sym, sum(x) OVER w AS s FROM base " +
                    "WINDOW w AS (PARTITION BY sym ORDER BY ts ANCHOR EXPRESSION timestamp_floor('1d', ts))");

            final long t0 = MicrosTimestampDriver.floor("2026-05-31T00:00:00.000000Z");

            // Batch A -> base seqTxn 1 (wal1/0). The first flush writes the head checkpoint
            // (covers base seqTxn 1) and advances the applied watermark to 1.
            execute("INSERT INTO base (ts, sym, x) VALUES " +
                    "('2026-06-01T00:00:00.000000Z', 'a', 1.0), " +
                    "('2026-06-01T00:00:01.000000Z', 'a', 2.0)");
            drainWalQueue();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
                drainWalQueue();
            }

            final LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);
            Assert.assertEquals("head covers base seqTxn 1", 1L, instance.getHeadCheckpointBaseSeqTxn());

            // Batch B -> base seqTxn 2 (wal1/1). It flushes (applied -> 2,
            // lvConsumed -> 2) but the head cadence does not fire (default 1M rows /
            // 5 min, clock advanced only 100ms), so the durable head still covers
            // base seqTxn 1: the checkpoint-lags-applied gap the restart replay
            // depends on.
            execute("INSERT INTO base (ts, sym, x) VALUES " +
                    "('2026-06-01T00:00:02.000000Z', 'a', 4.0), " +
                    "('2026-06-01T00:00:03.000000Z', 'a', 8.0)");
            drainWalQueue();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                setCurrentMicros(t0 + 100_000L);
                drainJob(job);
                drainWalQueue();
            }
            Assert.assertEquals("applied ran ahead of the head", 2L, instance.getAppliedWatermark());
            Assert.assertEquals("head still covers base seqTxn 1", 1L, instance.getHeadCheckpointBaseSeqTxn());

            // Trailing base commit -> base seqTxn 3 (wal1/2). Applied to the base but
            // NOT refreshed, so it rolls the base writer off wal1/1 (making the gap
            // segment a deletion candidate) while the view's floor stays at 2.
            execute("INSERT INTO base (ts, sym, x) VALUES ('2026-06-01T00:00:05.000000Z', 'a', 32.0)");
            drainWalQueue();
            Assert.assertEquals("view must not have consumed the trailing commit",
                    2L, instance.getStateReader().getLvConsumedSeqTxn());
            engine.releaseInactive();

            final String expectedAfterDrain = "ts\tsym\ts\n" +
                    "2026-06-01T00:00:00.000000Z\ta\t1.0\n" +
                    "2026-06-01T00:00:01.000000Z\ta\t3.0\n" +
                    "2026-06-01T00:00:02.000000Z\ta\t7.0\n" +
                    "2026-06-01T00:00:03.000000Z\ta\t15.0\n" +
                    "2026-06-01T00:00:05.000000Z\ta\t47.0\n";

            // Arm the seal failure: from here neither restart can seal a fresh
            // boundary, so the head stays pinned at base seqTxn 1 and every restart
            // replays the same gap - the state this regression is about.
            failCpWrite.set(true);

            // Restart #1: floor held at head base (1) retains the gap segments; the
            // view recovers ACTIVE, replays (1, 2], and drains forward to seqTxn 3.
            drainPurgeJob();
            assertSegmentExistence(true, "base", 1, 1);  // gap seqTxn 2 retained
            assertSegmentExistence(true, "base", 1, 2);  // seqTxn 3 retained
            engine.getLiveViewRegistry().clear();
            engine.buildViewGraphs();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                setCurrentMicros(t0 + 200_000L);
                drainJob(job);
                drainWalQueue();
            }
            LiveViewInstance afterFirst = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(afterFirst);
            Assert.assertFalse("view must stay active after the first restart", afterFirst.isInvalid());
            // The first restart advanced applied/lvConsumed to 3 but could NOT
            // advance the durable head (its seal failed), so the head still lags
            // and a second restart must replay the same gap over again.
            Assert.assertEquals("first restart drained to base seqTxn 3", 3L, afterFirst.getAppliedWatermark());
            Assert.assertEquals("head must still lag after the first restart",
                    1L, afterFirst.getHeadCheckpointBaseSeqTxn());
            Assert.assertEquals("lvConsumed advanced to the applied point",
                    3L, afterFirst.getStateReader().getLvConsumedSeqTxn());
            assertQuery("SELECT ts, sym, s FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns(expectedAfterDrain);

            // Restart #2: purge again first. lvConsumed is now 3 (further than after
            // the first restart), so pre-fix the floor deletes both gap segments;
            // post-fix the head-base cap (still 1) retains them, so replay(1, 3]
            // succeeds and the view recovers a second time rather than getting stuck.
            engine.releaseInactive();
            drainPurgeJob();
            assertSegmentExistence(true, "base", 1, 1);  // gap seqTxn 2 still retained after the 2nd purge
            assertSegmentExistence(true, "base", 1, 2);  // seqTxn 3 still retained
            engine.getLiveViewRegistry().clear();
            engine.buildViewGraphs();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                setCurrentMicros(t0 + 300_000L);
                drainJob(job);
                drainWalQueue();
            }
            LiveViewInstance afterSecond = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(afterSecond);
            Assert.assertFalse(
                    "view must stay active after the SECOND restart (the >=2-restart permanent-INVALID failure)",
                    afterSecond.isInvalid()
            );
            assertQuery("SELECT ts, sym, s FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns(expectedAfterDrain);

            // The accumulator survived both restarts: a new row continues the running
            // sum from 47, proving the window state (not just the rows) came through
            // two restarts intact. Disarm first so this last cycle runs an ordinary
            // flush, head write included.
            failCpWrite.set(false);
            execute("INSERT INTO base (ts, sym, x) VALUES ('2026-06-01T00:00:06.000000Z', 'a', 16.0)");
            drainWalQueue();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                setCurrentMicros(t0 + 400_000L);
                drainJob(job);
                drainWalQueue();
            }
            assertQuery("SELECT ts, sym, s FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns(expectedAfterDrain +
                    "2026-06-01T00:00:06.000000Z\ta\t63.0\n");

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testFailedRestartReplayDoesNotCorruptInvalidView() throws Exception {
        // Regression (handoff item 0b): when a restart's replay-to-applied fails
        // mid-gap, tryRestoreFromTimeline stashes a deferred invalidation but leaves
        // the window accumulators a PARTIAL advance over disk (advanced over the
        // gap seqTxns it did read, stuck short of the applied point). The refresh
        // worker must NOT run the incremental refresh + flush for that turn: doing
        // so materialises the inconsistent accumulators to the on-disk tier, and
        // since an invalidated view stays queryable off its own disk tier, a
        // reader then gets silently wrong window values rather than an error.
        //
        // Build a head-lags-applied gap that spans two base seqTxns (2 and 3) so
        // the replay can advance over seqTxn 2 before failing on seqTxn 3, then
        // delete seqTxn 3's WAL segment to force that mid-gap failure. A trailing
        // un-refreshed commit (seqTxn 4) gives the post-failure refresh something
        // to flush with the corrupt accumulator. Post-fix the view invalidates
        // with its disk tier untouched (three correct rows); pre-fix it flushes a
        // fourth row computed from the partial accumulator (sum 11 instead of 15).
        setProperty(PropertyKey.CAIRO_WAL_SEGMENT_ROLLOVER_ROW_COUNT, 1);
        assertMemoryLeak(() -> {
            // Pin the clock near the epoch so the WAL purge interval gate never
            // fires; data timestamps sit well above it (a non-SEED view keeps
            // every row).
            setCurrentMicros(MicrosTimestampDriver.floor("2026-05-31T00:00:00.000000Z"));
            execute("CREATE TABLE base (ts TIMESTAMP, sym SYMBOL, x DOUBLE) " +
                    "TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, sym, sum(x) OVER w AS s FROM base " +
                    "WINDOW w AS (PARTITION BY sym ORDER BY ts ANCHOR EXPRESSION timestamp_floor('1d', ts))");

            final long t0 = MicrosTimestampDriver.floor("2026-05-31T00:00:00.000000Z");

            // Batch A -> base seqTxn 1 (wal1/0). The first flush writes the head
            // checkpoint (covers base seqTxn 1, accumulator sum = 1) and advances the
            // applied watermark to 1.
            execute("INSERT INTO base (ts, sym, x) VALUES ('2026-06-01T00:00:00.000000Z', 'a', 1.0)");
            drainWalQueue();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
                drainWalQueue();
            }

            final LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);
            Assert.assertEquals("head checkpoint covers base seqTxn 1", 1L, instance.getHeadCheckpointBaseSeqTxn());

            // Batch B -> base seqTxn 2 (wal1/1). Flushes (applied -> 2) but the
            // head cadence does not fire (clock advanced only 100ms), so the head
            // still covers seqTxn 1.
            execute("INSERT INTO base (ts, sym, x) VALUES ('2026-06-01T00:00:01.000000Z', 'a', 2.0)");
            drainWalQueue();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                setCurrentMicros(t0 + 100_000L);
                drainJob(job);
                drainWalQueue();
            }

            // Batch C -> base seqTxn 3 (wal1/2). Flushes (applied -> 3), head still
            // covers seqTxn 1. This widens the checkpoint-lags-applied gap to
            // (1, 3], so the restart replay reads seqTxn 2 before it reaches 3.
            execute("INSERT INTO base (ts, sym, x) VALUES ('2026-06-01T00:00:02.000000Z', 'a', 4.0)");
            drainWalQueue();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                setCurrentMicros(t0 + 200_000L);
                drainJob(job);
                drainWalQueue();
            }

            Assert.assertEquals("head still covers base seqTxn 1", 1L, instance.getHeadCheckpointBaseSeqTxn());
            Assert.assertEquals("applied watermark ran ahead of the head", 3L, instance.getAppliedWatermark());

            // Batch D -> base seqTxn 4 (wal1/3). Applied to the base but NOT
            // refreshed into the view, so the view's applied watermark stays at 3.
            // It is the un-refreshed row the post-failure refresh would flush with
            // the corrupt accumulator.
            execute("INSERT INTO base (ts, sym, x) VALUES ('2026-06-01T00:00:03.000000Z', 'a', 8.0)");
            drainWalQueue();
            Assert.assertEquals("view must not have consumed the trailing commit",
                    3L, instance.getStateReader().getLvConsumedSeqTxn());

            // Release pooled writers so the WAL segments unlock, then delete
            // seqTxn 3's segment (wal1/2). The restart replay-to-applied(1, 3) then
            // reads seqTxn 2 (advancing the accumulator to 3) and fails opening
            // seqTxn 3's _event, invalidating the view mid-gap.
            engine.releaseInactive();
            final TableToken baseToken = engine.verifyTableName("base");
            try (Path p = new Path()) {
                p.of(engine.getConfiguration().getDbRoot())
                        .concat(baseToken).concat("wal1").slash().put(2).slash().put(WalUtils.EVENT_FILE_NAME);
                Assert.assertTrue("gap segment event file exists before delete",
                        engine.getConfiguration().getFilesFacade().removeQuiet(p.$()));
            }

            // Restart: rebuild the registry and drive one refresh. The first cycle
            // runs tryRestoreFromTimeline -> replayToApplied(1, 3), which fails on the
            // deleted seqTxn 3 segment. The view must invalidate WITHOUT flushing a
            // partial advance to disk.
            engine.getLiveViewRegistry().clear();
            engine.buildViewGraphs();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                setCurrentMicros(t0 + 300_000L);
                drainJob(job);
                drainWalQueue();
            }

            final LiveViewInstance recovered = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(recovered);
            // The replay over the deleted segment still fails, but it no longer
            // strands the view: timeline recovery catches the mid-gap failure and
            // rebuilds the accumulators from the applied base table, which does not
            // need the deleted WAL segment. The view stays ACTIVE.
            Assert.assertFalse("the rebuild recovered the view", recovered.isInvalid());
            assertQuery("SELECT view_status FROM live_views() WHERE view_name = 'lv'")
                    .noLeakCheck().noRandomAccess().returns("view_status\nactive\n");

            // The safety property the failure mode is about: whatever the view
            // serves must never come from a partially advanced accumulator. The
            // fourth row (00:00:03) carries the correct running sum 15, not the
            // 11 a partial replay would produce (accumulator stuck at 3 after
            // seqTxn 2 + the trailing x=8, skipping seqTxn 3's x=4).
            final String expected = "ts\tsym\ts\n" +
                    "2026-06-01T00:00:00.000000Z\ta\t1.0\n" +
                    "2026-06-01T00:00:01.000000Z\ta\t3.0\n" +
                    "2026-06-01T00:00:02.000000Z\ta\t7.0\n" +
                    "2026-06-01T00:00:03.000000Z\ta\t15.0\n";
            assertQuery("SELECT ts, sym, s FROM lv ORDER BY ts")
                    .noLeakCheck().timestamp("ts").expectSize().returns(expected);

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testTruncateOnBaseIsTransparentToLiveView() throws Exception {
        // TRUNCATE on the base is transparent to the LV: the view stays
        // ACTIVE, its derived rows on disk are preserved byte-for-byte, the
        // in-memory tier is unchanged, and the refresh worker walks past the
        // TRUNCATE seqTxn (advancing last_processed_seqTxn and
        // lv_consumed_seqTxn) without rewriting LV state. Pre-fix,
        // ApplyWal2TableJob's TRUNCATE branch invalidated dependent LVs,
        // flipping the view to INVALID on every base TRUNCATE.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 200ms START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");

            execute(
                    "INSERT INTO base (ts, x) VALUES " +
                            "('2026-04-01T00:00:00.000000Z', 1)," +
                            "('2026-04-02T00:00:00.000000Z', 2)"
            );
            drainWalQueue();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            drainWalQueue();

            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);
            assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n2\n");
            long preFloor = instance.getStateReader().getLvConsumedSeqTxn();

            execute("TRUNCATE TABLE base");
            drainWalQueue();
            // FLUSH EVERY 200ms would otherwise rate-limit the back-to-back
            // refresh cycle and the walk-past would not run until 200ms later.
            instance.setLastFlushTimeUs(Numbers.LONG_NULL);
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            drainWalQueue();

            Assert.assertFalse(
                    "LV must stay valid after TRUNCATE on base",
                    instance.isInvalid()
            );
            assertQuery("SELECT view_status FROM live_views() WHERE view_name = 'lv'").noLeakCheck().noRandomAccess().returns("view_status\nactive\n");
            assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n2\n");

            long postFloor = instance.getStateReader().getLvConsumedSeqTxn();
            Assert.assertTrue(
                    "lv_consumed_seqTxn must advance past the TRUNCATE seqTxn [pre=" + preFloor
                            + ", post=" + postFloor + ']',
                    postFloor > preFloor
            );

            // Forward inserts past the LV's latestSeenTs continue to flow
            // through the normal path; the TRUNCATE did not reset state.
            execute("INSERT INTO base (ts, x) VALUES ('2026-04-03T00:00:00.000000Z', 3)");
            drainWalQueue();
            instance.setLastFlushTimeUs(Numbers.LONG_NULL);
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            drainWalQueue();
            assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n3\n");

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testDropPartitionOnBaseIsTransparentToLiveView() throws Exception {
        // DROP PARTITION on the base is transparent to the LV (same contract as
        // TRUNCATE, see testTruncateOnBaseIsTransparentToLiveView): the view
        // stays ACTIVE, its derived rows are preserved, and the refresh worker
        // walks past the DROP PARTITION seqTxn (advancing last_processed_seqTxn
        // and lv_consumed_seqTxn) without rewriting LV state. Pre-fix,
        // ApplyWal2TableJob's CMD_ALTER_TABLE branch forwarded executeAlter's
        // mat-view invalidation reason to invalidateLiveViewsForBaseTable,
        // flipping every dependent LV to INVALID on the first base partition
        // drop -- which broke any base using DROP PARTITION or TTL retention.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 200ms START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");

            execute(
                    "INSERT INTO base (ts, x) VALUES " +
                            "('2026-04-01T00:00:00.000000Z', 1)," +
                            "('2026-04-02T00:00:00.000000Z', 2)"
            );
            drainWalQueue();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            drainWalQueue();

            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);
            assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n2\n");
            long preFloor = instance.getStateReader().getLvConsumedSeqTxn();

            execute("ALTER TABLE base DROP PARTITION LIST '2026-04-01'");
            drainWalQueue();
            // FLUSH EVERY 200ms would otherwise rate-limit the back-to-back
            // refresh cycle and the walk-past would not run until 200ms later.
            instance.setLastFlushTimeUs(Numbers.LONG_NULL);
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            drainWalQueue();

            Assert.assertFalse(
                    "LV must stay valid after DROP PARTITION on base",
                    instance.isInvalid()
            );
            assertQuery("SELECT view_status FROM live_views() WHERE view_name = 'lv'").noLeakCheck().noRandomAccess().returns("view_status\nactive\n");
            // The dropped base partition does not retract already-computed LV
            // rows: the view's derived output is preserved.
            assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n2\n");

            long postFloor = instance.getStateReader().getLvConsumedSeqTxn();
            Assert.assertTrue(
                    "lv_consumed_seqTxn must advance past the DROP PARTITION seqTxn [pre=" + preFloor
                            + ", post=" + postFloor + ']',
                    postFloor > preFloor
            );

            // Forward inserts past the LV's latestSeenTs continue to flow
            // through the normal path; the DROP PARTITION did not reset state.
            execute("INSERT INTO base (ts, x) VALUES ('2026-04-03T00:00:00.000000Z', 3)");
            drainWalQueue();
            instance.setLastFlushTimeUs(Numbers.LONG_NULL);
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            drainWalQueue();
            assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n3\n");

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testBaseTableTtlIsTransparentToLiveView() throws Exception {
        // A base-table TTL that evicts old partitions is transparent to the LV,
        // exactly like an explicit DROP PARTITION
        // (testDropPartitionOnBaseIsTransparentToLiveView): the view stays ACTIVE,
        // its already-derived rows below the evicted range are preserved (frozen,
        // not retracted), and the refresh worker walks past the eviction without
        // rewriting LV state. TTL differs only in its trigger - it fires
        // automatically at apply time when a later commit advances the base max
        // timestamp past the retention window - so it exercises the automatic
        // retention path the explicit-DROP test does not. The LV consumes the base
        // WAL stream incrementally, not base partitions, so physical partition
        // eviction never reaches the LV's read path.
        assertMemoryLeak(() -> {
            // Pin the clock just below the 2020 data at CREATE so the non-SEED
            // view's lower bound sits under the rows (the forward-append path drops
            // rows below it). The clock is advanced past the data max before the
            // TTL-triggering insert below so TTL's wall-clock protection (it evicts
            // relative to min(maxTimestamp, wallClock)) keys off the data max and
            // the eviction is deterministic.
            setCurrentMicros(MicrosTimestampDriver.floor("2020-01-01T00:00:00.000000Z"));
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY TTL 1 DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 200ms START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");

            execute(
                    "INSERT INTO base (ts, x) VALUES " +
                            "('2020-01-01T12:00:00.000000Z', 1)," +
                            "('2020-01-02T12:00:00.000000Z', 2)"
            );
            drainWalQueue();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            drainWalQueue();

            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);
            // Both partitions are within 1 day of the max (2020-01-02T12:00), so
            // nothing is evicted yet: base and LV both hold the two rows.
            assertQuery("SELECT count() FROM base").noLeakCheck().noRandomAccess().expectSize().returns("count\n2\n");
            assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n2\n");
            long preFloor = instance.getStateReader().getLvConsumedSeqTxn();

            // A later commit advances the base max to 2020-01-10, pushing both
            // earlier partitions outside the 1-day window: TTL evicts them at apply
            // time, leaving only the new row in the base table. Advance the clock
            // past the new max so the wall-clock protection keys off the data max.
            setCurrentMicros(MicrosTimestampDriver.floor("2020-01-12T00:00:00.000000Z"));
            execute("INSERT INTO base (ts, x) VALUES ('2020-01-10T12:00:00.000000Z', 3)");
            drainWalQueue();
            assertQuery("SELECT ts, x FROM base").noLeakCheck().timestamp("ts").expectSize().returns("ts\tx\n" +
                    "2020-01-10T12:00:00.000000Z\t3\n");

            // FLUSH EVERY 200ms would otherwise rate-limit the back-to-back refresh.
            instance.setLastFlushTimeUs(Numbers.LONG_NULL);
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            drainWalQueue();

            Assert.assertFalse(
                    "LV must stay valid after base TTL eviction",
                    instance.isInvalid()
            );
            assertQuery("SELECT view_status FROM live_views() WHERE view_name = 'lv'").noLeakCheck().noRandomAccess().returns("view_status\nactive\n");
            // The TTL-evicted base partitions do not retract the already-derived LV
            // rows; the new row forward-appends with the next row number.
            assertQuery("SELECT ts, x, rn FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns("ts\tx\trn\n" +
                    "2020-01-01T12:00:00.000000Z\t1\t1\n" +
                    "2020-01-02T12:00:00.000000Z\t2\t2\n" +
                    "2020-01-10T12:00:00.000000Z\t3\t3\n");

            long postFloor = instance.getStateReader().getLvConsumedSeqTxn();
            Assert.assertTrue(
                    "lv_consumed_seqTxn must advance past the new commit [pre=" + preFloor
                            + ", post=" + postFloor + ']',
                    postFloor > preFloor
            );

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testApplyPersistFailureDoesNotAdvanceFloor() throws Exception {
        // Regression: pre-fix, advanceLiveViewConsumedSeqTxn mutated the in-memory
        // floor before persisting _lv.s and silently swallowed any persist error,
        // leaving the in-memory floor ahead of the durable contract WalPurgeJob
        // reads (WAL retention coupling). The fix reorders to persist
        // first and throws on failure.
        final AtomicBoolean failPersist = new AtomicBoolean(false);
        FilesFacade ff = new TestFilesFacadeImpl() {
            @Override
            public long openRW(LPSZ name, int opts) {
                if (failPersist.get() && Utf8s.endsWithAscii(name, LiveViewState.LIVE_VIEW_STATE_FILE_NAME)) {
                    return -1;
                }
                return super.openRW(name, opts);
            }
        };

        assertMemoryLeak(ff, () -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");
            execute("INSERT INTO base (ts, x) VALUES ('2026-04-01T00:00:00.000000Z', 4)");
            drainWalQueue();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            drainWalQueue();

            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);
            TableToken token = instance.getLiveViewToken();
            long baselineFloor = instance.getStateReader().getLvConsumedSeqTxn();
            Assert.assertTrue("baseline lvConsumedSeqTxn must be > -1", baselineFloor > -1);

            // Inject persist failure and call advance directly with a strictly higher value.
            // Pre-fix the in-memory floor would advance and the persist error would be
            // swallowed; post-fix the call throws and the in-memory floor stays put.
            try (
                    BlockFileWriter blockFileWriter = new BlockFileWriter(
                            engine.getConfiguration().getFilesFacade(),
                            engine.getConfiguration().getCommitMode()
                    );
                    Path path = new Path()
            ) {
                failPersist.set(true);
                try {
                    long target = baselineFloor + 10;
                    try {
                        engine.advanceLiveViewConsumedSeqTxn(token, target, blockFileWriter, path);
                        Assert.fail("expected CairoException from failed _lv.s persist");
                    } catch (CairoException e) {
                        Assert.assertTrue(
                                "exception must mention the view name [msg=" + e.getFlyweightMessage() + "]",
                                Chars.contains(e.getFlyweightMessage(), token.getTableName())
                        );
                    }
                    Assert.assertEquals(
                            "in-memory lvConsumedSeqTxn must not advance when _lv.s persist fails",
                            baselineFloor,
                            instance.getStateReader().getLvConsumedSeqTxn()
                    );
                } finally {
                    failPersist.set(false);
                }

                // Sanity: with the failure flag cleared, the same advance succeeds and the
                // in-memory floor publishes the new value.
                engine.advanceLiveViewConsumedSeqTxn(token, baselineFloor + 10, blockFileWriter, path);
                Assert.assertEquals(
                        baselineFloor + 10,
                        instance.getStateReader().getLvConsumedSeqTxn()
                );
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testRefreshPersistFailureKeepsInMemoryAdvanced() throws Exception {
        // Refresh-side _lv.s write happens after the LV WAL block is committed, so
        // a failing persist cannot roll back the in-memory advance without producing
        // duplicate rows on retry. The refresh worker logs critical and moves on; the
        // next cycle resumes from the in-memory advance and the eventual successful
        // persist catches up the durable file.
        final AtomicBoolean failPersist = new AtomicBoolean(false);
        FilesFacade ff = new TestFilesFacadeImpl() {
            @Override
            public long openRW(LPSZ name, int opts) {
                if (failPersist.get() && Utf8s.endsWithAscii(name, LiveViewState.LIVE_VIEW_STATE_FILE_NAME)) {
                    return -1;
                }
                return super.openRW(name, opts);
            }
        };

        assertMemoryLeak(ff, () -> {
            // Pin the clock so the second refresh isn't skipped by the FLUSH-EVERY gate.
            setCurrentMicros(0);
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                execute("INSERT INTO base (ts, x) VALUES ('2026-04-01T00:00:00.000000Z', 4)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(instance);
                long baselineLastProcessed = instance.getLastProcessedSeqTxn();
                Assert.assertTrue("baseline lastProcessedSeqTxn must be > -1", baselineLastProcessed > -1);

                // Advance past the FLUSH EVERY 1s window so the next refresh isn't gated.
                setCurrentMicros(2_000_000L);

                failPersist.set(true);
                try {
                    execute("INSERT INTO base (ts, x) VALUES ('2026-04-01T00:00:00.000001Z', 8)");
                    drainWalQueue();
                    drainJob(job);
                    // The persist threw; the refresh top-level catch logged critical. The
                    // key invariant: in-memory still advanced so the next refresh cycle
                    // does not re-process and double-write rows to the LV WAL.
                    Assert.assertTrue(
                            "refresh must keep lastProcessedSeqTxn advanced even when _lv.s persist fails",
                            instance.getLastProcessedSeqTxn() > baselineLastProcessed
                    );
                } finally {
                    failPersist.set(false);
                }
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testCrashBetweenLvWalCommitAndInlineApplyRecovers() throws Exception {
        // Regression: a crash that leaves the durable _lv.s floor behind the LV
        // table's applied state must not double-emit on restart. A flush commits
        // the LV WAL block, inline-applies it (rows become durable in the LV
        // table via its own _txn), then persists _lv.s LAST. If the process dies
        // after the apply but before the _lv.s persist, restart reloads a stale
        // lastProcessedSeqTxn and the first post-restart refresh re-drains the
        // same base range, re-committing and re-applying the identical rows. The
        // LV table has no dedup keys and the forward-append commit is not a
        // REPLACE_RANGE, so nothing collapses the duplicates - recovery must
        // reconcile lastProcessedSeqTxn up to what the LV table already applied.
        final AtomicBoolean failStatePersist = new AtomicBoolean(false);
        FilesFacade ff = new TestFilesFacadeImpl() {
            @Override
            public long openRW(LPSZ name, int opts) {
                if (failStatePersist.get() && Utf8s.endsWithAscii(name, LiveViewState.LIVE_VIEW_STATE_FILE_NAME)) {
                    return -1;
                }
                return super.openRW(name, opts);
            }
        };

        assertMemoryLeak(ff, () -> {
            setCurrentMicros(0);
            execute("CREATE TABLE base (ts TIMESTAMP, sym SYMBOL, x INT) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, sym, x, sum(x) OVER w AS s FROM base " +
                    "WINDOW w AS (PARTITION BY sym ORDER BY ts ANCHOR EXPRESSION timestamp_floor('1d', ts))");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                // Baseline clean flush; _lv.s durably records this commit.
                execute("INSERT INTO base VALUES ('2026-04-01T00:00:00.000000Z', 'a', 1)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                // Crash window: the commit and inline apply succeed (row durable
                // in the LV table), but the trailing _lv.s persist fails, so the
                // durable floor stays at the baseline commit.
                setCurrentMicros(2_000_000L);
                failStatePersist.set(true);
                execute("INSERT INTO base VALUES ('2026-04-01T00:00:02.000000Z', 'a', 2)");
                drainWalQueue();
                drainJob(job);
                failStatePersist.set(false);

                // The row is applied and queryable despite the stale floor.
                assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n2\n");
            }

            // Restart: rebuild the registry from the on-disk _lv + (stale) _lv.s,
            // the path startup takes.
            engine.getLiveViewRegistry().clear();
            engine.buildViewGraphs();

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                setCurrentMicros(4_000_000L);
                // A fresh commit drives the first post-restart refresh, which must
                // resume from what the LV table already applied - not re-emit the
                // stranded range.
                execute("INSERT INTO base VALUES ('2026-04-01T00:00:04.000000Z', 'a', 3)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                // No duplication: exactly the three base rows, once each.
                assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n3\n");
                assertRunningSumLvMatchesRecompute();
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testCrashMidHeadCheckpointWriteFallsBackToPriorHead() throws Exception {
        // A crash mid seal (or a seal that simply fails) must not corrupt the view
        // or block recovery. The row data is durable in the LV table via its own
        // _txn; the checkpoint root only freezes window-accumulator state so a
        // restart can continue the running window without replaying from the
        // view's lower bound. maybeWriteHeadCheckpoint swallows the failure - the
        // timeline is derived state, and its segments are written tmp+rename -
        // leaving the previously published generation authoritative and the head
        // parked on the boundary it already named. A restart restores from that
        // boundary and replays base WAL forward across the cadence gap to the
        // applied point, converging to a from-scratch recompute with no
        // duplication.
        //
        // CHECKPOINT_ROWS=1 makes every flush attempt a seal so the injected
        // failure fires on the second flush.
        setProperty(PropertyKey.CAIRO_LIVE_VIEW_CHECKPOINT_ROWS, 1);
        final AtomicBoolean failCpWrite = new AtomicBoolean(false);
        FilesFacade ff = new TestFilesFacadeImpl() {
            @Override
            public long openRW(LPSZ name, int opts) {
                if (failCpWrite.get() && Utf8s.endsWithAscii(name, LiveViewCheckpointLayout.TMP_SUFFIX)) {
                    return -1;
                }
                return super.openRW(name, opts);
            }
        };

        assertMemoryLeak(ff, () -> {
            setCurrentMicros(0);
            execute("CREATE TABLE base (ts TIMESTAMP, sym SYMBOL, x INT) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, sym, x, sum(x) OVER w AS s FROM base " +
                    "WINDOW w AS (PARTITION BY sym ORDER BY ts ANCHOR EXPRESSION timestamp_floor('1d', ts))");

            final long priorHead;
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                // First flush seals a valid boundary (the first-checkpoint cadence).
                execute("INSERT INTO base VALUES ('2026-04-01T00:00:00.000000Z', 'a', 1)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();
                LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(instance);
                priorHead = instance.getHeadCheckpointLvSeqTxn();
                Assert.assertNotEquals("a prior boundary must exist", Numbers.LONG_NULL, priorHead);

                // Crash mid seal: the next flush commits + applies + persists
                // _lv.s fine, but the root append fails and is swallowed, so the
                // head metadata stays pinned to the prior boundary.
                setCurrentMicros(2_000_000L);
                failCpWrite.set(true);
                execute("INSERT INTO base VALUES ('2026-04-01T00:00:02.000000Z', 'a', 2)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();
                failCpWrite.set(false);
                Assert.assertEquals("the head must remain the prior boundary after a failed seal",
                        priorHead, instance.getHeadCheckpointLvSeqTxn());
                // Rows are durable despite the failed seal.
                assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n2\n");
                assertRunningSumLvMatchesRecompute();
            }

            // Restart: the published generation still names the prior boundary; the
            // first refresh restores its accumulators and replays base WAL forward
            // across the cadence gap.
            engine.getLiveViewRegistry().clear();
            engine.buildViewGraphs();

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                LiveViewInstance reloaded = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(reloaded);
                Assert.assertEquals("startup re-stamps the head from the published generation",
                        priorHead, reloaded.getHeadCheckpointLvSeqTxn());

                setCurrentMicros(4_000_000L);
                execute("INSERT INTO base VALUES ('2026-04-01T00:00:04.000000Z', 'a', 3)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();
                // The prior-head restore + forward replay leaves the view exactly
                // equal to a recompute - no lost or duplicated rows.
                assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n3\n");
                assertRunningSumLvMatchesRecompute();
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testRefreshThrowThenRetryIsIdempotentAndLeakFree() throws Exception {
        // A refresh cycle whose durable _lv.s persist throws mid-flush must not
        // corrupt the view. The LV WAL block is committed and inline-applied
        // before the persist, so the rows are already durable and the in-memory
        // watermark advanced past them; the top-level catch in refreshInstance
        // ticks the flush-retry budget and abandons the cycle, and a subsequent
        // successful cycle never re-appends the already-committed rows (no
        // duplication). Both the in-order flush path (flushLead) and the
        // out-of-order REPLACE_RANGE replay path (o3Replay) advance
        // lvConsumedSeqTxn then fall back to persistState on failure, so both
        // are exercised. The whole test runs under assertMemoryLeak, covering
        // the base readers that o3Replay / drainBaseWal close manually - a leak
        // on the throwing path would surface here.
        //
        // Injection: a counter fails exactly the two _lv.s writes a single
        // failing cycle makes (the advanceLiveViewConsumedSeqTxn attempt plus
        // the persistState fallback) and then self-clears, so the next cycle
        // persists cleanly. The failing cycle's second write is what propagates
        // and ticks the budget; a success cycle makes only one _lv.s write, so a
        // fully-drained counter proves the throw-and-fallback path executed.
        final AtomicInteger failLvStateWrites = new AtomicInteger(0);
        FilesFacade ff = new TestFilesFacadeImpl() {
            @Override
            public long openRW(LPSZ name, int opts) {
                if (Utf8s.endsWithAscii(name, LiveViewState.LIVE_VIEW_STATE_FILE_NAME)
                        && failLvStateWrites.get() > 0) {
                    failLvStateWrites.decrementAndGet();
                    return -1;
                }
                return super.openRW(name, opts);
            }
        };

        assertMemoryLeak(ff, () -> {
            setCurrentMicros(0);
            execute("CREATE TABLE base (ts TIMESTAMP, sym SYMBOL, x INT) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, sym, x, sum(x) OVER w AS s FROM base " +
                    "WINDOW w AS (PARTITION BY sym ORDER BY ts ANCHOR EXPRESSION timestamp_floor('1d', ts))");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                // Baseline: one clean flush establishes lastFlushTimeUs and the
                // head checkpoint the O3 replay later rebuilds against. All test rows sit
                // within one day, so the daily-anchored running sum equals the
                // plain unbounded recompute the oracle uses.
                execute("INSERT INTO base VALUES ('2026-04-01T00:00:00.000000Z', 'a', 1)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(instance);
                Assert.assertEquals("clean baseline leaves no retries", 0, instance.getFlushRetryCount());
                long baselineProcessed = instance.getLastProcessedSeqTxn();
                Assert.assertTrue("baseline must have processed the first commit", baselineProcessed > -1);

                // Phase 1 - in-order flush persist failure. Advance past FLUSH
                // EVERY so the flush is due, arm the two-write failure, and drive
                // one refresh. flushLead commits + applies the row, then the
                // consumed-seqTxn advance and its persistState fallback both throw
                // and the cycle ticks the retry budget. The lead in-order path
                // advances refreshedUpTo on the drain (before the flush), so the
                // failing cycle does not re-run and the budget stays at one.
                setCurrentMicros(2_000_000L);
                failLvStateWrites.set(2);
                execute("INSERT INTO base VALUES ('2026-04-01T00:00:02.000000Z', 'a', 2)");
                drainWalQueue();
                drainJob(job);
                Assert.assertEquals("both _lv.s writes of the failing flush must have fired",
                        0, failLvStateWrites.get());
                Assert.assertTrue("persist failure must tick the flush-retry budget",
                        instance.getFlushRetryCount() > 0);
                Assert.assertTrue("in-memory watermark advances despite the persist failure",
                        instance.getLastProcessedSeqTxn() > baselineProcessed);
                // The row was applied before the persist threw, so it is durable
                // and queryable even though _lv.s is momentarily stale.
                assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n2\n");

                // Retry: a fresh commit drives a clean flush that resets the
                // budget and catches _lv.s up. No row is re-appended.
                setCurrentMicros(4_000_000L);
                execute("INSERT INTO base VALUES ('2026-04-01T00:00:04.000000Z', 'a', 3)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();
                Assert.assertEquals("successful retry resets the budget", 0, instance.getFlushRetryCount());
                assertRunningSumLvMatchesRecompute();

                // Phase 2 - out-of-order REPLACE_RANGE replay persist failure. A
                // back-dated row forces o3Replay, which commits a REPLACE_RANGE
                // block and inline-applies it before advancing lvConsumedSeqTxn.
                // The lead O3 branch only advances refreshedUpTo after o3Replay
                // returns, so the throwing cycle re-runs on the next worker tick;
                // the two-write counter self-clears so that re-run persists
                // cleanly and converges within the same drainJob burst.
                setCurrentMicros(6_000_000L);
                failLvStateWrites.set(2);
                execute("INSERT INTO base VALUES ('2026-04-01T00:00:01.000000Z', 'a', 9)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();
                Assert.assertEquals("the O3 replay cycle must have exhausted the injected failures",
                        0, failLvStateWrites.get());
                Assert.assertTrue("O3 replay persist failure must tick the retry budget",
                        instance.getFlushRetryCount() > 0);
                // The REPLACE_RANGE block was committed and applied before the
                // persist threw, so the back-dated row is already durable and lands
                // exactly once (REPLACE_RANGE replaces the overlap band rather than
                // appending) even though _lv.s is momentarily stale.
                assertRunningSumLvMatchesRecompute();

                // Retry: the next commit re-drives the O3 replay (refreshedUpTo did
                // not advance on the failing cycle) with the counter cleared, so it
                // persists cleanly, resets the budget, and stays duplication-free.
                setCurrentMicros(8_000_000L);
                execute("INSERT INTO base VALUES ('2026-04-01T00:00:06.000000Z', 'a', 4)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();
                Assert.assertEquals("successful retry resets the budget", 0, instance.getFlushRetryCount());
                assertRunningSumLvMatchesRecompute();
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testRefreshAdvancesLvConsumedSeqTxn() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");
            execute("INSERT INTO base (ts, x) VALUES ('2026-01-01T00:00:00.000000Z', 1), " +
                    "('2026-01-01T00:01:00.000000Z', 5), ('2026-01-01T00:02:00.000000Z', -3)");
            drainWalQueue();

            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            drainWalQueue();

            // The live view's last-processed seqTxn moved past 0 because we ingested at
            // least one DATA commit on the base.
            Assert.assertTrue(
                    "lastProcessedSeqTxn must advance past 0",
                    instance.getLastProcessedSeqTxn() > 0
            );
            Assert.assertEquals(
                    "lvConsumedSeqTxn must equal lastProcessedSeqTxn after refresh",
                    instance.getLastProcessedSeqTxn(),
                    instance.getStateReader().getLvConsumedSeqTxn()
            );

            // Two rows match (x > 0); the live view's on-disk tier picks them up via
            // the standard ApplyWal2TableJob.
            assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n2\n");

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testRestartRecoversLvState() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");
            execute("INSERT INTO base (ts, x) VALUES ('2026-02-01T00:00:00.000000Z', 7), " +
                    "('2026-02-01T00:01:00.000000Z', 9)");
            drainWalQueue();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            drainWalQueue();

            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            long preLastProcessed = instance.getLastProcessedSeqTxn();
            Assert.assertTrue("preLastProcessed must be > 0", preLastProcessed > 0);

            // Simulate restart: clear the in-memory registry and rebuild from on-disk
            // _lv + _lv.s files via buildViewGraphs (the same path startup takes).
            engine.getLiveViewRegistry().clear();
            engine.buildViewGraphs();

            LiveViewInstance reloaded = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull("live view must be re-registered after restart", reloaded);
            Assert.assertEquals(
                    "lastProcessedSeqTxn must round-trip via _lv.s",
                    preLastProcessed,
                    reloaded.getLastProcessedSeqTxn()
            );
            Assert.assertEquals(
                    "lvConsumedSeqTxn must round-trip via _lv.s",
                    preLastProcessed,
                    reloaded.getStateReader().getLvConsumedSeqTxn()
            );
            // Reads route through the standard TableReader cursor over the LV's
            // _meta + applied WAL. The on-disk tier survives restart so the row count
            // should reflect what the refresh wrote before the registry was cleared.
            assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n2\n");

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testSeedFieldsRoundTripAsActiveDefault() throws Exception {
        // Without the SEED clause the CORE_DEFINITION / CORE_STATE blocks
        // persist the ACTIVE / LONG_NULL defaults. Round-trips across a
        // simulated restart so a regression that drops these fields breaks
        // visibly.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");

            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);
            Assert.assertEquals(
                    "START FROM NOW must round-trip to definition",
                    LiveViewDefinition.START_FROM_NOW,
                    instance.getDefinition().getStartFromKind()
            );
            Assert.assertEquals(
                    "seedState is ACTIVE for a view that does not sweep",
                    LiveViewState.SEED_STATE_ACTIVE,
                    instance.getStateReader().getSeedState()
            );
            Assert.assertEquals(
                    "seedTargetSeqTxn is LONG_NULL for a view that does not sweep",
                    Numbers.LONG_NULL,
                    instance.getStateReader().getSeedTargetSeqTxn()
            );

            // Round-trip across a simulated restart.
            engine.getLiveViewRegistry().clear();
            engine.buildViewGraphs();

            LiveViewInstance reloaded = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull("live view must be re-registered after restart", reloaded);
            Assert.assertEquals(
                    "start kind must round-trip via _lv",
                    LiveViewDefinition.START_FROM_NOW,
                    reloaded.getDefinition().getStartFromKind()
            );
            Assert.assertEquals(
                    "seedState must round-trip via _lv.s",
                    LiveViewState.SEED_STATE_ACTIVE,
                    reloaded.getStateReader().getSeedState()
            );
            Assert.assertEquals(
                    "seedTargetSeqTxn must round-trip via _lv.s",
                    Numbers.LONG_NULL,
                    reloaded.getStateReader().getSeedTargetSeqTxn()
            );

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testRestartResetsForeignCheckpointFormatAndRebuilds() throws Exception {
        // A checkpoint directory an earlier development build owned - here the
        // retained-ring manifest sitting beside the current layout - cannot be
        // recovered field by field. Startup removes it whole and the refresh
        // worker rebuilds derived state from the applied base, which must leave
        // the window accumulators where a from-scratch recompute puts them.
        assertMemoryLeak(() -> {
            setCurrentMicros(0);
            execute("CREATE TABLE base (ts TIMESTAMP, sym SYMBOL, x INT) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, sym, x, sum(x) OVER w AS s FROM base " +
                    "WINDOW w AS (PARTITION BY sym ORDER BY ts ANCHOR EXPRESSION timestamp_floor('1d', ts))");

            final TableToken lvToken = engine.getLiveViewRegistry().getViewInstance("lv").getLiveViewToken();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                execute("INSERT INTO base VALUES " +
                        "('2026-04-01T00:00:00.000000Z', 'a', 1), " +
                        "('2026-04-01T00:00:01.000000Z', 'b', 2)");
                drainWalQueue();
                setCurrentMicros(2_000_000L);
                drainJob(job);
                drainWalQueue();
            }
            Assert.assertTrue("the seal must publish a generation for the reset to discard",
                    hasDurableTimelineGeneration(lvToken));

            final FilesFacade ff = configuration.getFilesFacade();
            try (Path path = new Path()) {
                Assert.assertTrue(ff.touch(ringManifestPath(path, lvToken).$()));
            }

            engine.getLiveViewRegistry().clear();
            engine.buildViewGraphs();

            try (Path path = new Path()) {
                Assert.assertFalse("the foreign artefact goes with the directory",
                        ff.exists(ringManifestPath(path, lvToken).$()));
            }
            Assert.assertFalse("so does every root it sat beside", hasDurableTimelineGeneration(lvToken));

            final LiveViewInstance recovered = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull("a reset costs derived state, not the view", recovered);
            Assert.assertFalse(recovered.isStub());
            Assert.assertEquals(LiveViewLifecycleState.ACTIVE, recovered.getLifecycleState());
            assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n2\n");

            // The base advances and the view refreshes forward over the rebuilt
            // state. The new 'a' row must read s=4 (1+3); an accumulator lost with
            // the checkpoints would restart the running sum at 3.
            execute("INSERT INTO base VALUES ('2026-04-01T00:00:02.000000Z', 'a', 3)");
            drainWalQueue();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                setCurrentMicros(4_000_000L);
                drainJob(job);
                drainWalQueue();
            }
            assertQuery("SELECT ts, sym, x, s FROM lv ORDER BY ts")
                    .noLeakCheck().timestamp("ts").expectSize()
                    .returns("ts\tsym\tx\ts\n" +
                            "2026-04-01T00:00:00.000000Z\ta\t1\t1.0\n" +
                            "2026-04-01T00:00:01.000000Z\tb\t2\t2.0\n" +
                            "2026-04-01T00:00:02.000000Z\ta\t3\t4.0\n");
            Assert.assertTrue("the seal after the reset publishes a fresh generation",
                    hasDurableTimelineGeneration(lvToken));

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testRestartRoundTripsLvConsumedSeqTxn() throws Exception {
        // Refresh writes + applies inline, so a successful refresh
        // cycle leaves no unapplied LV WAL block in steady state. This pins the
        // round-trip of lvConsumedSeqTxn and lastProcessedSeqTxn through restart.
        // (Recovery from a crash mid-cycle — between commitLiveView and the inline
        // apply — is a narrow window covered by the durability ordering inside
        // engine.advanceLiveViewConsumedSeqTxn and lives outside the smoke suite.)
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");
            execute("INSERT INTO base (ts, x) VALUES ('2026-04-01T00:00:00.000000Z', 4), " +
                    "('2026-04-01T00:01:00.000000Z', 8)");
            drainWalQueue();

            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            long postLastProcessed = instance.getLastProcessedSeqTxn();
            long postLvConsumed = instance.getStateReader().getLvConsumedSeqTxn();
            Assert.assertTrue("refresh must advance lastProcessedSeqTxn", postLastProcessed > 0);
            Assert.assertEquals(
                    "inline apply must advance lvConsumed to lastProcessed",
                    postLastProcessed,
                    postLvConsumed
            );

            // Simulate restart.
            engine.getLiveViewRegistry().clear();
            engine.buildViewGraphs();
            LiveViewInstance reloaded = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull("live view must be re-registered after restart", reloaded);
            Assert.assertEquals(
                    "lvConsumed must round-trip at the post-apply value",
                    postLvConsumed,
                    reloaded.getStateReader().getLvConsumedSeqTxn()
            );
            Assert.assertEquals(
                    "lastProcessed must round-trip at the post-apply value",
                    postLastProcessed,
                    reloaded.getLastProcessedSeqTxn()
            );

            // Data must already be visible without further apply.
            assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n2\n");

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testRestartContinuesProcessingNewBaseCommits() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");

            // First batch lands and is fully refreshed/applied.
            execute("INSERT INTO base (ts, x) VALUES ('2026-04-01T00:00:00.000000Z', 1)");
            drainWalQueue();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            drainWalQueue();
            assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n1\n");

            // Restart: the registry is rebuilt from disk.
            engine.getLiveViewRegistry().clear();
            engine.buildViewGraphs();

            // New base commits arrive after restart. The freshly-loaded LV instance
            // must pick them up via the refresh job's normal notification path. This
            // catches loader bugs where the registry is registered but the
            // liveViewStateStore base-table mapping is not, so notifications would
            // silently never enqueue a task for the reloaded view.
            execute("INSERT INTO base (ts, x) VALUES ('2026-04-02T00:00:00.000000Z', 2), " +
                    "('2026-04-02T00:01:00.000000Z', 3)");
            drainWalQueue();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            drainWalQueue();
            assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n3\n");

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testRestartWithTornStateAndNoRecoverableFloorSurfacesStateUnreadable() throws Exception {
        // Tier A fallback for the torn-_lv.s durability path: when the state file is
        // torn AND the LV's own WAL sequencer log holds no applied LIVE_VIEW_DATA block
        // (nothing was ever flushed, or the log was purged), there is no safe resume
        // floor. Registering the view ACTIVE with a too-low floor would replay the base
        // from the start and duplicate rows, so buildViewGraphs surfaces it as a
        // droppable state_unreadable stub instead of stranding it invisibly.
        assertMemoryLeak(() -> {
            setCurrentMicros(0);
            execute("CREATE TABLE base (ts TIMESTAMP, sym SYMBOL, x INT) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, sym, x, sum(x) OVER w AS s FROM base " +
                    "WINDOW w AS (PARTITION BY sym ORDER BY ts ANCHOR EXPRESSION timestamp_floor('1d', ts))");

            final TableToken lvToken = engine.getLiveViewRegistry().getViewInstance("lv").getLiveViewToken();

            // No refresh is ever driven, so no LIVE_VIEW_DATA block is committed to the
            // LV WAL: readLiveViewAppliedMaxBaseSeqTxn will return -1 (no recoverable floor).
            final FilesFacade ff = configuration.getFilesFacade();
            truncateLiveViewStateFile(ff, lvToken);

            // Restart: rebuild the registry from disk with the torn _lv.s in place.
            engine.getLiveViewRegistry().clear();
            engine.buildViewGraphs();

            // The view is registered as a droppable stub (not silently skipped) and
            // surfaces in live_views() as state_unreadable - distinct from a too-new
            // version_unsupported format.
            final LiveViewInstance stub = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull("torn _lv.s with no recoverable floor must register a stub", stub);
            Assert.assertTrue(stub.isStub());
            Assert.assertEquals(LiveViewLifecycleState.STATE_UNREADABLE, stub.getLifecycleState());
            assertQuery("SELECT view_name, view_status FROM live_views() WHERE view_name = 'lv'")
                    .noLeakCheck().noRandomAccess()
                    .returns("view_name\tview_status\nlv\tstate_unreadable\n");

            // DROP LIVE VIEW removes the stub best-effort - no longer an undroppable zombie.
            execute("DROP LIVE VIEW lv");
            assertQuery("SELECT count() FROM live_views() WHERE view_name = 'lv'")
                    .noLeakCheck().noRandomAccess().expectSize().returns("count\n0\n");
            assertQuery("SELECT count() FROM tables() WHERE table_name = 'lv'")
                    .noLeakCheck().noRandomAccess().expectSize().returns("count\n0\n");
        });
    }

    @Test
    public void testRestartWithTornStateStubDoesNotBreakFallbackScan() throws Exception {
        // Regression: the refresh worker's registry fallback scan (scanForLaggingViews)
        // iterates every registered view, including a definition-less state_unreadable
        // stub left by a torn _lv.s with no recoverable floor. The stub is neither
        // dropped nor invalid, so it slipped past the scan's skip guard and NPE'd on
        // getDefinition().getBaseTableToken() - crashing the shared worker turn every
        // fallback tick and starving healthy sibling views of their fallback services.
        // The scan must skip the stub (like the catalogue reader does) and still refresh
        // a healthy sibling.
        assertMemoryLeak(() -> {
            setCurrentMicros(0);
            execute("CREATE TABLE base (ts TIMESTAMP, sym SYMBOL, x INT) TIMESTAMP(ts) PARTITION BY DAY WAL");
            // lv_ok is a healthy sibling; lv_stub becomes the torn stub. Neither is
            // refreshed before the fault, so lv_stub commits no LIVE_VIEW_DATA block and
            // thus has no recoverable floor once its _lv.s is torn (-> state_unreadable).
            execute("CREATE LIVE VIEW lv_ok FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, sym, x, sum(x) OVER w AS s FROM base " +
                    "WINDOW w AS (PARTITION BY sym ORDER BY ts ANCHOR EXPRESSION timestamp_floor('1d', ts))");
            execute("CREATE LIVE VIEW lv_stub FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, sym, x, sum(x) OVER w AS s FROM base " +
                    "WINDOW w AS (PARTITION BY sym ORDER BY ts ANCHOR EXPRESSION timestamp_floor('1d', ts))");

            final TableToken stubToken = engine.getLiveViewRegistry().getViewInstance("lv_stub").getLiveViewToken();

            // Base commits land while both views sit un-refreshed, so after the restart
            // lv_ok lags the base head and the fallback scan (not a notification) is what
            // must drive its first refresh.
            execute("INSERT INTO base VALUES " +
                    "('2026-04-01T00:00:00.000000Z', 'a', 1), " +
                    "('2026-04-01T00:00:01.000000Z', 'b', 2)");
            drainWalQueue();

            // Tear lv_stub's _lv.s and restart: it registers as a droppable
            // state_unreadable stub, lv_ok reloads as a healthy ACTIVE view.
            truncateLiveViewStateFile(configuration.getFilesFacade(), stubToken);
            engine.getLiveViewRegistry().clear();
            engine.buildViewGraphs();

            final LiveViewInstance stub = engine.getLiveViewRegistry().getViewInstance("lv_stub");
            Assert.assertNotNull(stub);
            Assert.assertTrue(stub.isStub());
            Assert.assertEquals(LiveViewLifecycleState.STATE_UNREADABLE, stub.getLifecycleState());
            final LiveViewInstance ok = engine.getLiveViewRegistry().getViewInstance("lv_ok");
            Assert.assertNotNull(ok);
            Assert.assertFalse(ok.isStub());

            // Drive the fallback scan. Pre-fix this NPEs on the stub inside the worker
            // turn; the fix skips the stub so the drain completes and lv_ok refreshes.
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                setCurrentMicros(2_000_000L);
                drainJob(job);
                drainWalQueue();
            }

            // The healthy sibling refreshed forward past the stub in the same scan.
            assertQuery("SELECT ts, sym, x, s FROM lv_ok ORDER BY ts")
                    .noLeakCheck().timestamp("ts").expectSize()
                    .returns("ts\tsym\tx\ts\n" +
                            "2026-04-01T00:00:00.000000Z\ta\t1\t1.0\n" +
                            "2026-04-01T00:00:01.000000Z\tb\t2\t2.0\n");

            // The stub was never spuriously refreshed - still a droppable state_unreadable
            // stub, and DROP LIVE VIEW removes it.
            final LiveViewInstance stubAfter = engine.getLiveViewRegistry().getViewInstance("lv_stub");
            Assert.assertNotNull(stubAfter);
            Assert.assertTrue(stubAfter.isStub());
            Assert.assertEquals(LiveViewLifecycleState.STATE_UNREADABLE, stubAfter.getLifecycleState());
            assertQuery("SELECT view_name, view_status FROM live_views() WHERE view_name = 'lv_stub'")
                    .noLeakCheck().noRandomAccess()
                    .returns("view_name\tview_status\nlv_stub\tstate_unreadable\n");
            execute("DROP LIVE VIEW lv_stub");
            assertQuery("SELECT count() FROM live_views() WHERE view_name = 'lv_stub'")
                    .noLeakCheck().noRandomAccess().expectSize().returns("count\n0\n");
        });
    }

    @Test
    public void testRestartWithTornStateButValidHeadCheckpoint() throws Exception {
        // Torn-_lv.s recovery (the "head checkpoint valid but _lv.s write was torn" durability
        // case). A torn _lv.s throws a CairoException whose errno is NOT
        // LV_FILE_VERSION_UNSUPPORTED. Rather than silently skip the view (which stranded
        // it as an invisible, frozen, undroppable zombie), buildViewGraphs reconstructs
        // the lost durable watermarks from the last applied LIVE_VIEW_DATA block in the
        // LV's own WAL sequencer log and resumes the view ACTIVE: the head checkpoint restores
        // the window accumulators and the forward drain catches up. This test truncates
        // _lv.s while leaving the head checkpoint and the _lv table data intact, then asserts the
        // view recovers, converges to a from-scratch recompute (the accumulator for the
        // partition that spans the fault must survive), rewrites a valid _lv.s (a second
        // restart takes the normal path), and stays droppable.
        assertMemoryLeak(() -> {
            setCurrentMicros(0);
            execute("CREATE TABLE base (ts TIMESTAMP, sym SYMBOL, x INT) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, sym, x, sum(x) OVER w AS s FROM base " +
                    "WINDOW w AS (PARTITION BY sym ORDER BY ts ANCHOR EXPRESSION timestamp_floor('1d', ts))");

            final TableToken lvToken = engine.getLiveViewRegistry().getViewInstance("lv").getLiveViewToken();

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                execute("INSERT INTO base VALUES " +
                        "('2026-04-01T00:00:00.000000Z', 'a', 1), " +
                        "('2026-04-01T00:00:01.000000Z', 'b', 2)");
                drainWalQueue();
                setCurrentMicros(2_000_000L);
                drainJob(job);
                drainWalQueue();
            }
            // Before the fault: the view holds 2 committed, durable rows in its _lv table.
            assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n2\n");

            final FilesFacade ff = configuration.getFilesFacade();

            // The head checkpoint survives untouched (the "valid checkpoint" half of the asymmetry):
            // it carries the window accumulators as of the flush point, incl. sum(x)=1 for 'a'.
            try (Path cpDir = new Path()) {
                cpDir.of(configuration.getDbRoot()).concat(lvToken).concat(LiveViewCheckpointLayout.CHECKPOINT_DIR_NAME);
                Assert.assertTrue("head checkpoint dir must survive the fault", ff.exists(cpDir.$()));
            }

            // Inject the torn write: truncate _lv.s below HEADER_SIZE so BlockFileReader.of
            // throws "block file too small" (errno 0) - the non-version branch.
            truncateLiveViewStateFile(ff, lvToken);

            // Restart: rebuild the registry from disk with the torn _lv.s in place.
            engine.getLiveViewRegistry().clear();
            engine.buildViewGraphs();

            // The view recovers ACTIVE - registered, visible in live_views(), rows intact.
            final LiveViewInstance recovered = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull("torn _lv.s must recover, not strand the view", recovered);
            Assert.assertFalse("recovered view is a real instance, not a stub", recovered.isStub());
            Assert.assertEquals(LiveViewLifecycleState.ACTIVE, recovered.getLifecycleState());
            assertQuery("SELECT view_name, view_status FROM live_views() WHERE view_name = 'lv'")
                    .noLeakCheck().noRandomAccess()
                    .returns("view_name\tview_status\nlv\tactive\n");
            assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n2\n");

            // The base advances; the recovered view refreshes forward and converges. The new
            // 'a' row must read s=4 (1+3), proving the head checkpoint restored the 'a' accumulator
            // across the fault - a lost accumulator would restart the running sum at 3.
            execute("INSERT INTO base VALUES ('2026-04-01T00:00:02.000000Z', 'a', 3)");
            drainWalQueue();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                setCurrentMicros(4_000_000L);
                drainJob(job);
                drainWalQueue();
            }
            assertQuery("SELECT ts, sym, x, s FROM lv ORDER BY ts")
                    .noLeakCheck().timestamp("ts").expectSize()
                    .returns("ts\tsym\tx\ts\n" +
                            "2026-04-01T00:00:00.000000Z\ta\t1\t1.0\n" +
                            "2026-04-01T00:00:01.000000Z\tb\t2\t2.0\n" +
                            "2026-04-01T00:00:02.000000Z\ta\t3\t4.0\n");

            // Recovery rewrote a valid _lv.s: a second restart takes the normal load path
            // (still ACTIVE, no stub, data intact) and keeps converging.
            engine.getLiveViewRegistry().clear();
            engine.buildViewGraphs();
            final LiveViewInstance reloaded = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull("rewritten _lv.s must load on a clean restart", reloaded);
            Assert.assertFalse(reloaded.isStub());
            Assert.assertEquals(LiveViewLifecycleState.ACTIVE, reloaded.getLifecycleState());
            assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n3\n");

            // The recovered view remains droppable via SQL - no longer a zombie.
            execute("DROP LIVE VIEW lv");
            assertQuery("SELECT count() FROM live_views() WHERE view_name = 'lv'")
                    .noLeakCheck().noRandomAccess().expectSize().returns("count\n0\n");
            assertQuery("SELECT count() FROM tables() WHERE table_name = 'lv'")
                    .noLeakCheck().noRandomAccess().expectSize().returns("count\n0\n");
        });
    }

    // Truncates a live view's _lv.s below the BlockFile header so BlockFileReader.of
    // throws "block file too small" (errno 0) - a faithful torn-partial-write artifact
    // on the non-version branch.

    /**
     * Reads the seed cursor the view's durable timeline generation carries, or
     * {@link Numbers#LONG_NULL} when it has no valid generation or the generation was published by
     * a steady seal. This is the coordinate a restart resumes the sweep from.
     */
    private long durableSeedCursorOffset(LiveViewInstance instance) {
        try (
                Path checkpointsDir = new Path();
                LiveViewCheckpointMetaStore metaStore = new LiveViewCheckpointMetaStore(engine.getConfiguration())
        ) {
            checkpointsDir.of(engine.getConfiguration().getDbRoot())
                    .concat(instance.getLiveViewToken())
                    .concat(LiveViewCheckpointLayout.CHECKPOINT_DIR_NAME);
            metaStore.of(checkpointsDir);
            return metaStore.isValid() ? metaStore.getSuperblock().seedCursorOffset : Numbers.LONG_NULL;
        }
    }

    /**
     * @return true when the view's checkpoint directory holds a superblock slot
     * that passes bounded validation, i.e. a generation a restart could adopt
     */
    private boolean hasDurableTimelineGeneration(TableToken lvToken) {
        try (Path checkpointsDir = new Path(); Path timelinePath = new Path()) {
            checkpointsDir.of(configuration.getDbRoot())
                    .concat(lvToken)
                    .concat(LiveViewCheckpointLayout.CHECKPOINT_DIR_NAME);
            LiveViewCheckpointLayout.timelinePath(timelinePath, checkpointsDir);
            // Opening the store would recreate _timeline, so a reset directory is
            // recognized by the absent file rather than by an invalid slot.
            if (!configuration.getFilesFacade().exists(timelinePath.$())) {
                return false;
            }
            try (LiveViewCheckpointMetaStore metaStore = new LiveViewCheckpointMetaStore(engine.getConfiguration())) {
                metaStore.of(checkpointsDir);
                return metaStore.isValid();
            }
        }
    }

    /**
     * Points {@code path} at the retained-ring manifest an earlier development
     * build wrote at the top level of {@code _checkpoints}.
     */
    private Path ringManifestPath(Path path, TableToken lvToken) {
        return path.of(configuration.getDbRoot())
                .concat(lvToken)
                .concat(LiveViewCheckpointLayout.CHECKPOINT_DIR_NAME)
                .concat("_ring");
    }

    private void truncateLiveViewStateFile(FilesFacade ff, TableToken lvToken) {
        try (Path sPath = new Path()) {
            sPath.of(configuration.getDbRoot()).concat(lvToken).concat(LiveViewState.LIVE_VIEW_STATE_FILE_NAME);
            Assert.assertTrue(ff.exists(sPath.$()));
            final long fd = ff.openRW(sPath.$(), CairoConfiguration.O_NONE);
            Assert.assertTrue(fd > 0);
            try {
                Assert.assertTrue(ff.truncate(fd, 8));
            } finally {
                ff.close(fd);
            }
        }
    }

    @Test
    public void testRestartWithUnappliedBaseSeqTxnConverges() throws Exception {
        // Distinct from "retained base WAL": here the base's OWN table lags its sequencer at restart.
        // batch2 is committed to the base WAL but never applied to the base table (no drainWalQueue),
        // so the base table's applied seqTxn sits behind the sequencer's committed seqTxn. The LV,
        // refreshed only through batch1, is consistent with the applied base at restart. Rebuilding the
        // registry from disk and then draining must apply the pending base WAL and refresh forward,
        // converging to a from-scratch recompute over the full base - without losing batch2 or
        // re-emitting batch1. The window carries a daily ANCHOR but all rows sit on one day, so the
        // running sum never resets and equals the plain sum(x) OVER (PARTITION BY sym ORDER BY ts)
        // recompute.
        assertMemoryLeak(() -> {
            setCurrentMicros(0);
            execute("CREATE TABLE base (ts TIMESTAMP, sym SYMBOL, x INT) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, sym, x, sum(x) OVER w AS s FROM base " +
                    "WINDOW w AS (PARTITION BY sym ORDER BY ts ANCHOR EXPRESSION timestamp_floor('1d', ts))");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                // batch1: applied to the base and refreshed into the view.
                execute("INSERT INTO base VALUES " +
                        "('2026-04-01T00:00:00.000000Z', 'a', 1), " +
                        "('2026-04-01T00:00:01.000000Z', 'b', 2)");
                drainWalQueue();
                setCurrentMicros(2_000_000L);
                drainJob(job);
                drainWalQueue();
                assertRunningSumLvMatchesRecompute();

                // batch2: committed to the base WAL but deliberately NOT applied - the base table now
                // lags its sequencer.
                execute("INSERT INTO base VALUES " +
                        "('2026-04-01T00:00:02.000000Z', 'a', 3), " +
                        "('2026-04-01T00:00:03.000000Z', 'b', 4)");
            }

            // Restart while batch2 is still unapplied to the base table.
            engine.getLiveViewRegistry().clear();
            engine.buildViewGraphs();

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                setCurrentMicros(4_000_000L);
                drainWalQueue(); // applies the pending batch2 to the base table
                drainJob(job);
                drainWalQueue();

                // Converged over the full base with no loss and no duplication.
                assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n4\n");
                assertRunningSumLvMatchesRecompute();
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testMultipleLiveViewsOverSameBaseRefreshTogether() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            // Two LVs over the same base with different SELECT shapes. A single base
            // commit must fan out to BOTH via getViewsForBaseTable; the per-instance
            // refresh latch must not block one LV from refreshing while the other is.
            execute("CREATE LIVE VIEW lv1 FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");
            execute("CREATE LIVE VIEW lv2 FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 5");

            execute("INSERT INTO base (ts, x) VALUES ('2026-05-01T00:00:00.000000Z', 3), " +
                    "('2026-05-01T00:01:00.000000Z', 7), " +
                    "('2026-05-01T00:02:00.000000Z', 12)");
            drainWalQueue();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            drainWalQueue();

            // lv1: x > 0 keeps all three rows.
            assertQuery("SELECT count() FROM lv1").noLeakCheck().noRandomAccess().expectSize().returns("count\n3\n");
            // lv2: x > 5 keeps the 7 and 12.
            assertQuery("SELECT count() FROM lv2").noLeakCheck().noRandomAccess().expectSize().returns("count\n2\n");

            // Both LVs must have actually advanced their state independently — verify
            // neither is stuck at zero (which would happen if refresh skipped one of them).
            LiveViewInstance i1 = engine.getLiveViewRegistry().getViewInstance("lv1");
            LiveViewInstance i2 = engine.getLiveViewRegistry().getViewInstance("lv2");
            Assert.assertTrue("lv1 must advance", i1.getLastProcessedSeqTxn() > 0);
            Assert.assertTrue("lv2 must advance", i2.getLastProcessedSeqTxn() > 0);

            execute("DROP LIVE VIEW lv1");
            execute("DROP LIVE VIEW lv2");
        });
    }

    @Test
    public void testLiveViewAsAsofJoinRhs() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");
            execute("CREATE TABLE probe (ts TIMESTAMP, label SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("INSERT INTO base (ts, x) VALUES " +
                    "('2026-03-01T00:00:00.000000Z', 10), ('2026-03-01T00:01:00.000000Z', 20)");
            execute("INSERT INTO probe (ts, label) VALUES " +
                    "('2026-03-01T00:00:30.000000Z', 'a'), ('2026-03-01T00:01:30.000000Z', 'b')");
            drainWalQueue();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            drainWalQueue();

            // ASOF JOIN against the LV as RHS: each probe row should pick up the
            // latest LV row at or before the probe ts.
            assertQuery("SELECT probe.ts, probe.label, lv.x, lv.rn " +
                    "FROM probe ASOF JOIN lv").noLeakCheck().timestamp("ts").noRandomAccess().expectSize().returns("ts\tlabel\tx\trn\n" +
                    "2026-03-01T00:00:30.000000Z\ta\t10\t1\n" +
                    "2026-03-01T00:01:30.000000Z\tb\t20\t2\n");

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testDependencyColumnIndexesPopulated() throws Exception {
        assertMemoryLeak(() -> {
            // Base has four columns (ts, x, y, z); LV references only ts + x.
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, y INT, z INT) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY x ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");

            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            // ts + x should be the dependency set; y and z must not appear.
            Assert.assertEquals(2, instance.getDependencyColumnNames().size());

            // Restart sweep: the dependency set lives in _lv, so reload restores it
            // before any refresh runs. A schema change between restart and first
            // refresh would otherwise fall back to the broad invalidation path.
            engine.getLiveViewRegistry().clear();
            engine.buildViewGraphs();
            LiveViewInstance reloaded = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertEquals(2, reloaded.getDependencyColumnNames().size());

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testFallbackScanPicksUpMissedNotifications() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");

            // Drain the notification state store BEFORE inserting — this simulates a
            // missed notification (e.g., the worker was busy elsewhere when the commit
            // landed, and the dedup gate dropped subsequent notifications).
            engine.getLiveViewStateStore().clear();

            execute("INSERT INTO base (ts, x) VALUES " +
                    "('2026-04-01T00:00:00.000000Z', 11), ('2026-04-01T00:01:00.000000Z', 22)");
            drainWalQueue();

            // Notification queue is empty; the refresh job's fallback scan must catch
            // the lag and refresh the LV.
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            drainWalQueue();

            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertTrue(
                    "fallback scan must advance lastProcessedSeqTxn",
                    instance.getLastProcessedSeqTxn() > 0
            );
            assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n2\n");

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testFlushEveryRateLimitsCommits() throws Exception {
        assertMemoryLeak(() -> {
            // Pin the test clock so the FLUSH EVERY 1s gate is exercised
            // deterministically: both batches land at t=0, so the second refresh
            // must be skipped; only after we advance the clock past 1s does
            // the LV catch up.
            setCurrentMicros(0);
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                // Batch 1 at t=0: passes the gate (lastFlushTimeUs is unset).
                execute("INSERT INTO base (ts, x) VALUES ('2026-04-01T00:00:00.000000Z', 1)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(instance);
                long firstFlushUs = instance.getLastFlushTimeUs();
                Assert.assertEquals("first refresh must record the commit timestamp", 0L, firstFlushUs);
                long firstProcessed = instance.getLastProcessedSeqTxn();
                Assert.assertTrue("first refresh must advance lastProcessedSeqTxn", firstProcessed > 0);

                // Batch 2 still at t=0: refresh must be skipped because we are
                // within the 1s rate-limit window.
                execute("INSERT INTO base (ts, x) VALUES ('2026-04-01T00:00:00.000001Z', 2)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();
                Assert.assertEquals(
                        "rate-limited refresh must not advance lastFlushTimeUs",
                        firstFlushUs,
                        instance.getLastFlushTimeUs()
                );
                Assert.assertEquals(
                        "rate-limited refresh must not advance lastProcessedSeqTxn",
                        firstProcessed,
                        instance.getLastProcessedSeqTxn()
                );

                // Advance past FLUSH EVERY: the fallback scan must pick up the
                // pending commit and refresh now succeeds.
                setCurrentMicros(2_000_000L);
                drainJob(job);
                drainWalQueue();
                Assert.assertEquals(
                        "post-window refresh must record the new commit timestamp",
                        2_000_000L,
                        instance.getLastFlushTimeUs()
                );
                Assert.assertTrue(
                        "post-window refresh must advance lastProcessedSeqTxn",
                        instance.getLastProcessedSeqTxn() > firstProcessed
                );
            }

            assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n2\n");
            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testFlushLeadInlineApplyFailureRecoversWithoutDuplication() throws Exception {
        // A flush that commits the lead's LV-WAL block but fails the inline apply of
        // that block must recover with every row landing exactly once. The apply does
        // not surface the failure: ApplyWal2TableJob.applyWal suspends the table and
        // returns, so flushLead still runs its trailing setLeadRowCount(0) and the
        // committed-but-unapplied block cannot be re-materialised into a second block
        // on the next flush (which would duplicate the lead). The view serves disk-only
        // until the suspended apply resumes and the deferred block lands once.
        //
        // The fault targets the inline apply: the failing flush's derived row lands in
        // a brand-new LV partition (a different day than the baseline row), so the apply
        // must create it and openRW its x.d - an uncached open a same-partition append
        // would skip. We fail that openRW once, after the commit made the block durable;
        // the fault self-clears so the deferred apply reads cleanly.
        final String[] lvDir = new String[1];
        final AtomicBoolean failNewPartitionApply = new AtomicBoolean(false);
        FilesFacade ff = new TestFilesFacadeImpl() {
            @Override
            public long openRW(LPSZ name, int opts) {
                if (failNewPartitionApply.get()
                        && lvDir[0] != null
                        && Utf8s.endsWithAscii(name, "x.d")
                        && Utf8s.containsAscii(name, lvDir[0])
                        && Utf8s.containsAscii(name, "2026-04-02")
                        && failNewPartitionApply.compareAndSet(true, false)) {
                    return -1;
                }
                return super.openRW(name, opts);
            }
        };

        assertMemoryLeak(ff, () -> {
            setCurrentMicros(0);
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");
            lvDir[0] = engine.verifyTableName("lv").getDirName();
            final TableToken lvToken = engine.verifyTableName("lv");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                // Baseline clean flush of the first row (day 1): sets lastFlushTimeUs
                // and the day-1 LV partition, no un-flushed lead, zeroed retry budget.
                execute("INSERT INTO base (ts, x) VALUES ('2026-04-01T00:00:00.000000Z', 1)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(instance);
                Assert.assertEquals("clean baseline leaves no retries", 0, instance.getFlushRetryCount());

                // Failing flush: the second row lands in a new day-2 partition. flushLead
                // commits the lead, advances the watermarks, then the inline apply fails
                // creating that partition and suspends the LV table. The block stays
                // committed-but-unapplied, so reads see only the baseline row meanwhile.
                setCurrentMicros(2_000_000L);
                execute("INSERT INTO base (ts, x) VALUES ('2026-04-02T00:00:00.000000Z', 2)");
                drainWalQueue();
                failNewPartitionApply.set(true);
                drainJob(job);
                Assert.assertFalse("the inline apply openRW must have been failed exactly once",
                        failNewPartitionApply.get());
                Assert.assertTrue("the failed inline apply must suspend the LV table",
                        engine.getTableSequencerAPI().isSuspended(lvToken));
                Assert.assertFalse("a suspended apply must not invalidate the view",
                        instance.isInvalid());
                assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n1\n");
                // A count() alone reads size() only; a full scan must agree with it. If the
                // failed inline apply left the slot re-stamped as a subset of a disk that never
                // received the flushed lead, hasNext() serves the committed-but-unapplied lead
                // row while size() reports disk-only - count() and a full scan disagree.
                assertQuery("SELECT ts, x, rn FROM lv").noLeakCheck().timestamp("ts").expectSize().returns(
                        "ts\tx\trn\n" +
                                "2026-04-01T00:00:00.000000Z\t1\t1\n");

                // Recovery: a third row (day 2) drives a clean flush with the fault
                // cleared. Resuming the suspended apply lands the deferred block plus
                // the new row. Every base row must land exactly once - row numbers stay
                // 1..3 with no duplicate row 2 (a re-materialised lead gives count 4).
                setCurrentMicros(4_000_000L);
                execute("INSERT INTO base (ts, x) VALUES ('2026-04-02T00:00:01.000000Z', 3)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                Assert.assertFalse("the LV table must resume after the fault clears",
                        engine.getTableSequencerAPI().isSuspended(lvToken));
                assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n3\n");
                assertQuery("SELECT ts, x, rn FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns(
                        "ts\tx\trn\n" +
                                "2026-04-01T00:00:00.000000Z\t1\t1\n" +
                                "2026-04-02T00:00:00.000000Z\t2\t2\n" +
                                "2026-04-02T00:00:01.000000Z\t3\t3\n");
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testFlushLeadUnappliedBlockIsRetriedOnQuiescentBase() throws Exception {
        // On a primary the refresh worker owns the LV's TableWriter, so
        // ApplyWal2TableJob.doRun drops every live-view WAL notification and flushLead's
        // inline applyWalDirect is the view's ONLY applier. When that apply no-ops - here
        // because another owner holds the LV TableWriter, so applyWal returns on
        // EntryUnavailableException without advancing anything - the committed block stays
        // off disk while the flush has already zeroed the lead and re-stamped the slot with
        // the pre-apply seqTxn. Neither tier then serves those rows: the view silently
        // under-reports, with no suspension to signal it. Nothing republishes an LV
        // notification, so before the fix only a later base commit (driving another flush)
        // could land the block - on a quiescent base, never. scanForLaggingViews must retry
        // the apply itself.
        assertMemoryLeak(() -> {
            setCurrentMicros(0);
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");
            final TableToken lvToken = engine.verifyTableName("lv");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                // Baseline clean flush: applies inline and initialises the LV's applied seqTxn.
                execute("INSERT INTO base (ts, x) VALUES ('2026-04-01T00:00:00.000000Z', 1)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();
                assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize()
                        .returns("count\n1\n");

                // Second row: hold the LV TableWriter across the flush so its inline apply
                // hits EntryUnavailableException and returns without applying. Use the WAL
                // apply lock reason, which applyWal treats as a legitimate concurrent holder
                // (isUnsolicitedTableLock) rather than a lock leak.
                setCurrentMicros(2_000_000L);
                execute("INSERT INTO base (ts, x) VALUES ('2026-04-01T00:00:01.000000Z', 2)");
                drainWalQueue();
                try (TableWriter ignore = engine.getWriterUnsafe(lvToken, TableUtils.WAL_2_TABLE_WRITE_REASON)) {
                    drainJob(job);
                }

                // The block is committed but unapplied, and no suspension flags it. The row is
                // invisible: the flush zeroed the lead, and disk never received it.
                final SeqTxnTracker tracker = engine.getTableSequencerAPI().getTxnTracker(lvToken);
                Assert.assertTrue("the busy-writer apply must leave the block unapplied",
                        tracker.getSeqTxn() > tracker.getWriterTxn());
                Assert.assertFalse("a busy writer must not suspend the LV table",
                        engine.getTableSequencerAPI().isSuspended(lvToken));
                assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize()
                        .returns("count\n1\n");

                // The base is now quiescent - no new commits, so no flush would ever run again.
                // The scan must still notice the unapplied block and re-drive the apply itself.
                drainJob(job);
                drainWalQueue();

                Assert.assertEquals("the retried apply must catch the LV table up",
                        tracker.getSeqTxn(), tracker.getWriterTxn());
                assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize()
                        .returns("count\n2\n");
                assertQuery("SELECT ts, x, rn FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize()
                        .returns("ts\tx\trn\n" +
                                "2026-04-01T00:00:00.000000Z\t1\t1\n" +
                                "2026-04-01T00:00:01.000000Z\t2\t2\n");
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testSeedResumeWaitsForPendingApplyBeforeReadingFloor() throws Exception {
        // Regression for the seed-resume floor: the resume path calls the void applyWalDirect to
        // fold a committed-but-unapplied seed block into the on-disk row count it derives the
        // skip-write floor from, then immediately stamps the single-shot resume flag and reads that
        // floor. applyWalDirect is non-throwing: when the LV TableWriter is busy it returns on
        // EntryUnavailableException without applying (no suspension). The block then stays off disk,
        // the floor under-counts it, and the resumed sweep re-emits the row - which duplicates once
        // the block finally applies (the seed append carries no dedup to collapse it). The resume
        // must verify the LV writer caught up to its committed seqTxn before trusting the floor.
        setProperty(PropertyKey.CAIRO_LIVE_VIEW_CHECKPOINT_ROWS, 1); // one admitted row per seed turn
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("INSERT INTO base (ts, x) VALUES " +
                    "('2026-04-01T00:00:01.000000Z', 1), " +
                    "('2026-04-01T00:00:02.000000Z', 2), " +
                    "('2026-04-01T00:00:03.000000Z', 3)");
            drainWalQueue();
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM BEGINNING AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");
            final TableToken lvToken = engine.verifyTableName("lv");
            final SeqTxnTracker tracker = engine.getTableSequencerAPI().getTxnTracker(lvToken);

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                // Turn 1: sweep row 1 and commit its LV block, but hold the LV TableWriter so the
                // inline apply no-ops via EntryUnavailableException (a busy writer, as on a primary
                // whose refresh worker owns it). The block is committed-but-unapplied and the view
                // stays SEEDING - the exact crash-between-commit-and-apply state a restart inherits.
                try (TableWriter ignore = engine.getWriterUnsafe(lvToken, TableUtils.WAL_2_TABLE_WRITE_REASON)) {
                    job.run();
                    drainWalQueue();
                }
                LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(instance);
                Assert.assertEquals("the view must still be SEEDING",
                        LiveViewState.SEED_STATE_SEEDING, instance.getStateReader().getSeedState());
                Assert.assertTrue("the seed block must be committed but unapplied",
                        tracker.getSeqTxn() > tracker.getWriterTxn());

                // Restart: seedResumeAttempted resets, the SEEDING view reloads from disk, and its
                // committed-but-unapplied block is still pending (the global apply path skips LV
                // tokens, and the SEEDING branch of the restart reconcile does not touch it).
                engine.getLiveViewRegistry().clear();
                engine.buildViewGraphs();
                Assert.assertTrue("the block is still pending after the restart",
                        tracker.getSeqTxn() > tracker.getWriterTxn());

                // Drive the resume with the LV writer held again, so the resume applyWalDirect
                // no-ops. The bug stamps the flag and re-sweeps off an under-read (0-row) floor; the
                // fix leaves the view SEEDING with the flag unset and re-attempts next turn.
                try (TableWriter ignore = engine.getWriterUnsafe(lvToken, TableUtils.WAL_2_TABLE_WRITE_REASON)) {
                    for (int i = 0; i < 4; i++) {
                        job.run();
                        drainWalQueue();
                    }
                }

                // Writer released: the deferred block applies and the seed finishes. Every base row
                // must land exactly once.
                driveSeedToCompletion(job, "lv");
                driveRefreshToQuiescence(job);
            }

            assertQuery("SELECT ts, x, rn FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns("ts\tx\trn\n" +
                    "2026-04-01T00:00:01.000000Z\t1\t1\n" +
                    "2026-04-01T00:00:02.000000Z\t2\t2\n" +
                    "2026-04-01T00:00:03.000000Z\t3\t3\n");

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testFlushRetryBudgetExhaustionInvalidatesView() throws Exception {
        // Persist failures retry up to cairo.live.view.flush.retry.max
        // (or .duration, whichever fires first). On budget exhaustion the view is
        // invalidated via the unified path. We force consecutive _lv.s persist failures
        // on the refresh worker and assert the LV flips to INVALID after the configured
        // count.
        setProperty(PropertyKey.CAIRO_LIVE_VIEW_FLUSH_RETRY_MAX, 2);
        // Set a duration cap large enough that the count trigger fires first.
        setProperty(PropertyKey.CAIRO_LIVE_VIEW_FLUSH_RETRY_MAX_DURATION_MICROS, Micros.HOUR_MICROS);

        final AtomicBoolean failPersist = new AtomicBoolean(false);
        FilesFacade ff = new TestFilesFacadeImpl() {
            @Override
            public long openRW(LPSZ name, int opts) {
                if (failPersist.get() && Utf8s.endsWithAscii(name, LiveViewState.LIVE_VIEW_STATE_FILE_NAME)) {
                    return -1;
                }
                return super.openRW(name, opts);
            }
        };

        assertMemoryLeak(ff, () -> {
            setCurrentMicros(0);
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                // Happy-path drain seeds lastFlushTimeUs and lvConsumedSeqTxn.
                execute("INSERT INTO base (ts, x) VALUES ('2026-04-01T00:00:00.000001Z', 1)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(instance);
                Assert.assertFalse("LV must be valid after happy path", instance.isInvalid());

                failPersist.set(true);
                try {
                    // Two consecutive persist failures: first hits retryCount=1 (budget
                    // not exhausted, log only); second hits retryCount=2 == max → invalidate.
                    setCurrentMicros(200_000L);
                    execute("INSERT INTO base (ts, x) VALUES ('2026-04-01T00:00:00.000002Z', 2)");
                    drainWalQueue();
                    drainJob(job);
                    Assert.assertEquals("first failure must increment retryCount to 1",
                            1, instance.getFlushRetryCount());
                    Assert.assertFalse("LV must still be valid after one failure",
                            instance.isInvalid());

                    setCurrentMicros(400_000L);
                    execute("INSERT INTO base (ts, x) VALUES ('2026-04-01T00:00:00.000003Z', 3)");
                    drainWalQueue();
                    drainJob(job);
                    Assert.assertTrue("second failure (retryCount=2) must exhaust the budget",
                            instance.isInvalid());
                    Assert.assertTrue(
                            "invalidation reason must mention flush retry [reason=" + instance.getInvalidationReason() + "]",
                            Chars.contains(instance.getInvalidationReason(), "flush retry budget")
                    );
                } finally {
                    failPersist.set(false);
                }
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testFlushRetryBudgetTransientTableMissDoesNotInvalidate() throws Exception {
        // A transient "table does not exist" must NOT count toward the COUNT
        // budget. handleRefreshFailure gates the tableTransient case
        // (CairoException.isTableDoesNotExist()) on the wall-clock DURATION
        // budget only, so a fast refresh worker cannot brick a healthy view
        // inside the sub-millisecond CREATE deferred-name window (getWalWriter
        // throws "table does not exist" until the name commits) or a concurrent
        // DROP. We reproduce the transient by locking the LV's WAL writer pool:
        // getWalWriter then raises EntryLockedException -> tableDoesNotExist.
        // Complements testFlushRetryBudgetExhaustionInvalidatesView, which
        // injects a generic (non-transient) CairoException and drives the
        // opposite branch (retryCount >= max invalidates).
        setProperty(PropertyKey.CAIRO_LIVE_VIEW_FLUSH_RETRY_MAX, 2);
        // Large duration cap: the count trigger would fire first if the gate
        // wrongly counted the transient.
        setProperty(PropertyKey.CAIRO_LIVE_VIEW_FLUSH_RETRY_MAX_DURATION_MICROS, Micros.HOUR_MICROS);

        assertMemoryLeak(() -> {
            setCurrentMicros(0);
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                // Happy-path drain seeds lastFlushTimeUs and lvConsumedSeqTxn.
                execute("INSERT INTO base (ts, x) VALUES ('2026-04-01T00:00:00.000001Z', 1)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(instance);
                Assert.assertFalse("LV must be valid after happy path", instance.isInvalid());

                // Lock the LV's WAL writer pool: any getWalWriter(lvToken) now
                // throws EntryLockedException, which getWalWriterUnsafe converts
                // to CairoException.tableDoesNotExist. get0() throws on any locked
                // entry regardless of the calling thread, so this fires even
                // though the refresh runs on the test thread.
                final TableToken lvToken = instance.getLiveViewToken();
                Assert.assertTrue("must lock LV WAL writers", engine.lockWalWriters(lvToken));
                try {
                    // Drive well past CAIRO_LIVE_VIEW_FLUSH_RETRY_MAX failing
                    // cycles while keeping elapsed under the duration cap.
                    for (int i = 0; i < 5; i++) {
                        setCurrentMicros(200_000L * (i + 1));
                        execute("INSERT INTO base (ts, x) VALUES ('2026-04-01T00:00:00.00000" + (i + 2) + "Z', " + (i + 2) + ")");
                        drainWalQueue();
                        drainJob(job);
                    }
                    Assert.assertTrue("retryCount must climb past the count budget on the transient",
                            instance.getFlushRetryCount() > 2);
                    Assert.assertFalse("a transient table miss must NOT invalidate under the duration cap",
                            instance.isInvalid());
                } finally {
                    engine.unlockWalWriters(lvToken);
                }

                // Once the transient clears, the next refresh succeeds, resets
                // the retry budget, and the view catches up while still valid.
                setCurrentMicros(2_000_000L);
                drainJob(job);
                drainWalQueue();
                Assert.assertFalse("view must stay valid once the table resolves", instance.isInvalid());
                Assert.assertEquals("retry budget resets after a successful refresh",
                        0, instance.getFlushRetryCount());
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testFlushRetryBudgetTransientTableMissInvalidatesOnDurationCap() throws Exception {
        // The tableTransient gate is duration-bounded, not infinite: a table
        // that never resolves (WAL writers stay locked past the wall-clock cap)
        // still invalidates once elapsedUs >= the duration budget, so a
        // genuinely broken view does not spin forever. The count budget is set
        // high so only the duration trigger can fire here.
        setProperty(PropertyKey.CAIRO_LIVE_VIEW_FLUSH_RETRY_MAX, 1_000);
        setProperty(PropertyKey.CAIRO_LIVE_VIEW_FLUSH_RETRY_MAX_DURATION_MICROS, 500_000L);

        assertMemoryLeak(() -> {
            setCurrentMicros(0);
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                execute("INSERT INTO base (ts, x) VALUES ('2026-04-01T00:00:00.000001Z', 1)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(instance);
                Assert.assertFalse("LV must be valid after happy path", instance.isInvalid());

                final TableToken lvToken = instance.getLiveViewToken();
                Assert.assertTrue("must lock LV WAL writers", engine.lockWalWriters(lvToken));
                try {
                    // First failing cycle seeds flushRetryStartUs at the current
                    // clock (elapsedUs == 0), so it must not yet invalidate.
                    setCurrentMicros(100_000L);
                    execute("INSERT INTO base (ts, x) VALUES ('2026-04-01T00:00:00.000002Z', 2)");
                    drainWalQueue();
                    drainJob(job);
                    Assert.assertFalse("first transient failure must not yet invalidate", instance.isInvalid());
                    Assert.assertTrue("first transient failure records a retry", instance.getFlushRetryCount() >= 1);

                    // Advance past the duration cap and drive another cycle: the
                    // transient now exceeds the wall-clock budget and invalidates.
                    setCurrentMicros(1_000_000L);
                    execute("INSERT INTO base (ts, x) VALUES ('2026-04-01T00:00:00.000003Z', 3)");
                    drainWalQueue();
                    drainJob(job);
                    Assert.assertTrue("a never-resolving table must invalidate on the duration cap",
                            instance.isInvalid());
                    Assert.assertTrue(
                            "invalidation reason must mention flush retry [reason=" + instance.getInvalidationReason() + "]",
                            Chars.contains(instance.getInvalidationReason(), "flush retry budget")
                    );
                } finally {
                    engine.unlockWalWriters(lvToken);
                }
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testSameTimestampAdditiveAcrossCommitsMatchesRecompute() throws Exception {
        // Convergence guard for the additive O3 trigger's STRICT comparison.
        // drainBaseWal treats a commit as cross-commit O3 only when its min ts
        // is strictly below the frontier (txnMinTs < latestSeen, near
        // LiveViewRefreshJob line 1301), so a row that repeats an
        // already-materialized timestamp in a LATER commit is appended forward
        // rather than replayed. A review raised this as a possible divergence
        // for a peer-grouping RANGE frame, on the assumption that a full
        // recompute equalizes same-ts peers to one aggregate.
        //
        // It does not: QuestDB's RANGE ... AND CURRENT ROW emits a running value
        // per physical row (each row's frame is [ts - offset, its own ts], and
        // within one ts the running total advances in physical order) - it does
        // NOT retroactively equalize earlier same-ts peers. So the forward
        // append produces exactly what a from-scratch recompute produces, and
        // the strict trigger is correct: flipping it to <= would only force a
        // needless O3 replay on every same-microsecond append. This test pins
        // that equality (the LV fuzz oracle uses unique-increasing timestamps,
        // so it never exercises the same-ts path).
        assertMemoryLeak(() -> {
            final String frame =
                    "WINDOW w AS (PARTITION BY sym ORDER BY ts RANGE BETWEEN '2' HOUR PRECEDING AND CURRENT ROW)";
            final String recompute = "SELECT ts, sym, s FROM " +
                    "(SELECT ts, sym, sum(x) OVER w AS s FROM base " + frame + ") ORDER BY ts, s";
            execute("CREATE TABLE base (ts TIMESTAMP, sym SYMBOL, x INT) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, sym, sum(x) OVER w AS s FROM base " + frame);

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                setCurrentMicros(0L);
                // Commit 1: a single row at T for sym 'a'; latestSeenTs -> T.
                execute("INSERT INTO base (ts, sym, x) VALUES ('2026-08-01T00:00:00.000000Z', 'a', 3)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                // Commit 2 (separate cycle): a SAME-ts peer row at T. txnMinTs
                // (T) == latestSeen (T), so the strict trigger classifies it
                // in-order and it is appended forward, not replayed.
                setCurrentMicros(200_000L);
                execute("INSERT INTO base (ts, sym, x) VALUES ('2026-08-01T00:00:00.000000Z', 'a', 5)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                // Commit 3: a strictly-later row inside the 2h range, forwarding
                // the running total over both T peers plus itself.
                setCurrentMicros(400_000L);
                execute("INSERT INTO base (ts, sym, x) VALUES ('2026-08-01T01:00:00.000000Z', 'a', 2)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                // The from-scratch recompute is the oracle: 3.0, then 3+5=8.0 at
                // the second T peer, then 3+5+2=10.0 at T+1h.
                assertQuery(recompute)
                        .noLeakCheck().timestamp("ts").expectSize().returns("ts\tsym\ts\n" +
                                "2026-08-01T00:00:00.000000Z\ta\t3.0\n" +
                                "2026-08-01T00:00:00.000000Z\ta\t8.0\n" +
                                "2026-08-01T01:00:00.000000Z\ta\t10.0\n");
                // The live view's incrementally-appended output matches it byte
                // for byte - no stale same-ts peer.
                assertQuery("SELECT ts, sym, s FROM lv ORDER BY ts, s")
                        .noLeakCheck().timestamp("ts").expectSize().returns("ts\tsym\ts\n" +
                                "2026-08-01T00:00:00.000000Z\ta\t3.0\n" +
                                "2026-08-01T00:00:00.000000Z\ta\t8.0\n" +
                                "2026-08-01T01:00:00.000000Z\ta\t10.0\n");
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testSchemaChangeNarrowsToReferencedColumns() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, y INT, z INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");

            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertFalse("LV must start valid", instance.isInvalid());

            // Drop an unreferenced column — LV should stay ACTIVE.
            execute("ALTER TABLE base DROP COLUMN z");
            drainWalQueue();
            Assert.assertFalse(
                    "dropping an unreferenced column must not invalidate the LV",
                    instance.isInvalid()
            );

            // Drop a referenced column (x) — LV should flip to INVALID.
            execute("ALTER TABLE base DROP COLUMN x");
            drainWalQueue();
            Assert.assertTrue(
                    "dropping a referenced column must invalidate the LV",
                    instance.isInvalid()
            );

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testSchemaChangeColumnRenameInvalidatesOnlyReferencedColumn() throws Exception {
        // Counterpart to testSchemaChangeNarrowsToReferencedColumns (which covers
        // DROP COLUMN): a base RENAME COLUMN drops the old name, so a view that
        // references the renamed column flips to INVALID via dependsOnMissingOrRetypedColumn,
        // while a rename of a column the view never reads leaves it ACTIVE.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, y INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");

            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertFalse("LV must start valid", instance.isInvalid());

            // Rename an unreferenced column — LV stays ACTIVE.
            execute("ALTER TABLE base RENAME COLUMN y TO y2");
            drainWalQueue();
            Assert.assertFalse(
                    "renaming an unreferenced column must not invalidate the LV",
                    instance.isInvalid()
            );

            // Rename a referenced column (x) — LV flips to INVALID.
            execute("ALTER TABLE base RENAME COLUMN x TO x2");
            drainWalQueue();
            Assert.assertTrue(
                    "renaming a referenced column must invalidate the LV",
                    instance.isInvalid()
            );
            Assert.assertTrue(
                    "wrong invalidation reason [reason=" + instance.getInvalidationReason() + ']',
                    Chars.contains(instance.getInvalidationReason(), "rename column operation")
            );

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testDropLiveViewWritesDropSentinelDurably() throws Exception {
        // dropLiveView's first durable step writes _lv.drop and fsyncs it
        // before any in-memory or on-disk teardown, so a crash mid-drop leaves
        // an unambiguous signal for the startup loader to reap. We verify the
        // ordering at the FilesFacade layer: the sentinel openRW must run
        // before liveViewRegistry.removeView mutates the in-memory state,
        // and an fsync against the same fd must run before the file closes.
        final AtomicBoolean sentinelOpened = new AtomicBoolean(false);
        final AtomicBoolean sentinelFsynced = new AtomicBoolean(false);
        final long[] sentinelFd = {-1L};
        FilesFacade ff = new TestFilesFacadeImpl() {
            @Override
            public long openRW(LPSZ name, int opts) {
                final long fd = super.openRW(name, opts);
                if (fd > 0 && Utf8s.endsWithAscii(name, LiveViewDefinition.LIVE_VIEW_DROP_SENTINEL_FILE_NAME)) {
                    sentinelOpened.set(true);
                    sentinelFd[0] = fd;
                }
                return fd;
            }

            @Override
            public void fsync(long fd) {
                if (sentinelFd[0] == fd) {
                    sentinelFsynced.set(true);
                }
                super.fsync(fd);
            }
        };
        assertMemoryLeak(ff, () -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");
            execute("DROP LIVE VIEW lv");
            Assert.assertTrue("_lv.drop sentinel must be created during DROP",
                    sentinelOpened.get());
            Assert.assertTrue("_lv.drop sentinel must be fsynced during DROP",
                    sentinelFsynced.get());
        });
    }

    @Test
    public void testLoaderReapsLiveViewWhenDropSentinelExists() throws Exception {
        // Simulates a crash mid-DROP: the durable _lv.drop sentinel landed on
        // disk but the rest of the drop (sequencer mark + FS unlink) never
        // ran. On restart, buildViewGraphs must finish the drop instead of
        // re-registering a healthy-looking LV. Without the sentinel-reap
        // branch the loader would replay the LV as if DROP had never been
        // issued.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");

            TableToken token = engine.getLiveViewRegistry().getViewInstance("lv").getLiveViewToken();
            FilesFacade ff = engine.getConfiguration().getFilesFacade();
            try (Path path = new Path()) {
                path.of(engine.getConfiguration().getDbRoot())
                        .concat(token)
                        .concat(LiveViewDefinition.LIVE_VIEW_DROP_SENTINEL_FILE_NAME);
                Assert.assertTrue("sentinel touch must succeed", ff.touch(path.$()));
            }

            engine.getLiveViewRegistry().clear();
            engine.buildViewGraphs();

            Assert.assertNull(
                    "LV must not be re-registered when _lv.drop is present",
                    engine.getLiveViewRegistry().getViewInstance("lv")
            );
            Assert.assertNull(
                    "loader must mark the dropped token as dropped",
                    engine.getTableTokenIfExists("lv")
            );
        });
    }

    @Test
    public void testLoaderReapsOrphanLiveViewDirectory() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");

            // Simulate a CREATE crash that left the table directory and _lv.s
            // behind but never wrote the _lv commit marker. After restart, the
            // loader should reap the directory.
            TableToken token = engine.getLiveViewRegistry().getViewInstance("lv").getLiveViewToken();
            FilesFacade ff = engine.getConfiguration().getFilesFacade();
            try (Path path = new Path()) {
                path.of(engine.getConfiguration().getDbRoot())
                        .concat(token)
                        .concat(LiveViewDefinition.LIVE_VIEW_DEFINITION_FILE_NAME);
                Assert.assertTrue(ff.removeQuiet(path.$()));

                // Sanity: the LV directory is still on disk before the loader runs.
                path.of(engine.getConfiguration().getDbRoot()).concat(token);
                Assert.assertTrue("LV directory must still exist before reap", ff.exists(path.$()));
            }

            engine.getLiveViewRegistry().clear();
            engine.buildViewGraphs();

            Assert.assertNull(
                    "loader must not register an LV without a committed _lv",
                    engine.getLiveViewRegistry().getViewInstance("lv")
            );
            // The reap path goes through dropTableOrViewOrMatView, which marks
            // the WAL token dropped in the name registry. On-disk cleanup is
            // then handled by the standard WAL purge machinery; this assertion
            // captures the durable-side outcome (the LV name no longer resolves).
            Assert.assertNull(
                    "loader must mark the orphan token as dropped",
                    engine.getTableTokenIfExists("lv")
            );
        });
    }

    @Test
    public void testLoaderSurfacesHalfCreatedLiveViewAsDroppableStub() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");

            // Simulate a crash that left _lv on disk but not _lv.s. With the engine's
            // atomic write order (_lv.s first, _lv last) this can only occur via external
            // corruption. The loader must not fall back to a default subscribeFromSeqTxn
            // (which would re-replay the entire base table), and it must not silently skip
            // the view (which would strand it as an invisible, undroppable zombie). It
            // surfaces a non-refreshing, droppable state_unreadable stub instead.
            TableToken token = engine.getLiveViewRegistry().getViewInstance("lv").getLiveViewToken();
            FilesFacade ff = engine.getConfiguration().getFilesFacade();
            try (Path path = new Path()) {
                path.of(engine.getConfiguration().getDbRoot())
                        .concat(token)
                        .concat(LiveViewState.LIVE_VIEW_STATE_FILE_NAME);
                Assert.assertTrue(ff.removeQuiet(path.$()));
            }

            engine.getLiveViewRegistry().clear();
            engine.buildViewGraphs();

            LiveViewInstance stub = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull("missing _lv.s must surface a stub, not be silently skipped", stub);
            Assert.assertTrue(stub.isStub());
            Assert.assertEquals(LiveViewLifecycleState.STATE_UNREADABLE, stub.getLifecycleState());
            assertQuery("SELECT view_name, view_status FROM live_views() WHERE view_name = 'lv'")
                    .noLeakCheck().noRandomAccess()
                    .returns("view_name\tview_status\nlv\tstate_unreadable\n");

            // The stub is droppable via SQL - no undroppable zombie left behind.
            execute("DROP LIVE VIEW lv");
            assertQuery("SELECT count() FROM live_views() WHERE view_name = 'lv'")
                    .noLeakCheck().noRandomAccess().expectSize().returns("count\n0\n");
        });
    }

    @Test
    public void testSchemaChangeNarrowsAfterRestart() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, y INT, z INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");

            // Restart sweep before any refresh runs. The dependency set must come
            // back from _lv, otherwise the schema-change hook falls back to broad
            // invalidation and the LV flips INVALID on an unrelated DROP.
            engine.getLiveViewRegistry().clear();
            engine.buildViewGraphs();
            LiveViewInstance reloaded = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertFalse("LV must come back valid", reloaded.isInvalid());

            execute("ALTER TABLE base DROP COLUMN z");
            drainWalQueue();
            Assert.assertFalse(
                    "post-restart unreferenced-column DROP must not invalidate the LV",
                    reloaded.isInvalid()
            );

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testAnchorSpecPersistsAndRoundTrips() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, sym SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, sum(x) OVER w AS s FROM base " +
                    "WINDOW w AS (PARTITION BY sym ORDER BY ts ANCHOR EXPRESSION timestamp_floor('1d', ts))");

            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);
            Assert.assertNotNull("anchor spec must be captured at CREATE",
                    instance.getDefinition().getAnchorSpec());
            Assert.assertEquals("w", instance.getDefinition().getAnchorSpec().windowName);
            Assert.assertEquals(1, instance.getDefinition().getAnchorSpec().partitionColumnNames.size());
            Assert.assertEquals("sym", instance.getDefinition().getAnchorSpec().partitionColumnNames.get(0));

            // Drive a refresh so ensureAnchorFunction runs. The anchor function should
            // now be compiled and cached on the instance.
            execute("INSERT INTO base (ts, x, sym) VALUES ('2026-07-01T00:00:00.000000Z', 1, 'a')");
            drainWalQueue();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            drainWalQueue();
            Assert.assertNotNull("anchor function must be lazily compiled on first refresh",
                    instance.getAnchorFunction());

            // Simulate restart and verify anchor spec round-trips via _lv.
            engine.getLiveViewRegistry().clear();
            engine.buildViewGraphs();
            LiveViewInstance reloaded = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(reloaded);
            Assert.assertNotNull("anchor spec must round-trip via _lv",
                    reloaded.getDefinition().getAnchorSpec());
            Assert.assertEquals("w", reloaded.getDefinition().getAnchorSpec().windowName);
            Assert.assertEquals(1, reloaded.getDefinition().getAnchorSpec().partitionColumnNames.size());

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testAnchorResetsRunningSumAcrossDayBoundary() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, sym SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, sym, sum(x) OVER w AS s FROM base " +
                    "WINDOW w AS (PARTITION BY sym ORDER BY ts ANCHOR EXPRESSION timestamp_floor('1d', ts))");

            // Two days for sym='a': day 1 has values 10 and 20 (running sum: 10, 30);
            // day 2 has values 5 and 15 (running sum should restart from 0: 5, 20).
            // Without anchor reset, day 2's sums would continue from day 1 (35, 50).
            execute("INSERT INTO base (ts, x, sym) VALUES " +
                    "('2026-08-01T00:00:00.000000Z', 10, 'a'), " +
                    "('2026-08-01T01:00:00.000000Z', 20, 'a'), " +
                    "('2026-08-02T00:00:00.000000Z', 5, 'a'), " +
                    "('2026-08-02T01:00:00.000000Z', 15, 'a')");
            drainWalQueue();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            drainWalQueue();

            assertQuery("SELECT ts, sym, s FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns("ts\tsym\ts\n" +
                    "2026-08-01T00:00:00.000000Z\ta\t10.0\n" +
                    "2026-08-01T01:00:00.000000Z\ta\t30.0\n" +
                    "2026-08-02T00:00:00.000000Z\ta\t5.0\n" +
                    "2026-08-02T01:00:00.000000Z\ta\t20.0\n");

            execute("DROP LIVE VIEW lv");
        });
    }

