    @Test
    public void testInvalidationSurvivesRestart() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");

            // Drop the base table — this should invalidate the live view AND persist
            // the invalidation to _lv.s so restart sees the invalid state.
            execute("DROP TABLE base");
            drainWalQueue();

            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);
            Assert.assertTrue("live view must be invalid after base drop", instance.isInvalid());
            Assert.assertEquals(
                    "invalidation reason must record the trigger",
                    "base table drop",
                    instance.getInvalidationReason().toString()
            );

            // Simulate restart: clear registry, re-load from disk.
            engine.getLiveViewRegistry().clear();
            engine.buildViewGraphs();

            LiveViewInstance reloaded = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(reloaded);
            Assert.assertTrue(
                    "invalidation must round-trip via _lv.s",
                    reloaded.isInvalid()
            );
            Assert.assertEquals(
                    "invalidation reason must round-trip via _lv.s",
                    "base table drop",
                    reloaded.getInvalidationReason().toString()
            );

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testBaseTableRenameInvalidatesLiveView() throws Exception {
        // Renaming the base table is allowed, but it invalidates every dependent
        // LV as a synchronous side effect (CairoEngine.rename ->
        // invalidateLiveViewsForBaseTable, reason "base table rename") - the same
        // contract a base DROP takes (testInvalidationSurvivesRestart). The LV
        // stays queryable from its own on-disk tier (it materializes to its own
        // table, independent of the base name) and the invalidation persists
        // across a restart. Contrast LiveViewTest.testRejectRename, which covers
        // renaming the LV itself (rejected outright, never reaching this path).
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");
            execute("INSERT INTO base (ts, x) VALUES " +
                    "('2026-05-01T00:00:00.000000Z', 1), " +
                    "('2026-05-02T00:00:00.000000Z', 2)");
            drainWalQueue();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            drainWalQueue();

            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);
            Assert.assertFalse("LV must start valid", instance.isInvalid());
            assertQuery("SELECT ts, x, rn FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns("ts\tx\trn\n" +
                    "2026-05-01T00:00:00.000000Z\t1\t1\n" +
                    "2026-05-02T00:00:00.000000Z\t2\t2\n");

            // Rename the base. The LV flips INVALID immediately.
            execute("RENAME TABLE base TO base2");
            drainWalQueue();

            Assert.assertTrue("LV must be invalid after base rename", instance.isInvalid());
            Assert.assertEquals(
                    "invalidation reason must record the trigger",
                    "base table rename",
                    instance.getInvalidationReason().toString()
            );
            assertQuery("SELECT view_status, invalidation_reason FROM live_views() WHERE view_name = 'lv'").noLeakCheck().noRandomAccess().returns("view_status\tinvalidation_reason\n" +
                    "invalid\tbase table rename\n");

            // The invalid view stays queryable from its own on-disk tier - the
            // base rename does not touch the LV's materialized data.
            assertQuery("SELECT ts, x, rn FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns("ts\tx\trn\n" +
                    "2026-05-01T00:00:00.000000Z\t1\t1\n" +
                    "2026-05-02T00:00:00.000000Z\t2\t2\n");

            // The invalidation round-trips through _lv.s across a restart.
            engine.getLiveViewRegistry().clear();
            engine.buildViewGraphs();
            LiveViewInstance reloaded = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(reloaded);
            Assert.assertTrue(
                    "invalidation must round-trip via _lv.s",
                    reloaded.isInvalid()
            );
            Assert.assertEquals(
                    "invalidation reason must round-trip via _lv.s",
                    "base table rename",
                    reloaded.getInvalidationReason().toString()
            );

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testLiveViewsCatalogueColumnOrderMatchesRfc() throws Exception {
        // Columns appear in the documented order so clients binding by
        // ordinal see a stable shape. The documented columns come first, the
        // three o3_*_rows columns trail as replay observability, and the
        // checkpoint_* group closes the set in its four blocks: the
        // generation's shape, collection, cost, and localized repair. The last
        // block ends on checkpoint_repair_plan, which describes the repair a
        // view's SQL admits rather than one repair's progress.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");
            try {
                assertQuery("SELECT * FROM live_views() WHERE 1 = 0").noLeakCheck().returns("view_name\tview_table_dir_name\tbase_table_name\tview_sql\tview_status\t"
                        + "invalidation_reason\tflush_every_interval\tflush_every_interval_unit\t"
                        + "in_memory_interval\tin_memory_interval_unit\tin_mem_bytes\tin_mem_rows\t"
                        + "o3_rejected_count\tbelow_lower_bound_count\tlag_seqtxn\tlag_micros\t"
                        + "last_processed_seqtxn\tapplied_watermark\tlv_consumed_seqtxn\t"
                        + "view_lower_bound_timestamp\twriter_stall_micros\tseed_target_seqtxn\t"
                        + "o3_resume_replay_rows\to3_boundary_replay_rows\to3_replay_scan_rows\t"
                        + "checkpoint_timeline_generation\tcheckpoint_timeline_entries\t"
                        + "checkpoint_timeline_normalized_base_seqtxn\tcheckpoint_timeline_logical_bytes\t"
                        + "checkpoint_timeline_physical_bytes\tcheckpoint_timeline_shared_bytes\t"
                        + "checkpoint_timeline_sharing_ratio\tcheckpoint_timeline_row_position_delta_bytes\t"
                        + "checkpoint_data_segment_count\tcheckpoint_obsolete_segment_bytes\t"
                        + "checkpoint_oldest_pinned_generation\tcheckpoint_gc_lag_generations\t"
                        + "checkpoint_last_write_micros\tcheckpoint_last_restore_micros\t"
                        + "checkpoint_last_write_new_bytes\tcheckpoint_last_lookup_depth\t"
                        + "checkpoint_repair_in_progress\tcheckpoint_repair_correction_timestamp\t"
                        + "checkpoint_repair_low_timestamp\tcheckpoint_repair_high_timestamp\t"
                        + "checkpoint_repair_roots_versioned\tcheckpoint_repair_new_bytes\t"
                        + "checkpoint_repair_resumes\tcheckpoint_repair_failures\t"
                        + "checkpoint_repair_plan\n");
            } finally {
                execute("DROP LIVE VIEW lv");
            }
        });
    }

