    @Test
    public void testO3LateRowBelowLowerBoundIsRejectedAndCounted() throws Exception {
        // A late O3 row whose timestamp falls below viewLowerBoundTimestamp is
        // rejected: it never reaches the on-disk tier, and the rejection is
        // recorded in live_views().o3_rejected_count.
        assertMemoryLeak(() -> {
            // Pin the clock so the non-SEED view's lower bound is a known
            // wall-clock moment (2023-11-14T22:13:20Z).
            setCurrentMicros(1_700_000_000_000_000L);
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");

            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);

            // A row above the lower bound advances latestSeenTs through a refresh.
            execute("INSERT INTO base (ts, x) VALUES ('2023-11-15T00:00:00.000000Z', 1)");
            drainWalQueue();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            drainWalQueue();
            assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n1\n");
            Assert.assertEquals("no rejections yet", 0L, instance.getO3RejectedCount());

            // A late row below the lower bound: it is O3 (ts < latestSeenTs) and
            // sits entirely below viewLowerBoundTimestamp, so the refresh rejects it.
            execute("INSERT INTO base (ts, x) VALUES ('2023-11-14T00:00:00.000000Z', 2)");
            drainWalQueue();
            // FLUSH EVERY 1s would otherwise rate-limit the back-to-back cycle.
            instance.setLastFlushTimeUs(Numbers.LONG_NULL);
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            drainWalQueue();

            // The rejected row never reached the tier; the counter recorded it.
            assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n1\n");
            Assert.assertEquals(
                    "one O3 row rejected below the lower bound",
                    1L,
                    instance.getO3RejectedCount()
            );
            assertQuery("SELECT view_name, o3_rejected_count FROM live_views() WHERE view_name = 'lv'").noLeakCheck().noRandomAccess().returns("view_name\to3_rejected_count\n" +
                    "lv\t1\n");

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testNonSeedForwardAndO3ReplayAgreeOnSubFloorRows() throws Exception {
        // A non-SEED view's lower bound is the CREATE wall-clock moment. The
        // O3 head-miss replay seeds its scan at that floor and drops every row
        // below it; the forward-append path must drop sub-floor rows as well.
        // Otherwise a back-dated row would be kept when it arrives in order
        // (forward) but dropped when it arrives out of order (replay) - the
        // view's contents would depend on the arrival path, not the data. This
        // drives both paths over identical data straddling the floor and asserts
        // they produce the same rows, with the sub-floor rows dropped either way.
        //
        // The complementary "O3 row below the floor is rejected and counted"
        // case is testO3LateRowBelowLowerBoundIsRejectedAndCounted; this is the
        // forward-path twin of it.
        final long floorMicros = MicrosTimestampDriver.floor("2026-04-01T00:00:05.000000Z");
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base_fwd (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE TABLE base_o3 (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");

            // Pin the clock at the floor so each non-SEED view's lower bound
            // is 2026-04-01T00:00:05.
            setCurrentMicros(floorMicros);
            execute("CREATE LIVE VIEW lv_fwd FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base_fwd");
            execute("CREATE LIVE VIEW lv_o3 FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base_o3");

            LiveViewInstance fwd = engine.getLiveViewRegistry().getViewInstance("lv_fwd");
            LiveViewInstance o3 = engine.getLiveViewRegistry().getViewInstance("lv_o3");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                // Forward path: a single in-order commit straddling the floor.
                // The two sub-floor rows (01, 02) precede the two above-floor
                // rows (06, 07) in ts order, so the commit is not out of order
                // and goes through the forward-append path.
                execute("INSERT INTO base_fwd (ts, x) VALUES " +
                        "('2026-04-01T00:00:01.000000Z', 1), " +
                        "('2026-04-01T00:00:02.000000Z', 2), " +
                        "('2026-04-01T00:00:06.000000Z', 6), " +
                        "('2026-04-01T00:00:07.000000Z', 7)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                // O3 path, step 1: the above-floor rows arrive first and are
                // forward-appended, advancing the watermark to 00:00:07.
                execute("INSERT INTO base_o3 (ts, x) VALUES " +
                        "('2026-04-01T00:00:06.000000Z', 6), " +
                        "('2026-04-01T00:00:07.000000Z', 7)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                // O3 path, step 2: the sub-floor rows arrive back-dated as a
                // second commit whose min ts is below the watermark, triggering
                // an O3 head-miss replay. The replay re-scans from the floor and
                // never sees the sub-floor rows. Clear the per-view flush gate so
                // the back-to-back cycle is not rate-limited by FLUSH EVERY.
                o3.setLastFlushTimeUs(Numbers.LONG_NULL);
                execute("INSERT INTO base_o3 (ts, x) VALUES " +
                        "('2026-04-01T00:00:01.000000Z', 1), " +
                        "('2026-04-01T00:00:02.000000Z', 2)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();
            }

            // Both paths drop the sub-floor rows and keep only the above-floor
            // rows, with identical row numbers.
            final String expected = "ts\tx\trn\n" +
                    "2026-04-01T00:00:06.000000Z\t6\t1\n" +
                    "2026-04-01T00:00:07.000000Z\t7\t2\n";
            assertQuery("SELECT ts, x, rn FROM lv_fwd ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns(expected);
            assertQuery("SELECT ts, x, rn FROM lv_o3 ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns(expected);

            // The two counters split the sub-floor drops by arrival path and
            // never overlap. The forward path drops its two in-order sub-floor
            // rows (pre-CREATE data excluded by the floor, not out-of-order
            // arrivals): they land in below_lower_bound_count, not
            // o3_rejected_count. The replay path rejects the back-dated commit
            // below the floor: it lands in o3_rejected_count, not
            // below_lower_bound_count.
            Assert.assertEquals("in-order sub-floor rows are not O3 rejections", 0L, fwd.getO3RejectedCount());
            Assert.assertEquals("in-order sub-floor rows are counted below the lower bound", 2L, fwd.getBelowLowerBoundCount());
            Assert.assertEquals("the back-dated sub-floor commit is an O3 rejection", 2L, o3.getO3RejectedCount());
            Assert.assertEquals("the O3 path does not touch below_lower_bound_count", 0L, o3.getBelowLowerBoundCount());
            assertQuery("SELECT view_name, o3_rejected_count, below_lower_bound_count FROM live_views() ORDER BY view_name")
                    .noLeakCheck().returns("view_name\to3_rejected_count\tbelow_lower_bound_count\n" +
                            "lv_fwd\t0\t2\n" +
                            "lv_o3\t2\t0\n");

            execute("DROP LIVE VIEW lv_fwd");
            execute("DROP LIVE VIEW lv_o3");
        });
    }

    @Test
    public void testInOrderRowsBelowLowerBoundAreCounted() throws Exception {
        // A fresh non-SEED view whose entire first commit is back-dated below
        // the CREATE wall-clock floor drops every row on the in-order forward-
        // append path. That drop used to be invisible - active view, lag 0,
        // o3_rejected_count 0, no log - so a 100%-loss of back-dated ingestion
        // read as a healthy-but-empty view. below_lower_bound_count now records
        // it so the drop is diagnosable from the catalogue.
        assertMemoryLeak(() -> {
            // Pin the floor at a known wall-clock moment (2023-11-14T22:13:20Z).
            // Every inserted row sits strictly below it and strictly ascending,
            // so the commit is in order (not O3) and takes the forward-append
            // path rather than the O3 replay.
            setCurrentMicros(1_700_000_000_000_000L);
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");

            LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(instance);
            Assert.assertEquals("no drops yet", 0L, instance.getBelowLowerBoundCount());

            execute("INSERT INTO base (ts, x) VALUES " +
                    "('2023-11-14T00:00:00.000000Z', 1), " +
                    "('2023-11-14T00:00:01.000000Z', 2), " +
                    "('2023-11-14T00:00:02.000000Z', 3)");
            drainWalQueue();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            drainWalQueue();

            // Every row dropped: the view is empty but the counter names it, and
            // none of the drops are attributed to the O3 path.
            assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n0\n");
            Assert.assertEquals("all three in-order sub-floor rows counted", 3L, instance.getBelowLowerBoundCount());
            Assert.assertEquals("in-order drops are not O3 rejections", 0L, instance.getO3RejectedCount());
            Assert.assertTrue("the advisory log latch is set after the first drop", instance.hasWarnedBelowLowerBoundDrop());
            assertQuery("SELECT view_name, view_status, o3_rejected_count, below_lower_bound_count FROM live_views() WHERE view_name = 'lv'")
                    .noLeakCheck().noRandomAccess().returns("view_name\tview_status\to3_rejected_count\tbelow_lower_bound_count\n" +
                            "lv\tactive\t0\t3\n");

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testUnsupportedDefinitionVersionSurfacesAndDrops() throws Exception {
        // An _lv whose CORE format version is newer than this build supports must
        // not vanish silently: the load path surfaces the view in live_views()
        // with view_status='version_unsupported' and other columns NULL, and DROP
        // LIVE VIEW still removes it best-effort.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");
            TableToken token = engine.getLiveViewRegistry().getViewInstance("lv").getLiveViewToken();

            overwriteLiveViewFileWithBumpedFormatVersion(
                    token,
                    LiveViewDefinition.LIVE_VIEW_DEFINITION_FILE_NAME,
                    LiveViewDefinition.LIVE_VIEW_DEFINITION_CORE_MSG_TYPE
            );
            // Simulate restart: drop the in-memory registry and rebuild from disk.
            engine.getLiveViewRegistry().clear();
            engine.buildViewGraphs();

            LiveViewInstance stub = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull("version-unsupported view must still be registered", stub);
            Assert.assertTrue("stub must be a load-failure stub", stub.isStub());
            Assert.assertEquals("stub must report version-unsupported",
                    LiveViewLifecycleState.VERSION_UNSUPPORTED, stub.getLifecycleState());

            // view_name and view_status surface; definition/state columns are NULL
            // (string columns render empty, long columns render "null").
            assertQuery("SELECT view_name, view_status, view_sql, base_table_name, lv_consumed_seqtxn, " +
                    "view_lower_bound_timestamp FROM live_views() WHERE view_name = 'lv'").noLeakCheck().noRandomAccess().returns("view_name\tview_status\tview_sql\tbase_table_name\tlv_consumed_seqtxn\tview_lower_bound_timestamp\n" +
                    "lv\tversion_unsupported\t\t\tnull\t\n");

            // DROP works on the stub (best-effort recovery path).
            execute("DROP LIVE VIEW lv");
            assertQuery("SELECT count() FROM live_views() WHERE view_name = 'lv'").noLeakCheck().noRandomAccess().expectSize().returns("count\n0\n");
        });
    }

    @Test
    public void testUnsupportedStateVersionSurfaces() throws Exception {
        // The version gate also covers _lv.s: a newer state-file format surfaces
        // the view as version_unsupported even when _lv reads cleanly.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 1s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");
            TableToken token = engine.getLiveViewRegistry().getViewInstance("lv").getLiveViewToken();

            overwriteLiveViewFileWithBumpedFormatVersion(
                    token,
                    LiveViewState.LIVE_VIEW_STATE_FILE_NAME,
                    LiveViewState.LIVE_VIEW_STATE_CORE_MSG_TYPE
            );
            engine.getLiveViewRegistry().clear();
            engine.buildViewGraphs();

            LiveViewInstance stub = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(stub);
            Assert.assertEquals(LiveViewLifecycleState.VERSION_UNSUPPORTED, stub.getLifecycleState());
            assertQuery("SELECT view_name, view_status FROM live_views() WHERE view_name = 'lv'").noLeakCheck().noRandomAccess().returns("view_name\tview_status\n" +
                    "lv\tversion_unsupported\n");

            execute("DROP LIVE VIEW lv");
        });
    }

    private void overwriteLiveViewFileWithBumpedFormatVersion(TableToken token, String fileName, int coreBlockType) {
        try (
                BlockFileWriter writer = new BlockFileWriter(
                        engine.getConfiguration().getFilesFacade(),
                        engine.getConfiguration().getCommitMode());
                Path path = new Path()
        ) {
            path.of(engine.getConfiguration().getDbRoot()).concat(token).concat(fileName);
            writer.of(path.$());
            AppendableBlock block = writer.append();
            // The format version is the CORE block's first field, so a value above
            // the reader's supported version is rejected before the rest is parsed.
            block.putInt(Integer.MAX_VALUE);
            block.commit(coreBlockType);
            writer.commit();
        }
    }

    @Test
    public void testLiveViewsCatalogueExposesOperationalColumns() throws Exception {
        // Pin the clock so lag_micros is deterministic across runs.
        assertMemoryLeak(() -> {
            setCurrentMicros(1_000_000L);
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");
            execute("INSERT INTO base (ts, x) VALUES ('2026-04-01T00:00:00.000001Z', 1)");
            drainWalQueue();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            drainWalQueue();

            // Advance the clock so lag_micros reflects time since the last flush.
            setCurrentMicros(3_000_000L);

            // view_table_dir_name must match the live view's actual directory; once mangling
            // is enabled in tests it diverges from the view name, so resolve via the engine.
            TableToken token = engine.verifyTableName("lv");
            String expectedDir = token.getDirName();
            // writer_stall_micros is 0 here: this scenario never stalls the writer.
            // lag_micros = 3_000_000 - lastFlushTimeUs. lastFlushTimeUs was set to 1_000_000
            // (the clock at refresh), so lag_micros = 2_000_000.
            assertQuery("SELECT view_name, view_table_dir_name, lag_micros, writer_stall_micros FROM live_views()").noLeakCheck().noRandomAccess().returns("view_name\tview_table_dir_name\tlag_micros\twriter_stall_micros\n" +
                    "lv\t" + expectedDir + "\t2000000\t0\n");

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testNthValueDoubleOverUnboundedPartitionRowsSnapshotRoundTrip() throws Exception {
        // nth_value() Step 1 — DOUBLE variant. State per partition is
        // [value: DOUBLE, count: LONG, tombstone: BYTE]. Picks N=2 so the second
        // row per partition locks the value; rows beyond that propagate the
        // locked value.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x DOUBLE, sym SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, sym, nth_value(x, 2) OVER w AS nv FROM base " +
                    "WINDOW w AS (PARTITION BY sym ORDER BY ts ANCHOR EXPRESSION timestamp_floor('1d', ts))");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                setCurrentMicros(0L);
                execute("INSERT INTO base (ts, x, sym) VALUES " +
                        "('2026-08-01T00:00:00.000000Z', 5.0, 'a'), " +
                        "('2026-08-01T01:00:00.000000Z', 50.0, 'a'), " +
                        "('2026-08-01T02:00:00.000000Z', 20.0, 'a'), " +
                        "('2026-08-01T00:00:00.000000Z', 7.0, 'b'), " +
                        "('2026-08-01T01:00:00.000000Z', 11.0, 'b')");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                LiveViewInstance lv = engine.getLiveViewRegistry().getViewInstance("lv");
                WindowFunction nvFunc = lv.getAnchorWindow().getFunctions().getQuick(0);
                Assert.assertTrue(nvFunc.supportsCheckpointState());
                Map fnMap = nvFunc.getPartitionMap();
                Assert.assertEquals(2L, fnMap.size());

                try (MemoryCARW sink = Vm.getCARWInstance(4096L, Integer.MAX_VALUE, MemoryTag.NATIVE_DEFAULT)) {
                    LiveViewFunctionSnapshot.write(sink, nvFunc);
                    nvFunc.toTop();
                    Assert.assertEquals(0L, fnMap.size());
                    LiveViewFunctionSnapshot.restore(sink, 0L, sink.getAppendOffset(), nvFunc);
                    Assert.assertEquals(2L, fnMap.size());

                    // 'a' nth_value(x, 2) is 50.0, 'b' is 11.0. Sum 61.0.
                    MapRecordCursor mc = fnMap.getCursor();
                    MapRecord rec = fnMap.getRecord();
                    double total = 0;
                    while (mc.hasNext()) {
                        total += rec.getValue().getDouble(0);
                    }
                    Assert.assertEquals(61.0, total, 0.0);
                }
            }

            execute("DROP LIVE VIEW lv");
        });
    }

