    @Test
    public void testRestartRestoresFirstLastValueFromHeadCheckpoint() throws Exception {
        // first_value() and last_value() over (PARTITION BY ...
        // ROWS N PRECEDING ...) are now snapshot-capable, in both the parent
        // ("respect nulls", default) and IGNORE NULLS subclass variants. The
        // four migrated classes have distinct slot layouts:
        //   - FirstValue parent:   3 LONG slots
        //   - FirstNotNull:        4 LONG slots
        //   - LastValue parent:    2 LONG slots (3rd reserved)
        //   - LastNotNull:         1 TYPED + 2 LONG slots
        // The LV below routes through all four code paths; w1 fires when
        // rowsHi == 0 (frame includes current row) for first_value variants
        // and the IGNORE NULLS last_value path; w2 fires when rowsHi < 0 for
        // the respect-nulls last_value parent (rowsHi == 0 would route to
        // LastValueIncludeCurrent, which has no snapshot support).
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, sym SYMBOL, x DOUBLE) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, sym, " +
                    "  first_value(x) OVER w1 AS fv, " +
                    "  first_value(x) IGNORE NULLS OVER w1 AS fvn, " +
                    "  last_value(x) IGNORE NULLS OVER w1 AS lvn, " +
                    "  last_value(x) OVER w2 AS lv " +
                    "FROM base " +
                    "WINDOW " +
                    "  w1 AS (PARTITION BY sym ORDER BY ts ROWS 2 PRECEDING), " +
                    "  w2 AS (PARTITION BY sym ORDER BY ts ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING)");

            final long preHeadLvSeqTxn;
            final long preLastProcessed;
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                setCurrentMicros(0L);
                execute("INSERT INTO base (ts, sym, x) VALUES " +
                        "('2026-09-01T00:00:00.000000Z', 'a', 1.0), " +
                        "('2026-09-01T01:00:00.000000Z', 'a', 2.0), " +
                        "('2026-09-01T02:00:00.000000Z', 'a', 3.0), " +
                        "('2026-09-01T00:00:00.000000Z', 'b', 10.0), " +
                        "('2026-09-01T01:00:00.000000Z', 'b', 20.0)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
                preHeadLvSeqTxn = instance.getHeadCheckpointLvSeqTxn();
                preLastProcessed = instance.getLastProcessedSeqTxn();
                Assert.assertNotEquals(
                        "head checkpoint must be written for an LV with first_value/last_value bounded ROWS now that 2b.3d/e makes them snapshot-capable",
                        Numbers.LONG_NULL,
                        preHeadLvSeqTxn
                );
                Assert.assertTrue(
                        "snapshot capability cached after first successful flush",
                        instance.isSnapshotCapability()
                );
            }

            engine.getLiveViewRegistry().clear();
            engine.buildViewGraphs();

            LiveViewInstance reloaded = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(reloaded);
            Assert.assertEquals(preHeadLvSeqTxn, reloaded.getHeadCheckpointLvSeqTxn());

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                drainJob(job);
            }
            Assert.assertTrue(reloaded.isCheckpointRestoreAttempted());
            Assert.assertEquals(preLastProcessed, reloaded.getLastProcessedSeqTxn());

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testRestartRestoresLagFromHeadCheckpoint() throws Exception {
        // lag() is now snapshot-capable. End-to-end check that a
        // refresh cycle writes a head checkpoint, a simulated restart re-discovers
        // it, and the first post-restart refresh tick rehydrates the lag
        // function's partition map. Mirrors testRestartRestoresRankFromHead
        // Checkpoint for the lag ring-blob path.
        //
        // The post-restart-then-new-commit scenario is intentionally NOT
        // covered: getIncrementalCursor's pre-existing toTop chain wipes the
        // anchor map and function maps at the start of each refresh cycle,
        // so a new commit immediately after restore would discard the
        // rehydrated state. That cross-cycle wipe is tracked under 2a.8's
        // "known limitations".
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, sym SYMBOL, x DOUBLE) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, sym, lag(x, 1) OVER w AS prev FROM base " +
                    "WINDOW w AS (PARTITION BY sym ORDER BY ts ANCHOR EXPRESSION timestamp_floor('1d', ts))");

            final long preHeadLvSeqTxn;
            final long preLastProcessed;
            final long preFunctionMapSize;
            try (MemoryCARW pre = Vm.getCARWInstance(64 * 1024L, Integer.MAX_VALUE, MemoryTag.NATIVE_DEFAULT);
                 MemoryCARW post = Vm.getCARWInstance(64 * 1024L, Integer.MAX_VALUE, MemoryTag.NATIVE_DEFAULT)) {
                try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                    setCurrentMicros(0L);
                    execute("INSERT INTO base (ts, sym, x) VALUES " +
                            "('2026-09-01T00:00:00.000000Z', 'a', 1.0), " +
                            "('2026-09-01T01:00:00.000000Z', 'a', 2.0), " +
                            "('2026-09-01T00:00:00.000000Z', 'b', 3.0)");
                    drainWalQueue();
                    drainJob(job);
                    drainWalQueue();

                    LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
                    preHeadLvSeqTxn = instance.getHeadCheckpointLvSeqTxn();
                    preLastProcessed = instance.getLastProcessedSeqTxn();
                    WindowFunction lagFn = instance.getAnchorWindow().getFunctions().getQuick(0);
                    preFunctionMapSize = lagFn.getPartitionMap().size();
                    Assert.assertNotEquals(
                            "head checkpoint must be written for an LV with lag() now that 2b.2a makes it snapshot-capable",
                            Numbers.LONG_NULL,
                            preHeadLvSeqTxn
                    );
                    Assert.assertEquals("two partition keys seeded pre-restart", 2L, preFunctionMapSize);
                    // Capture the pre-restart ring so the restore below has something to be compared
                    // against, rather than just counted.
                    LiveViewFunctionSnapshot.write(pre, lagFn);
                }

                engine.getLiveViewRegistry().clear();
                engine.buildViewGraphs();

                LiveViewInstance reloaded = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(reloaded);
                Assert.assertEquals(preHeadLvSeqTxn, reloaded.getHeadCheckpointLvSeqTxn());

                try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                    drainJob(job);
                }
                // isCheckpointRestoreAttempted() is also satisfied by a restore that FAILED and fell
                // back to a head-miss replay recompute, which would leave everything below passing for
                // the wrong reason. Only "succeeded" proves the state came off the head checkpoint.
                Assert.assertTrue(
                        "head checkpoint restore must rehydrate lag's state, not fall back to a head-miss replay",
                        reloaded.isCheckpointRestoreSucceeded()
                );
                Assert.assertEquals(preLastProcessed, reloaded.getLastProcessedSeqTxn());

                WindowFunction reloadedLagFn = reloaded.getAnchorWindow().getFunctions().getQuick(0);
                Assert.assertEquals(
                        "lag's partition map rehydrates to its pre-restart partition count",
                        preFunctionMapSize,
                        reloadedLagFn.getPartitionMap().size()
                );

                // The partition count on its own is satisfied by a restore that rehydrated the right
                // number of partitions holding garbage rings - nothing reads a lag value back out.
                // Re-serialise the restored function and compare it byte for byte with the pre-restart
                // snapshot: that pins firstIdx, count and every ring slot. A post-restart INSERT would
                // be the more direct oracle, but the cross-cycle toTop wipe documented above makes
                // that scenario meaningless for an ANCHOR window.
                LiveViewFunctionSnapshot.write(post, reloadedLagFn);
                final long preBytes = pre.getAppendOffset();
                Assert.assertTrue("pre-restart snapshot wrote some bytes", preBytes > 0);
                Assert.assertEquals(
                        "restored lag state must re-serialise to the pre-restart length",
                        preBytes,
                        post.getAppendOffset()
                );
                for (long i = 0; i < preBytes; i++) {
                    Assert.assertEquals("restored lag state differs at byte " + i, pre.getByte(i), post.getByte(i));
                }
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testLatestSeenTsAdvancesAcrossRows() throws Exception {
        // The anchor-dispatch cursor stamps the per-LV latestSeenTs
        // watermark on every base row consumed by the refresh worker. This is
        // the input the O3 detection path will read in a later commit; for now
        // we just verify the cursor feeds the setter with the max ts in the
        // batch.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, sym SYMBOL, x DOUBLE) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, sym, sum(x) OVER w AS s FROM base " +
                    "WINDOW w AS (PARTITION BY sym ORDER BY ts ANCHOR EXPRESSION timestamp_floor('1d', ts))");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                LiveViewInstance lv = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(lv);
                Assert.assertEquals(
                        "latestSeenTs starts at LONG_NULL on a fresh LV",
                        Numbers.LONG_NULL,
                        lv.getLatestSeenTs()
                );

                setCurrentMicros(0L);
                execute("INSERT INTO base (ts, sym, x) VALUES " +
                        "('2026-10-01T00:00:00.000000Z', 'a', 1.0), " +
                        "('2026-10-01T00:00:05.000000Z', 'b', 3.0), " +
                        "('2026-10-01T00:00:10.000000Z', 'a', 2.0)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                Assert.assertEquals(
                        "latestSeenTs equals max(ts) of the batch consumed by the refresh worker",
                        MicrosFormatUtils.parseUTCTimestamp("2026-10-01T00:00:10.000000Z"),
                        lv.getLatestSeenTs()
                );

                // A subsequent in-order batch advances the watermark; advance
                // microtime past the FLUSH EVERY gate so the second refresh
                // actually fires rather than no-oping on the rate limiter.
                setCurrentMicros(200_000L);
                execute("INSERT INTO base (ts, sym, x) VALUES " +
                        "('2026-10-01T00:01:00.000000Z', 'a', 4.0)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();
                Assert.assertEquals(
                        "latestSeenTs advances on the next in-order batch",
                        MicrosFormatUtils.parseUTCTimestamp("2026-10-01T00:01:00.000000Z"),
                        lv.getLatestSeenTs()
                );

                // The setter's monotonic clamp is asserted directly so the
                // contract is pinned independently of the cursor wiring.
                long beforeClampAttempt = lv.getLatestSeenTs();
                lv.setLatestSeenTs(beforeClampAttempt - 1_000_000L);
                Assert.assertEquals(
                        "setLatestSeenTs is monotonic; a lower value is ignored",
                        beforeClampAttempt,
                        lv.getLatestSeenTs()
                );

                // forceSetLatestSeenTs bypasses the monotonic clamp; the
                // refresh worker uses it on O3 detect + rollback to revert
                // any in-cycle bumps the discarded rows applied.
                long rollbackTarget = beforeClampAttempt - 10_000_000L;
                lv.forceSetLatestSeenTs(rollbackTarget);
                Assert.assertEquals(
                        "forceSetLatestSeenTs writes the value verbatim",
                        rollbackTarget,
                        lv.getLatestSeenTs()
                );
                lv.forceSetLatestSeenTs(beforeClampAttempt);
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testO3InvalidatesHeadCheckpoint() throws Exception {
        // An O3 base commit (min ts strictly below the LV's
        // latestSeenTs watermark) cannot be replayed in WAL order without
        // corrupting per-partition window state, so the refresh worker
        // rolls back the in-flight WAL writer, branches to o3Replay, and
        // re-feeds base data in ts order from a TableReader. The prior
        // boundary is retired by the replay path; a fresh one reflecting
        // the post-replay state is sealed before the cycle returns so a
        // subsequent O3 has a near boundary to resume from.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, sym SYMBOL, x DOUBLE) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, sym, sum(x) OVER w AS s FROM base " +
                    "WINDOW w AS (PARTITION BY sym ORDER BY ts ANCHOR EXPRESSION timestamp_floor('1d', ts))");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                setCurrentMicros(0L);
                execute("INSERT INTO base (ts, sym, x) VALUES " +
                        "('2026-11-01T00:00:10.000000Z', 'a', 1.0), " +
                        "('2026-11-01T00:00:20.000000Z', 'b', 3.0)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                LiveViewInstance lv = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(lv);
                final long preO3HeadLvSeqTxn = lv.getHeadCheckpointLvSeqTxn();
                Assert.assertNotEquals(
                        "a boundary was sealed before the O3 commit",
                        Numbers.LONG_NULL,
                        preO3HeadLvSeqTxn
                );
                Assert.assertEquals(
                        "latestSeenTs equals max(ts) of the first batch",
                        MicrosFormatUtils.parseUTCTimestamp("2026-11-01T00:00:20.000000Z"),
                        lv.getLatestSeenTs()
                );

                {
                    // Insert an out-of-order row: ts (00:00:05) is strictly
                    // below the watermark (00:00:20). Advance microtime past
                    // the FLUSH EVERY gate so the refresh worker actually
                    // ticks rather than no-oping on the rate limiter.
                    setCurrentMicros(200_000L);
                    execute("INSERT INTO base (ts, sym, x) VALUES " +
                            "('2026-11-01T00:00:05.000000Z', 'a', 2.0)");
                    drainWalQueue();
                    drainJob(job);
                    drainWalQueue();

                    final long postO3HeadLvSeqTxn = lv.getHeadCheckpointLvSeqTxn();
                    Assert.assertNotEquals(
                            "head metadata refreshed post O3 replay",
                            Numbers.LONG_NULL,
                            postO3HeadLvSeqTxn
                    );
                    Assert.assertNotEquals(
                            "post-replay head lvSeqTxn differs from the pre-O3 head",
                            preO3HeadLvSeqTxn,
                            postO3HeadLvSeqTxn
                    );
                    Assert.assertNotEquals(
                            "head checkpoint max ts populated post O3 replay",
                            Numbers.LONG_NULL,
                            lv.getHeadCheckpointMaxTs()
                    );
                    Assert.assertNotEquals(
                            "head checkpoint state bytes populated post O3 replay",
                            0L,
                            lv.getHeadCheckpointStateBytes()
                    );
                }
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testO3HeadMissReplaysFromLowerBound() throws Exception {
        // An O3 row with ts strictly below the head's maxTimestamp
        // forces a head-miss replay. The path resets every window-function map,
        // wipes the anchor map, scans the base TableReader from
        // viewLowerBoundTimestamp through advanceTo, emits a single REPLACE_RANGE
        // commit, and writes a fresh head reflecting the post-replay state.
        // After the dust settles the LV output reads the cumulative sum across
        // all rows in ts order - matching what the non-incremental SELECT
        // against the base would produce.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, sym SYMBOL, x DOUBLE) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, sym, sum(x) OVER w AS s FROM base " +
                    "WINDOW w AS (PARTITION BY sym ORDER BY ts ANCHOR EXPRESSION timestamp_floor('1d', ts))");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                setCurrentMicros(0L);
                execute("INSERT INTO base (ts, sym, x) VALUES " +
                        "('2026-11-01T00:00:10.000000Z', 'a', 1.0), " +
                        "('2026-11-01T00:00:20.000000Z', 'a', 2.0)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                LiveViewInstance lv = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(lv);
                final long preO3HeadLvSeqTxn = lv.getHeadCheckpointLvSeqTxn();
                Assert.assertNotEquals(Numbers.LONG_NULL, preO3HeadLvSeqTxn);
                Assert.assertEquals(
                        MicrosFormatUtils.parseUTCTimestamp("2026-11-01T00:00:20.000000Z"),
                        lv.getHeadCheckpointMaxTs()
                );

                // Drop an O3 row at ts strictly below headMaxTs. lateRowTs=05
                // < headMaxTs=20 - head-miss eligibility is the only path.
                setCurrentMicros(200_000L);
                execute("INSERT INTO base (ts, sym, x) VALUES " +
                        "('2026-11-01T00:00:05.000000Z', 'a', 3.0)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                // Post-replay LV output is the cumulative sum across all three
                // rows in ts-ascending order: 3 -> 3+1=4 -> 4+2=6.
                assertQuery("SELECT ts, sym, s FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns("ts\tsym\ts\n" +
                        "2026-11-01T00:00:05.000000Z\ta\t3.0\n" +
                        "2026-11-01T00:00:10.000000Z\ta\t4.0\n" +
                        "2026-11-01T00:00:20.000000Z\ta\t6.0\n");

                // A fresh head has landed at a new lvSeqTxn, the prior one is
                // gone on disk.
                Assert.assertNotEquals(preO3HeadLvSeqTxn, lv.getHeadCheckpointLvSeqTxn());
                Assert.assertNotEquals(Numbers.LONG_NULL, lv.getHeadCheckpointLvSeqTxn());

                // lvRowsTotal (-> MANIFEST.lvRowPosition) must match the on-disk
                // count: the intact-base head-miss is a full rebuild of 3 rows,
                // counted once. The double-count bug returned 6 (3 on disk + 3
                // appended).
                Assert.assertEquals(3L, lv.getLvRowsTotal());
                assertQuery("SELECT count(*) AS count FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n3\n");
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testO3HeadHitUnderApplyAheadResumesFromAnchor() throws Exception {
        // Companion to testO3HeadMissReplayUnderApplyAheadDoesNotDuplicateTrailingRow
        // for the head-hit branch. A head-hit-eligible O3 trigger (ts strictly above
        // the stale head's maxTimestamp) would normally replay only the tail above
        // the head. But when ApplyWal2TableJob has run ahead, the base snapshot
        // already holds trailing seqTxns the forward drain has not examined; a
        // head-hit replay reads base only above headMaxTs, so it would advance the
        // watermark only to the trigger and let the forward path re-append a trailing
        // global-max row (a duplicate, the same defect as the head-miss case).
        //
        // Before the apply-ahead resume (step 6) the replay detected the ahead
        // snapshot and fell back to a full head-miss recompute. It now resumes from
        // the retained head anchor instead - the ahead range's minimum ts (100s here)
        // sits above the head, so the head is a valid sealed anchor - and commits at
        // the effective seqTxn the snapshot reflects, replaying only the bounded tail
        // (rowsEmitted=4, not a from-boundary recompute) while still advancing the
        // watermark past the trailing commit so it is not re-appended. Both dispositions
        // produce the identical result asserted below.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            setCurrentMicros(0L);
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                // seqTxn 1: two in-order rows. A head lands at maxTs=20.
                execute("INSERT INTO base (ts, x) VALUES " +
                        "('2026-11-01T00:00:10.000000Z', 1), " +
                        "('2026-11-01T00:00:20.000000Z', 2)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                LiveViewInstance lv = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(lv);
                final long headMaxTs20 = lv.getHeadCheckpointMaxTs();
                Assert.assertEquals(
                        MicrosFormatUtils.parseUTCTimestamp("2026-11-01T00:00:20.000000Z"),
                        headMaxTs20
                );

                // seqTxn 2: in-order rows that move latestSeenTs to 40 without
                // rewriting the head (cadence does not fire), so headMaxTs stays 20.
                setCurrentMicros(150_000L);
                execute("INSERT INTO base (ts, x) VALUES " +
                        "('2026-11-01T00:00:30.000000Z', 3), " +
                        "('2026-11-01T00:00:40.000000Z', 4)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();
                Assert.assertEquals("head must still sit at maxTs=20",
                        headMaxTs20, lv.getHeadCheckpointMaxTs());

                // seqTxn 3: O3 trigger at ts=25 (20 < 25 < 40, head-hit eligible).
                // seqTxn 4: a lone trailing row at the global-max ts (100s). Both
                // are committed and applied to the BASE before the refresh job runs
                // again, with NO drainJob between them, so apply runs ahead of the
                // O3 trigger and the forward drain never processes seqTxn 4 alone.
                setCurrentMicros(400_000L);
                execute("INSERT INTO base (ts, x) VALUES ('2026-11-01T00:00:25.000000Z', 5)");
                execute("INSERT INTO base (ts, x) VALUES ('2026-11-01T00:01:40.000000Z', 6)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                // Six rows in ts order, row_number() a gapless 1..6. The bug left
                // seven rows - the global-max row duplicated with rn 7.
                assertQuery("SELECT ts, x, rn FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns("ts\tx\trn\n" +
                        "2026-11-01T00:00:10.000000Z\t1\t1\n" +
                        "2026-11-01T00:00:20.000000Z\t2\t2\n" +
                        "2026-11-01T00:00:25.000000Z\t5\t3\n" +
                        "2026-11-01T00:00:30.000000Z\t3\t4\n" +
                        "2026-11-01T00:00:40.000000Z\t4\t5\n" +
                        "2026-11-01T00:01:40.000000Z\t6\t6\n");
                Assert.assertEquals(6L, lv.getLvRowsTotal());
                assertQuery("SELECT count(*) AS count FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n6\n");
            }

            execute("DROP LIVE VIEW lv");
        });
    }


    @Test
    public void testCheckpointTimelineWalPurgeFloorRetainsPriorSlot() throws Exception {
        // The head arm follows the newest boundary this process sealed. The
        // versioned timeline independently keeps its two A/B generations
        // recoverable, so with generations 1..3 slots 3 and 2 require base WAL
        // from seqTxn 2 while the head sits at 3. This locks both bounds of the
        // combined floor.
        setProperty(PropertyKey.CAIRO_WAL_SEGMENT_ROLLOVER_ROW_COUNT, 1);
        setProperty(PropertyKey.CAIRO_LIVE_VIEW_CHECKPOINT_ROWS, 1);
        assertMemoryLeak(() -> {
            final long t0 = MicrosTimestampDriver.floor("2026-05-31T00:00:00.000000Z");
            setCurrentMicros(t0);
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                for (int seconds = 10; seconds <= 30; seconds += 10) {
                    setCurrentMicros(t0 + seconds * 100_000L);
                    execute("INSERT INTO base (ts, x) VALUES ('2026-06-01T00:00:" + seconds + ".000000Z', " + seconds + ")");
                    drainWalQueue();
                    drainJob(job);
                    drainWalQueue();
                }

                final LiveViewInstance lv = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(lv);
                // Three boundaries span base seqTxn 1..3. The head tracks the
                // newest, while the two timeline slots hold generations 3 and 2
                // after the third publication.
                Assert.assertEquals(3L, lv.getHeadCheckpointBaseSeqTxn());
                Assert.assertEquals("the fallback timeline slot retains generation 2 WAL",
                        2L, lv.getCheckpointTimelineWalPurgeFloor());
            }

            // A trailing base commit the view never consumes, to roll the writer
            // off segment 2.
            setCurrentMicros(t0 + 5_000_000L);
            execute("INSERT INTO base (ts, x) VALUES ('2026-06-01T00:00:40.000000Z', 40)");
            drainWalQueue();
            engine.releaseInactive();
            drainPurgeJob();

            // The ring's oldest entry does not retain segments 0 or 1. Segment 2
            // remains because fallback timeline generation 2 needs seqTxn 3 for
            // recovery after a torn generation-3 publication.
            assertSegmentExistence(false, "base", 1, 0);
            assertSegmentExistence(false, "base", 1, 1);
            assertSegmentExistence(true, "base", 1, 2);
            // seqTxn 4 is unconsumed, so lvConsumed floors it regardless of the
            // timeline - the sweep did not simply take everything.
            assertSegmentExistence(true, "base", 1, 3);

            assertNoRefreshFaults("lv");
            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testO3ReplayScanRowsCountsFilteredRowsInBoundaryRebuild() throws Exception {
        // Baseline observability: o3_replay_scan_rows counts every base row an O3
        // replay pulls, including rows the WHERE filter drops, so with a filter it
        // strictly exceeds the emit count o3_boundary_replay_rows. The view keeps
        // x > 0 and the base carries one x <= 0 row in the frame; a corrupt-head
        // restart forces a boundary rebuild that scans all three base rows but
        // re-emits only the two that pass the filter.
        setProperty(PropertyKey.CAIRO_LIVE_VIEW_CHECKPOINT_ROWS, 1);
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            setCurrentMicros(0L);
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");

            final long headLvSeqTxn;
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                // Kept, dropped, kept - all inside the eventual replay frame.
                setCurrentMicros(200_000L);
                execute("INSERT INTO base (ts, x) VALUES ('2026-11-01T00:00:10.000000Z', 10)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();
                setCurrentMicros(400_000L);
                execute("INSERT INTO base (ts, x) VALUES ('2026-11-01T00:00:20.000000Z', -1)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();
                setCurrentMicros(600_000L);
                execute("INSERT INTO base (ts, x) VALUES ('2026-11-01T00:00:30.000000Z', 30)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                final LiveViewInstance lv = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(lv);
                headLvSeqTxn = lv.getHeadCheckpointLvSeqTxn();
            }

            // Remove the timeline so the restart has no root to restore from and
            // falls back to a full boundary rebuild from the lower bound.
            try (Path timelinePath = new Path()) {
                final LiveViewInstance lv = engine.getLiveViewRegistry().getViewInstance("lv");
                timelinePath.of(engine.getConfiguration().getDbRoot())
                        .concat(lv.getLiveViewToken())
                        .concat(LiveViewCheckpointLayout.CHECKPOINT_DIR_NAME);
                LiveViewCheckpointLayout.timelinePath(timelinePath, timelinePath);
                Assert.assertTrue(
                        "the timeline must exist before the rebuild is forced",
                        engine.getConfiguration().getFilesFacade().removeQuiet(timelinePath.$())
                );
            }

            engine.getLiveViewRegistry().clear();
            engine.buildViewGraphs();
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                setCurrentMicros(1_000_000L);
                drainJob(job);
                drainWalQueue();
            }

            final LiveViewInstance reloaded = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(reloaded);
            Assert.assertTrue(reloaded.isCheckpointRestoreSucceeded());
            // The rebuild scans all three base rows but re-emits only the two that
            // pass x > 0, so scan strictly exceeds emit by the one dropped row.
            assertQuery("SELECT o3_boundary_replay_rows, o3_replay_scan_rows FROM live_views()")
                    .noLeakCheck().noRandomAccess()
                    .returns("o3_boundary_replay_rows\to3_replay_scan_rows\n2\t3\n");
            assertQuery("SELECT ts, x, rn FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize()
                    .returns("ts\tx\trn\n" +
                            "2026-11-01T00:00:10.000000Z\t10\t1\n" +
                            "2026-11-01T00:00:30.000000Z\t30\t2\n");

            execute("DROP LIVE VIEW lv");
        });
    }


    @Test
    public void testO3BoundedMissUnderApplyAheadReanchorsBelowAheadMinimum() throws Exception {
        setProperty(PropertyKey.CAIRO_LIVE_VIEW_CHECKPOINT_ROWS, 1);
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            setCurrentMicros(0L);
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                // Build retained anchors at 10 and 20, with the head at 30.
                for (int seconds = 10; seconds <= 30; seconds += 10) {
                    setCurrentMicros(seconds * 20_000L);
                    execute("INSERT INTO base (ts, x) VALUES ('2026-11-01T00:00:" + seconds + ".000000Z', " + seconds + ")");
                    drainWalQueue();
                    drainJob(job);
                    drainWalQueue();
                }

                LiveViewInstance lv = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(lv);
                Assert.assertEquals(MicrosFormatUtils.parseUTCTimestamp("2026-11-01T00:00:30.000000Z"), lv.getHeadCheckpointMaxTs());

                // Trigger 25 initially selects the boundary at 20.
                // Apply then races ahead with minTs=15, forcing re-anchor at 10.
                setCurrentMicros(800_000L);
                execute("INSERT INTO base (ts, x) VALUES ('2026-11-01T00:00:25.000000Z', 25)");
                execute("INSERT INTO base (ts, x) VALUES ('2026-11-01T00:00:15.000000Z', 15)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                assertQuery("SELECT ts, x, rn FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns("ts\tx\trn\n" +
                        "2026-11-01T00:00:10.000000Z\t10\t1\n" +
                        "2026-11-01T00:00:15.000000Z\t15\t2\n" +
                        "2026-11-01T00:00:20.000000Z\t20\t3\n" +
                        "2026-11-01T00:00:25.000000Z\t25\t4\n" +
                        "2026-11-01T00:00:30.000000Z\t30\t5\n");
                // This view has no WHERE filter, so the resume replay scans exactly the 4 rows
                // it re-emits. The other 5 are planning: the plan prices the resume against a
                // localized rebuild before choosing, and for a ROWS frame those bounds come from
                // a discovery that reads base rows. A 1_000_000-row frame walks the history out
                // and proves no finite H, so the resume wins - having paid for the answer.
                assertQuery("SELECT o3_resume_replay_rows, o3_boundary_replay_rows, o3_replay_scan_rows FROM live_views()")
                        .noLeakCheck().noRandomAccess()
                        .returns("o3_resume_replay_rows\to3_boundary_replay_rows\to3_replay_scan_rows\n4\t0\t9\n");
                Assert.assertEquals(5L, lv.getLvRowsTotal());
                Assert.assertEquals(5L, lv.getStateReader().getLvConsumedSeqTxn());
                // The repair retired the timeline and sealed a fresh boundary at 30
                // over the replayed state.
                Assert.assertEquals(MicrosFormatUtils.parseUTCTimestamp("2026-11-01T00:00:30.000000Z"), lv.getHeadCheckpointMaxTs());
            }
            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testO3ApplyAheadTruncateFallsBackToBoundary() throws Exception {
        setProperty(PropertyKey.CAIRO_LIVE_VIEW_CHECKPOINT_ROWS, 1);
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            setCurrentMicros(0L);
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                for (int seconds = 10; seconds <= 30; seconds += 10) {
                    setCurrentMicros(seconds * 20_000L);
                    execute("INSERT INTO base (ts, x) VALUES ('2026-11-01T00:00:" + seconds + ".000000Z', " + seconds + ")");
                    drainWalQueue();
                    drainJob(job);
                    drainWalQueue();
                }

                LiveViewInstance lv = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(lv);

                // The trigger qualifies for the boundary at 20, but the unexamined ahead
                // range contains TRUNCATE. Only boundary replay can preserve the
                // prefix below the trigger while applying the trigger's delete
                // authority at and above 25. TRUNCATE itself is transparent to
                // previously materialised LV rows by contract.
                setCurrentMicros(800_000L);
                execute("INSERT INTO base (ts, x) VALUES ('2026-11-01T00:00:25.000000Z', 25)");
                execute("TRUNCATE TABLE base");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                assertQuery("SELECT ts, x, rn FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns("ts\tx\trn\n" +
                        "2026-11-01T00:00:10.000000Z\t10\t1\n" +
                        "2026-11-01T00:00:20.000000Z\t20\t2\n");
                assertQuery("SELECT ts, x FROM base ORDER BY ts").noLeakCheck().timestamp("ts").returns("ts\tx\n");
                assertQuery("SELECT o3_resume_replay_rows, o3_boundary_replay_rows FROM live_views()")
                        .noLeakCheck().noRandomAccess()
                        .returns("o3_resume_replay_rows\to3_boundary_replay_rows\n0\t0\n");
                Assert.assertEquals(2L, lv.getLvRowsTotal());
                Assert.assertEquals(5L, lv.getStateReader().getLvConsumedSeqTxn());
            }
            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testO3ApplyAheadResumeGuardIncludesBackdatedAheadRow() throws Exception {
        // The apply-ahead resume (step 6) must never drop a back-dated row hidden in
        // the ahead range below the resume anchor. A head-hit-eligible O3 trigger
        // (ts=25, above the stale head at maxTs=20) would resume from the head anchor
        // and replay only (20, +inf). But ApplyWal2TableJob has raced ahead and the
        // ahead range holds a row BELOW the head (ts=05); a naive resume from the head
        // would scan only (20, +inf) and never read ts=05 - a silent permanent drop.
        // The minAheadTs guard sees the ahead range's minimum (05) sits below every
        // retained anchor, refuses the resume, and rebuilds from the boundary, which
        // materialises the whole snapshot including ts=05.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            setCurrentMicros(0L);
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                // seqTxn 1: two in-order rows. A head lands at maxTs=20.
                execute("INSERT INTO base (ts, x) VALUES " +
                        "('2026-11-01T00:00:10.000000Z', 10), " +
                        "('2026-11-01T00:00:20.000000Z', 20)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                LiveViewInstance lv = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(lv);
                Assert.assertEquals(
                        MicrosFormatUtils.parseUTCTimestamp("2026-11-01T00:00:20.000000Z"),
                        lv.getHeadCheckpointMaxTs()
                );

                // seqTxn 2: in-order rows that move latestSeenTs to 40 without
                // rewriting the head (cadence does not fire), so headMaxTs stays 20.
                setCurrentMicros(150_000L);
                execute("INSERT INTO base (ts, x) VALUES " +
                        "('2026-11-01T00:00:30.000000Z', 30), " +
                        "('2026-11-01T00:00:40.000000Z', 40)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();
                Assert.assertEquals("head must still sit at maxTs=20",
                        MicrosFormatUtils.parseUTCTimestamp("2026-11-01T00:00:20.000000Z"),
                        lv.getHeadCheckpointMaxTs());

                // seqTxn 3: O3 trigger at ts=25 (20 < 25 < 40, head-hit eligible).
                // seqTxn 4: a back-dated row at ts=05, BELOW the head's maxTs=20 and
                // below every retained anchor. Both are applied to the BASE before the
                // job runs again, with NO drainJob between them, so apply runs ahead of
                // the O3 trigger and ts=05 hides in the unexamined seqTxn 4.
                setCurrentMicros(400_000L);
                execute("INSERT INTO base (ts, x) VALUES ('2026-11-01T00:00:25.000000Z', 25)");
                execute("INSERT INTO base (ts, x) VALUES ('2026-11-01T00:00:05.000000Z', 5)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                // Six rows in ts order, row_number() a gapless 1..6, INCLUDING the
                // back-dated ts=05 row the guard preserved. A resume that ignored the
                // ahead range would have omitted it (five rows, a shifted rn).
                assertQuery("SELECT ts, x, rn FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns("ts\tx\trn\n" +
                        "2026-11-01T00:00:05.000000Z\t5\t1\n" +
                        "2026-11-01T00:00:10.000000Z\t10\t2\n" +
                        "2026-11-01T00:00:20.000000Z\t20\t3\n" +
                        "2026-11-01T00:00:25.000000Z\t25\t4\n" +
                        "2026-11-01T00:00:30.000000Z\t30\t5\n" +
                        "2026-11-01T00:00:40.000000Z\t40\t6\n");
                Assert.assertEquals(6L, lv.getLvRowsTotal());
                assertQuery("SELECT count(*) AS count FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n6\n");
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testO3ApplyAheadRetiresStaleAnchorSoLaterO3DoesNotResumeFromIt() throws Exception {
        // A back-dated ahead row (ts=05, below the head at maxTs=20) un-seals the head
        // as a resume anchor: the head's window state predates ts=05, so any later
        // resume from it would mis-sequence. Step 6 lowers the retire floor to the ahead
        // range's minimum (min(triggerLowTs, minAheadTs)=05) so the stale head is dropped
        // from the ring during the apply-ahead recompute, not kept as a poisoned anchor.
        //
        // This is the differential half of testO3ApplyAheadResumeGuardIncludesBackdatedAheadRow:
        // a SECOND, clean (non-apply-ahead) O3 at ts=22 follows. With the stale maxTs=20
        // anchor retired, it rebuilds from the boundary and stays gapless. Without the
        // retire-floor fix the maxTs=20 anchor survives, the second O3 resumes from it
        // (its counter=2 predates ts=05, and the (20,+inf) replay leaves ts=05/10/20 as a
        // frozen 3-row prefix), and row_number() collides at rn=3 and tops out at 6 for 7
        // rows.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            setCurrentMicros(0L);
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                // seqTxn 1 + 2: build a head at maxTs=20 and move latestSeenTs to 40
                // without rewriting the head (as in the guard test).
                execute("INSERT INTO base (ts, x) VALUES " +
                        "('2026-11-01T00:00:10.000000Z', 10), " +
                        "('2026-11-01T00:00:20.000000Z', 20)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();
                setCurrentMicros(150_000L);
                execute("INSERT INTO base (ts, x) VALUES " +
                        "('2026-11-01T00:00:30.000000Z', 30), " +
                        "('2026-11-01T00:00:40.000000Z', 40)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                LiveViewInstance lv = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(lv);

                // O3 #1 (apply-ahead, back-dated below the head): trigger ts=25, plus a
                // ts=05 row that lands in a seqTxn the forward drain never examines.
                setCurrentMicros(400_000L);
                execute("INSERT INTO base (ts, x) VALUES ('2026-11-01T00:00:25.000000Z', 25)");
                execute("INSERT INTO base (ts, x) VALUES ('2026-11-01T00:00:05.000000Z', 5)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                // O3 #2 (clean, no apply-ahead): a cross-commit O3 at ts=22, below the
                // post-recompute head (maxTs=40) and above the retired stale anchor
                // (maxTs=20). With the stale anchor retired it rebuilds from the boundary.
                setCurrentMicros(650_000L);
                execute("INSERT INTO base (ts, x) VALUES ('2026-11-01T00:00:22.000000Z', 22)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                // Seven rows in ts order, row_number() a gapless 1..7. Resuming from the
                // poisoned maxTs=20 anchor would have produced a duplicate rn=3 and a max
                // rn of 6 for these 7 rows.
                assertQuery("SELECT ts, x, rn FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns("ts\tx\trn\n" +
                        "2026-11-01T00:00:05.000000Z\t5\t1\n" +
                        "2026-11-01T00:00:10.000000Z\t10\t2\n" +
                        "2026-11-01T00:00:20.000000Z\t20\t3\n" +
                        "2026-11-01T00:00:22.000000Z\t22\t4\n" +
                        "2026-11-01T00:00:25.000000Z\t25\t5\n" +
                        "2026-11-01T00:00:30.000000Z\t30\t6\n" +
                        "2026-11-01T00:00:40.000000Z\t40\t7\n");
                Assert.assertEquals(7L, lv.getLvRowsTotal());
                assertQuery("SELECT count(*) AS count FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n7\n");
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testO3ResumeAndBoundaryReplayRowsSurfaceInCatalogue() throws Exception {
        // Observability. live_views() splits the rows an O3 re-emits by path:
        // o3_resume_replay_rows counts bounded resume-from-anchor replays ("the
        // win"), o3_boundary_replay_rows counts the residual O(view age)
        // boundary rebuild taken when the late row predates the whole ring. The
        // two are disjoint - a given O3 replay bumps exactly one - so an
        // operator can see the ring bounding O3 cost and spot any residual full
        // rebuilds.
        setProperty(PropertyKey.CAIRO_LIVE_VIEW_CHECKPOINT_ROWS, 1); // one head per flush -> dense ring
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            setCurrentMicros(0L);
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                // Three in-order commits seal heads at maxTs=10, 20, 30 -> a
                // three-entry ring. In-order forward-append never replays, so both
                // counters stay 0.
                setCurrentMicros(200_000L);
                execute("INSERT INTO base (ts, x) VALUES ('2026-11-01T00:00:10.000000Z', 10)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();
                setCurrentMicros(400_000L);
                execute("INSERT INTO base (ts, x) VALUES ('2026-11-01T00:00:20.000000Z', 20)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();
                setCurrentMicros(600_000L);
                execute("INSERT INTO base (ts, x) VALUES ('2026-11-01T00:00:30.000000Z', 30)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                assertQuery("SELECT o3_resume_replay_rows, o3_boundary_replay_rows FROM live_views()")
                        .noLeakCheck().noRandomAccess()
                        .returns("o3_resume_replay_rows\to3_boundary_replay_rows\n0\t0\n");

                // Cross-commit O3 at ts=15: below the head (30), above the maxTs=10
                // anchor. Resumes from that anchor and re-emits only the tail above it
                // ({15, 20, 30} = 3 rows), so o3_resume_replay_rows becomes 3 while the
                // boundary counter stays 0.
                setCurrentMicros(800_000L);
                execute("INSERT INTO base (ts, x) VALUES ('2026-11-01T00:00:15.000000Z', 15)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                assertQuery("SELECT o3_resume_replay_rows, o3_boundary_replay_rows FROM live_views()")
                        .noLeakCheck().noRandomAccess()
                        .returns("o3_resume_replay_rows\to3_boundary_replay_rows\n3\t0\n");

                // Cross-commit O3 at ts=05: below every surviving ring entry (the
                // maxTs=10 anchor and the fresh post-resume head), so no anchor
                // qualifies and the replay falls back to the full boundary rebuild. It
                // recomputes the whole view ({5, 10, 15, 20, 30} = 5 rows), so
                // o3_boundary_replay_rows becomes 5 while the resume counter is unchanged.
                setCurrentMicros(1_000_000L);
                execute("INSERT INTO base (ts, x) VALUES ('2026-11-01T00:00:05.000000Z', 5)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                assertQuery("SELECT o3_resume_replay_rows, o3_boundary_replay_rows FROM live_views()")
                        .noLeakCheck().noRandomAccess()
                        .returns("o3_resume_replay_rows\to3_boundary_replay_rows\n3\t5\n");
            }

            // Five rows in ts order, row_number() a gapless 1..5 - both replay paths
            // preserved the from-scratch answer over the applied base {5,10,15,20,30}.
            assertQuery("SELECT ts, x, rn FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns("ts\tx\trn\n" +
                    "2026-11-01T00:00:05.000000Z\t5\t1\n" +
                    "2026-11-01T00:00:10.000000Z\t10\t2\n" +
                    "2026-11-01T00:00:15.000000Z\t15\t3\n" +
                    "2026-11-01T00:00:20.000000Z\t20\t4\n" +
                    "2026-11-01T00:00:30.000000Z\t30\t5\n");

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testRefreshLatchReleasedWhenStagingBufferCloseThrows() throws Exception {
        // M2 regression: refreshInstance's finally frees the worker's staging buffer
        // (Misc.free -> LiveViewInMemoryBuffer.close()) and THEN releases the refresh
        // latch (unlockAfterRefresh). Misc.free catches only IOException, so an
        // AssertionError (QuestDB runs with -ea) or a CairoException from a native-memory
        // / tracker-balance assert in close() propagates and skips unlockAfterRefresh -
        // the view's refresh latch is never released and it silently stops refreshing
        // forever, while the shared exec-context tracker stays bound to this view. The
        // fix wraps the free in a nested try/finally so the release always runs, keeping
        // the deliberate "free under the latch" ordering.
        //
        // The fault is armed via a one-shot @TestOnly hook that throws at the exact point
        // where a real close() would - right after Misc.free in the finally.
        assertMemoryLeak(() -> {
            setCurrentMicros(0L);
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms IN MEMORY 60s START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                // Baseline populate cycle establishes the in-mem tier and the staging buffer.
                execute("INSERT INTO base (ts, x) VALUES ('2026-11-01T00:00:10.000000Z', 1)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                LiveViewInstance instance = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(instance);
                // The latch is free between cycles.
                Assert.assertTrue("baseline latch must be free", instance.tryLockForRefresh());
                instance.unlockAfterRefresh();

                // Arm the one-shot staging-buffer close fault, then drive a refresh cycle
                // whose finally frees the staging buffer and throws.
                job.setSimulateStagingBufferCloseFaultForTest();
                setCurrentMicros(200_000L);
                execute("INSERT INTO base (ts, x) VALUES ('2026-11-01T00:00:20.000000Z', 2)");
                drainWalQueue();
                boolean faultObserved = false;
                try {
                    drainJob(job);
                } catch (AssertionError e) {
                    if ("injected staging-buffer close fault".equals(e.getMessage())) {
                        faultObserved = true;
                    } else {
                        throw e;
                    }
                }
                Assert.assertTrue("the injected staging-buffer close fault must fire in the refresh finally", faultObserved);

                // The refresh latch MUST be released even though the staging-buffer close threw.
                // Without the fix, unlockAfterRefresh is skipped and this fails (latch stuck forever).
                Assert.assertTrue("refresh latch must be released even if the staging-buffer close throws",
                        instance.tryLockForRefresh());
                instance.unlockAfterRefresh();

                // The view recovers on the next cycle and serves the correct rows.
                drainJob(job);
                drainWalQueue();
                assertQuery("SELECT ts, x, rn FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns("ts\tx\trn\n" +
                        "2026-11-01T00:00:10.000000Z\t1\t1\n" +
                        "2026-11-01T00:00:20.000000Z\t2\t2\n");
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testO3ApplyAheadWalEventFaultDoesNotLeakBaseReader() throws Exception {
        // M3 regression: the apply-ahead O3 replay must not leak its pooled base
        // TableReader when the WAL-E read that gates the resume faults.
        //
        // o3HeadMissReplay (and replayFromAnchor) acquire a base TableReader via
        // waitForApply into a bare local, then - BEFORE the try/finally that owns
        // reader.close() - call computeApplyAheadMinTs, which opens the base WAL-E
        // event file for the seqTxns ApplyWal2TableJob raced past the O3 trigger. A
        // read fault there (a torn / purged WAL-E - the "applied base outlived its
        // WAL" state the refresh engine handles elsewhere) throws CairoException,
        // which unwinds past the bare reader without closing it. The refresh cycle's
        // top-level catch swallows the throw (ticks the flush-retry budget), so the
        // leak is silent: one pooled reader per failed attempt, surfaced at
        // end-of-test by assertMemoryLeak's busy-reader check (and pinned directly
        // below via getBusyReaderCount()).
        //
        // The scenario mirrors testO3HeadMissReplayUnderApplyAheadDoesNotDuplicateTrailingRow:
        // a back-dated row (seqTxn 2, ts=15 < headMaxTs=20) is head-miss eligible, and a
        // trailing in-order row (seqTxn 3) is applied to the base before the refresh runs,
        // so o3HeadMissReplay pins the reader at seqTxn 3 while the trigger is seqTxn 2 and
        // enters the apply-ahead branch (effectiveSeqTxn != advanceTo).
        //
        // Fault targeting: drainBaseWal's detection reads seqTxn 2's _event and breaks
        // WITHOUT reading seqTxn 3's, and (no SYMBOL column) holds no reader; only
        // computeApplyAheadMinTs reads seqTxn 3's _event, and it does so while the pooled
        // base reader is borrowed. Gating on a busy reader therefore fires the one-shot
        // fault exactly on computeApplyAheadMinTs, never on detection.
        final String[] baseDir = new String[1];
        final AtomicBoolean armed = new AtomicBoolean(false);
        final AtomicBoolean faultFired = new AtomicBoolean(false);
        final FilesFacade ff = new TestFilesFacadeImpl() {
            @Override
            public long openRO(LPSZ name) {
                if (shouldFailBaseWalEventRead(name)) {
                    faultFired.set(true);
                    return -1;
                }
                return super.openRO(name);
            }

            @Override
            public long openRONoCache(LPSZ name) {
                if (shouldFailBaseWalEventRead(name)) {
                    faultFired.set(true);
                    return -1;
                }
                return super.openRONoCache(name);
            }

            private boolean shouldFailBaseWalEventRead(LPSZ name) {
                return armed.get()
                        && !faultFired.get()
                        && baseDir[0] != null
                        && Utf8s.containsAscii(name, baseDir[0])
                        && Utf8s.containsAscii(name, WalUtils.WAL_NAME_BASE)
                        && Utf8s.endsWithAscii(name, WalUtils.EVENT_FILE_NAME)
                        && engine.getBusyReaderCount() > 0;
            }
        };

        assertMemoryLeak(ff, () -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            baseDir[0] = engine.verifyTableName("base").getDirName();
            setCurrentMicros(0L);
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                // seqTxn 1: two in-order rows. A head lands at maxTs=20, latestSeenTs=20.
                execute("INSERT INTO base (ts, x) VALUES " +
                        "('2026-11-01T00:00:10.000000Z', 1), " +
                        "('2026-11-01T00:00:20.000000Z', 2)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                LiveViewInstance lv = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(lv);
                Assert.assertNotEquals(Numbers.LONG_NULL, lv.getHeadCheckpointLvSeqTxn());

                // seqTxn 2: back-dated ts=15 (< headMaxTs=20). seqTxn 3: trailing ts=100s.
                // Both applied to the base before the refresh runs (no drainJob between the
                // inserts), so the replay's base reader sits at seqTxn 3 while the O3 trigger
                // is only seqTxn 2.
                setCurrentMicros(200_000L);
                execute("INSERT INTO base (ts, x) VALUES ('2026-11-01T00:00:15.000000Z', 3)");
                execute("INSERT INTO base (ts, x) VALUES ('2026-11-01T00:01:40.000000Z', 4)");
                drainWalQueue();

                armed.set(true);
                drainJob(job); // faulting apply-ahead cycle: leaks a pooled reader without the fix
                armed.set(false);
                drainWalQueue();

                Assert.assertTrue("computeApplyAheadMinTs must have faulted on the base WAL-E read", faultFired.get());
                // The pooled base reader must be balanced even though the WAL-E read threw.
                Assert.assertEquals("apply-ahead WAL-E fault leaked the pooled base reader",
                        0, engine.getBusyReaderCount());

                // The fault was transient (one-shot); a follow-up cycle converges the view,
                // proving the throw did not permanently wedge the refresh path.
                drainJob(job);
                drainWalQueue();
                assertQuery("SELECT ts, x, rn FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns("ts\tx\trn\n" +
                        "2026-11-01T00:00:10.000000Z\t1\t1\n" +
                        "2026-11-01T00:00:15.000000Z\t3\t2\n" +
                        "2026-11-01T00:00:20.000000Z\t2\t3\n" +
                        "2026-11-01T00:01:40.000000Z\t4\t4\n");
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testO3ApplyAheadHeadHitWalEventFaultDoesNotLeakBaseReader() throws Exception {
        // M3 regression, replayFromAnchor (head-hit) sibling of
        // testO3ApplyAheadWalEventFaultDoesNotLeakBaseReader. A head-hit-eligible O3
        // trigger under apply-ahead routes to replayFromAnchor, which - like
        // o3HeadMissReplay - acquires a pooled base reader via waitForApply and then
        // calls computeApplyAheadMinTs BEFORE the try/finally that owns reader.close().
        // A WAL-E read fault there must not leak the reader. replayFromAnchor also
        // carries an early reader.close()+recurse fallback (no resumable anchor below
        // the ahead floor), so its fix must guard the finally against a double close;
        // this test only exercises the fault-before-fallback path, and the existing
        // apply-ahead resume tests exercise the fallback with the fix in place.
        //
        // Scenario mirrors testO3HeadHitUnderApplyAheadResumesFromAnchor: an O3 trigger
        // at ts=25 (> headMaxTs=20, head-hit eligible) with a trailing seqTxn applied to
        // the base before the refresh runs, so replayFromAnchor pins the reader ahead of
        // the trigger and enters the apply-ahead branch.
        final String[] baseDir = new String[1];
        final AtomicBoolean armed = new AtomicBoolean(false);
        final AtomicBoolean faultFired = new AtomicBoolean(false);
        final FilesFacade ff = new TestFilesFacadeImpl() {
            @Override
            public long openRO(LPSZ name) {
                if (shouldFailBaseWalEventRead(name)) {
                    faultFired.set(true);
                    return -1;
                }
                return super.openRO(name);
            }

            @Override
            public long openRONoCache(LPSZ name) {
                if (shouldFailBaseWalEventRead(name)) {
                    faultFired.set(true);
                    return -1;
                }
                return super.openRONoCache(name);
            }

            private boolean shouldFailBaseWalEventRead(LPSZ name) {
                return armed.get()
                        && !faultFired.get()
                        && baseDir[0] != null
                        && Utf8s.containsAscii(name, baseDir[0])
                        && Utf8s.containsAscii(name, WalUtils.WAL_NAME_BASE)
                        && Utf8s.endsWithAscii(name, WalUtils.EVENT_FILE_NAME)
                        && engine.getBusyReaderCount() > 0;
            }
        };

        assertMemoryLeak(ff, () -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            baseDir[0] = engine.verifyTableName("base").getDirName();
            setCurrentMicros(0L);
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                // seqTxn 1: two in-order rows. A head lands at maxTs=20.
                execute("INSERT INTO base (ts, x) VALUES " +
                        "('2026-11-01T00:00:10.000000Z', 1), " +
                        "('2026-11-01T00:00:20.000000Z', 2)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                LiveViewInstance lv = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(lv);
                Assert.assertNotEquals(Numbers.LONG_NULL, lv.getHeadCheckpointLvSeqTxn());

                // seqTxn 2: in-order rows move latestSeenTs to 40 without rewriting the head.
                setCurrentMicros(150_000L);
                execute("INSERT INTO base (ts, x) VALUES " +
                        "('2026-11-01T00:00:30.000000Z', 3), " +
                        "('2026-11-01T00:00:40.000000Z', 4)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                // seqTxn 3: head-hit O3 trigger at ts=25 (20 < 25 < 40). seqTxn 4: trailing
                // ts=100s. Both applied to the base before the refresh runs.
                setCurrentMicros(400_000L);
                execute("INSERT INTO base (ts, x) VALUES ('2026-11-01T00:00:25.000000Z', 5)");
                execute("INSERT INTO base (ts, x) VALUES ('2026-11-01T00:01:40.000000Z', 6)");
                drainWalQueue();

                armed.set(true);
                drainJob(job); // faulting head-hit apply-ahead cycle: leaks a pooled reader without the fix
                armed.set(false);
                drainWalQueue();

                Assert.assertTrue("computeApplyAheadMinTs must have faulted on the base WAL-E read", faultFired.get());
                Assert.assertEquals("apply-ahead WAL-E fault leaked the pooled base reader",
                        0, engine.getBusyReaderCount());

                // The fault was transient; a follow-up cycle converges the view.
                drainJob(job);
                drainWalQueue();
                assertQuery("SELECT ts, x, rn FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns("ts\tx\trn\n" +
                        "2026-11-01T00:00:10.000000Z\t1\t1\n" +
                        "2026-11-01T00:00:20.000000Z\t2\t2\n" +
                        "2026-11-01T00:00:25.000000Z\t5\t3\n" +
                        "2026-11-01T00:00:30.000000Z\t3\t4\n" +
                        "2026-11-01T00:00:40.000000Z\t4\t5\n" +
                        "2026-11-01T00:01:40.000000Z\t6\t6\n");
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testO3HeadMissReplayUnderApplyAheadDoesNotDuplicateTrailingRow() throws Exception {
        // Regression for the concurrent-O3 permanent duplicate row
        // (LiveViewConcurrencyTest#testMultiWalWriterInterleavingRowNumber). The bug
        // needs only that ApplyWal2TableJob has applied base seqTxns PAST the O3
        // trigger before the refresh job runs, which a multi-writer interleaving
        // produces but a single writer can also stage deterministically. The
        // head-miss replay reads the whole base snapshot - including a trailing
        // in-order commit holding a lone row at the global-max ts - and materialises
        // it, but the buggy path advanced the LV watermark only to the O3 trigger
        // seqTxn. The forward path then re-read that trailing commit and re-appended
        // the global-max row, leaving a permanent duplicate and a corrupted
        // row_number() sequence. The fix advances the watermark to the seqTxn the
        // replay's base snapshot actually reflects, so the trailing commit is not
        // reprocessed.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            setCurrentMicros(0L);
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                // seqTxn 1: two in-order rows. Forward-processed; a head lands at
                // maxTs=20 and latestSeenTs=20.
                execute("INSERT INTO base (ts, x) VALUES " +
                        "('2026-11-01T00:00:10.000000Z', 1), " +
                        "('2026-11-01T00:00:20.000000Z', 2)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                LiveViewInstance lv = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(lv);
                Assert.assertNotEquals(Numbers.LONG_NULL, lv.getHeadCheckpointLvSeqTxn());

                // seqTxn 2: a back-dated row at ts=15 (< headMaxTs=20), head-miss
                // eligible. seqTxn 3: a lone row at the global-max ts (100s), in
                // order. Both are committed and applied to the BASE before the
                // refresh job runs again, so the replay's base reader sits at
                // seqTxn 3 while the O3 trigger is only seqTxn 2 (apply ran ahead).
                // There is NO drainJob between the two inserts, so the forward drain
                // never processes seqTxn 3 on its own.
                setCurrentMicros(200_000L);
                execute("INSERT INTO base (ts, x) VALUES ('2026-11-01T00:00:15.000000Z', 3)");
                execute("INSERT INTO base (ts, x) VALUES ('2026-11-01T00:01:40.000000Z', 4)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                // Exactly four rows, row_number() a gapless 1..4 in ts order. The
                // bug produced five rows - the global-max row duplicated with rn 5.
                assertQuery("SELECT ts, x, rn FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns("ts\tx\trn\n" +
                        "2026-11-01T00:00:10.000000Z\t1\t1\n" +
                        "2026-11-01T00:00:15.000000Z\t3\t2\n" +
                        "2026-11-01T00:00:20.000000Z\t2\t3\n" +
                        "2026-11-01T00:01:40.000000Z\t4\t4\n");
                Assert.assertEquals(4L, lv.getLvRowsTotal());
                assertQuery("SELECT count(*) AS count FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n4\n");
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testO3WithinSingleCommitIsReordered() throws Exception {
        // A single base commit whose rows are NOT in ts-ascending order must
        // not corrupt window state. The refresh worker reads raw (unsorted) WAL
        // segments, so detection cannot rely on the commit's min ts alone:
        // here the whole commit sits above the LV watermark (the LV is empty),
        // yet the rows are internally shuffled. The commit carries
        // WalEventCursor.DataInfo.isOutOfOrder()==true, which must route the
        // batch through the ts-sorted O3 replay path. All rows share one day
        // bucket so no anchor reset fires - the bug is purely row order.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, sym SYMBOL, x DOUBLE) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, sym, sum(x) OVER w AS s, row_number() OVER w AS rn FROM base " +
                    "WINDOW w AS (PARTITION BY sym ORDER BY ts ANCHOR EXPRESSION timestamp_floor('1d', ts))");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                // One INSERT statement == one WAL commit; the two rows are out
                // of ts order within it (ts=20 appended before ts=10).
                execute("INSERT INTO base (ts, sym, x) VALUES " +
                        "('2026-11-01T00:00:20.000000Z', 'a', 2.0), " +
                        "('2026-11-01T00:00:10.000000Z', 'a', 1.0)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                // Correct cumulative-in-ts-order output:
                //   ts=10 -> sum=1.0, rn=1
                //   ts=20 -> sum=1+2=3.0, rn=2
                // The buggy in-WAL-order path computes the reverse (ts=10 carries
                // sum=3.0/rn=2 because it was processed second).
                assertQuery("SELECT ts, sym, s, rn FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns("ts\tsym\ts\trn\n" +
                        "2026-11-01T00:00:10.000000Z\ta\t1.0\t1\n" +
                        "2026-11-01T00:00:20.000000Z\ta\t3.0\t2\n");
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testO3HeadMissWithFullyFilteredReplayPreservesState() throws Exception {
        // The head-miss path replays from viewLowerBoundTimestamp and
        // rebuilds state. The probe-then-wipe ordering ensures a replay that
        // produces zero output rows does not clobber pre-O3 accumulator
        // state. This test covers the closely related scenario: an O3 commit
        // whose row is filtered out by the LV's WHERE; the replay still reads
        // two surviving base rows so the probe passes, the wipe + replay run
        // as usual, and the LV's output matches the pre-O3 state.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, sym SYMBOL, x DOUBLE) " +
                    "TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, sym, sum(x) OVER w AS s FROM base WHERE x > 100 " +
                    "WINDOW w AS (PARTITION BY sym ORDER BY ts ANCHOR EXPRESSION timestamp_floor('1d', ts))");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                setCurrentMicros(0L);
                execute("INSERT INTO base (ts, sym, x) VALUES " +
                        "('2026-11-01T00:00:10.000000Z', 'a', 200.0), " +
                        "('2026-11-01T00:00:20.000000Z', 'a', 300.0)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                assertQuery("SELECT ts, sym, s FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns("ts\tsym\ts\n" +
                        "2026-11-01T00:00:10.000000Z\ta\t200.0\n" +
                        "2026-11-01T00:00:20.000000Z\ta\t500.0\n");

                // O3 row at ts=05 that fails the filter (x <= 100). The WAL
                // path still detects O3 by min(ts) < latestSeenTs; head-miss
                // replay reads (05,50), (10,200), (20,300) from the
                // TableReader, the filter drops (05,50), and the post-filter
                // probe sees the remaining two rows. State wipes and
                // rebuilds; LV output is unchanged.
                setCurrentMicros(200_000L);
                execute("INSERT INTO base (ts, sym, x) VALUES " +
                        "('2026-11-01T00:00:05.000000Z', 'a', 50.0)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                assertQuery("SELECT ts, sym, s FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns("ts\tsym\ts\n" +
                        "2026-11-01T00:00:10.000000Z\ta\t200.0\n" +
                        "2026-11-01T00:00:20.000000Z\ta\t500.0\n");
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testO3HeadMissConvergentEmptyingClearsGhostRows() throws Exception {
        // Sibling of testO3HeadMissWithFullyFilteredReplayPreservesState, but
        // here the O3 commit is a CONVERGENT DATA replacement (dedup UPSERT)
        // that pushes EVERY surviving base row below the LV's WHERE filter, so
        // the head-miss recompute produces zero rows. The probe-then-skip path
        // used to leave the two pre-O3 output rows stranded on disk as ghosts
        // (size() over-reporting) while the watermark advanced past the commit
        // that removed their base rows. The fix emits a pure-delete
        // REPLACE_RANGE over [lateRowTs, +inf) and resets accumulator state, so
        // the view empties and a subsequent forward row cumulates from scratch.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, sym SYMBOL, x DOUBLE) " +
                    "TIMESTAMP(ts) PARTITION BY DAY WAL DEDUP UPSERT KEYS(ts, sym)");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, sym, sum(x) OVER w AS s FROM base WHERE x > 100 " +
                    "WINDOW w AS (PARTITION BY sym ORDER BY ts ANCHOR EXPRESSION timestamp_floor('1d', ts))");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                setCurrentMicros(0L);
                execute("INSERT INTO base (ts, sym, x) VALUES " +
                        "('2026-11-01T00:00:10.000000Z', 'a', 200.0), " +
                        "('2026-11-01T00:00:20.000000Z', 'a', 300.0)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                assertQuery("SELECT ts, sym, s FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns("ts\tsym\ts\n" +
                        "2026-11-01T00:00:10.000000Z\ta\t200.0\n" +
                        "2026-11-01T00:00:20.000000Z\ta\t500.0\n");

                // Single dedup UPSERT that replaces BOTH base rows with values
                // failing the filter (x <= 100). min(ts)=10 < latestSeenTs=20
                // trips O3 detection; head-miss reads (10,50),(20,50), the
                // filter drops both, and the probe sees no surviving row. lateRowTs
                // = 10 (a DATA trigger), so the replay clears [10, +inf).
                setCurrentMicros(200_000L);
                execute("INSERT INTO base (ts, sym, x) VALUES " +
                        "('2026-11-01T00:00:10.000000Z', 'a', 50.0), " +
                        "('2026-11-01T00:00:20.000000Z', 'a', 50.0)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                LiveViewInstance lv = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(lv);
                Assert.assertFalse(lv.isInvalid());
                // Ghost rows are gone: the view is empty.
                assertQuery("SELECT ts, sym, s FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns("ts\tsym\ts\n");

                // A forward in-order row for the same partition must cumulate
                // from scratch (sum = 500, not 1000): proof the accumulator was
                // reset alongside the on-disk delete, not left at its pre-O3 500.
                setCurrentMicros(400_000L);
                execute("INSERT INTO base (ts, sym, x) VALUES " +
                        "('2026-11-01T00:00:30.000000Z', 'a', 500.0)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                assertQuery("SELECT ts, sym, s FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns("ts\tsym\ts\n" +
                        "2026-11-01T00:00:30.000000Z\ta\t500.0\n");
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testO3HeadMissAfterBaseDropPartitionPreservesUnrefreshablePrefix() throws Exception {
        // Head-miss O3 replay re-reads the BASE table (it is not base-
        // independent). When the base has dropped an old partition, the replay
        // can no longer produce rows for that range. Without the replayMinTs
        // clamp the REPLACE_RANGE spanned [viewLowerBoundTimestamp, +inf) and
        // DELETED the LV's already-computed rows for the dropped range. The
        // clamp scopes the rewrite to the rows the base still produces, so the
        // unrefreshable prefix is preserved (frozen) instead of dropped. The
        // daily anchor makes each day its own bucket, so dropping a whole day
        // leaves the surviving days on bucket boundaries (no straddling-bucket
        // accumulator artifact in this scenario).
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, sym SYMBOL, x DOUBLE) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, sym, sum(x) OVER w AS s FROM base " +
                    "WINDOW w AS (PARTITION BY sym ORDER BY ts ANCHOR EXPRESSION timestamp_floor('1d', ts))");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                execute("INSERT INTO base (ts, sym, x) VALUES " +
                        "('2026-11-01T00:00:10.000000Z', 'a', 1.0), " +
                        "('2026-11-01T00:00:20.000000Z', 'a', 2.0), " +
                        "('2026-11-02T00:00:10.000000Z', 'a', 10.0), " +
                        "('2026-11-02T00:00:20.000000Z', 'a', 20.0), " +
                        "('2026-11-03T00:00:10.000000Z', 'a', 100.0), " +
                        "('2026-11-03T00:00:20.000000Z', 'a', 200.0)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                LiveViewInstance lv = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(lv);
                // A head checkpoint must exist so the upcoming deep-past O3 is a
                // genuine head-miss decision rather than a no-head fallback.
                Assert.assertNotEquals(Numbers.LONG_NULL, lv.getHeadCheckpointLvSeqTxn());
                // Per-day cumulative sum (the anchor resets each day).
                assertQuery("SELECT ts, sym, s FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns("ts\tsym\ts\n" +
                        "2026-11-01T00:00:10.000000Z\ta\t1.0\n" +
                        "2026-11-01T00:00:20.000000Z\ta\t3.0\n" +
                        "2026-11-02T00:00:10.000000Z\ta\t10.0\n" +
                        "2026-11-02T00:00:20.000000Z\ta\t30.0\n" +
                        "2026-11-03T00:00:10.000000Z\ta\t100.0\n" +
                        "2026-11-03T00:00:20.000000Z\ta\t300.0\n");

                // Base drops its oldest partition; the LV walks past it
                // (transparent) and stays ACTIVE with its derived rows intact.
                execute("ALTER TABLE base DROP PARTITION LIST '2026-11-01'");
                drainWalQueue();
                lv.setLastFlushTimeUs(Numbers.LONG_NULL);
                drainJob(job);
                drainWalQueue();
                Assert.assertFalse(lv.isInvalid());

                // Deep-past O3 into the surviving day-2 bucket (ts < headMaxTs)
                // forces a head-miss replay. The base no longer holds day-1, so
                // the replay produces nothing below 2026-11-02; the clamp leaves
                // the day-1 LV rows in place rather than deleting them.
                lv.setLastFlushTimeUs(Numbers.LONG_NULL);
                execute("INSERT INTO base (ts, sym, x) VALUES ('2026-11-02T00:00:05.000000Z', 'a', 5.0)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                Assert.assertFalse(lv.isInvalid());
                assertQuery("SELECT view_status FROM live_views() WHERE view_name = 'lv'").noLeakCheck().noRandomAccess().returns("view_status\nactive\n");
                // Day-1 rows survive with their ORIGINAL sums (frozen prefix);
                // day-2 is rewritten with the merged O3 row; day-3 is unchanged.
                // Without the clamp, the day-1 rows would be gone.
                assertQuery("SELECT ts, sym, s FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns("ts\tsym\ts\n" +
                        "2026-11-01T00:00:10.000000Z\ta\t1.0\n" +
                        "2026-11-01T00:00:20.000000Z\ta\t3.0\n" +
                        "2026-11-02T00:00:05.000000Z\ta\t5.0\n" +
                        "2026-11-02T00:00:10.000000Z\ta\t15.0\n" +
                        "2026-11-02T00:00:20.000000Z\ta\t35.0\n" +
                        "2026-11-03T00:00:10.000000Z\ta\t100.0\n" +
                        "2026-11-03T00:00:20.000000Z\ta\t300.0\n");
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testO3HeadHitReplaysFromHead() throws Exception {
        // An O3 row with ts > head.maxTimestamp drops into the
        // head-hit branch. State rolls back to the head's snapshot moment
        // (restoreFromHead populates anchor + function maps), the replay
        // scans only the rows past head.maxTimestamp, and emits a single
        // REPLACE_RANGE commit covering (head.maxTimestamp, +inf). LV
        // output afterwards is the cumulative sum across all rows in
        // ts-ascending order.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, sym SYMBOL, x DOUBLE) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, sym, sum(x) OVER w AS s FROM base " +
                    "WINDOW w AS (PARTITION BY sym ORDER BY ts ANCHOR EXPRESSION timestamp_floor('1d', ts))");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                // Batch 1: two rows. Drain writes a head at maxTs=20.
                setCurrentMicros(0L);
                execute("INSERT INTO base (ts, sym, x) VALUES " +
                        "('2026-11-01T00:00:10.000000Z', 'a', 1.0), " +
                        "('2026-11-01T00:00:20.000000Z', 'a', 2.0)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                LiveViewInstance lv = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(lv);
                final long preO3HeadLvSeqTxn = lv.getHeadCheckpointLvSeqTxn();
                Assert.assertNotEquals(Numbers.LONG_NULL, preO3HeadLvSeqTxn);
                Assert.assertEquals(
                        MicrosFormatUtils.parseUTCTimestamp("2026-11-01T00:00:20.000000Z"),
                        lv.getHeadCheckpointMaxTs()
                );

                // Batch 2: two more rows in WAL order. Cadence triggers
                // (default 1M rows / 5 min) do not fire, so the head
                // metadata still points at the batch-1 head.
                setCurrentMicros(150_000L);
                execute("INSERT INTO base (ts, sym, x) VALUES " +
                        "('2026-11-01T00:00:30.000000Z', 'a', 3.0), " +
                        "('2026-11-01T00:00:40.000000Z', 'a', 4.0)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                Assert.assertEquals(
                        "head metadata unchanged after batch 2 (cadence did not fire)",
                        preO3HeadLvSeqTxn,
                        lv.getHeadCheckpointLvSeqTxn()
                );
                Assert.assertEquals(
                        MicrosFormatUtils.parseUTCTimestamp("2026-11-01T00:00:40.000000Z"),
                        lv.getLatestSeenTs()
                );

                // O3 row at ts=25 sits strictly between headMaxTs=20 and
                // latestSeenTs=40, so head-hit eligibility applies
                // (headMaxTs <= lateRowTs).
                setCurrentMicros(400_000L);
                execute("INSERT INTO base (ts, sym, x) VALUES " +
                        "('2026-11-01T00:00:25.000000Z', 'a', 5.0)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                // Post-replay output: cumulative sum across all five rows
                // ordered by ts.
                assertQuery("SELECT ts, sym, s FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns("ts\tsym\ts\n" +
                        "2026-11-01T00:00:10.000000Z\ta\t1.0\n" +
                        "2026-11-01T00:00:20.000000Z\ta\t3.0\n" +
                        "2026-11-01T00:00:25.000000Z\ta\t8.0\n" +
                        "2026-11-01T00:00:30.000000Z\ta\t11.0\n" +
                        "2026-11-01T00:00:40.000000Z\ta\t15.0\n");

                Assert.assertNotEquals(preO3HeadLvSeqTxn, lv.getHeadCheckpointLvSeqTxn());
                Assert.assertNotEquals(Numbers.LONG_NULL, lv.getHeadCheckpointLvSeqTxn());
                Assert.assertEquals(
                        "post-replay head maxTs reflects max row in replay output",
                        MicrosFormatUtils.parseUTCTimestamp("2026-11-01T00:00:40.000000Z"),
                        lv.getHeadCheckpointMaxTs()
                );
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testO3RebuildsInMemoryTier() throws Exception {
        // After an O3 replay rewrites the on-disk tier (REPLACE_RANGE), the in-mem
        // tier still holds the pre-replay output rows for the rewritten range. The
        // refresh worker rebuilds the in-mem tier atomically from the rewritten LV
        // table, stamped with the post-O3 LV-table seqTxn, so a post-O3 cursor
        // regains Mode B immediately rather than falling through to disk until the
        // next normal cycle. (This LV has a SYMBOL output column; the rebuild and
        // the normal cycle both store LV-table-space symbol ids, so reads route
        // through the tier and resolve symbols correctly.) The seqTxn fence keeps
        // the read correct regardless of whether the rebuild populated the tier.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, sym SYMBOL, x DOUBLE) TIMESTAMP(ts) PARTITION BY DAY WAL");
            // IN MEMORY 1h keeps every test row resident in the in-mem tier.
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms IN MEMORY 1h START FROM NOW AS " +
                    "SELECT ts, sym, sum(x) OVER w AS s FROM base " +
                    "WINDOW w AS (PARTITION BY sym ORDER BY ts ANCHOR EXPRESSION timestamp_floor('1d', ts))");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                // Two in-order batches: four rows land in the in-mem tier; the
                // batch-1 head sits at maxTs=20.
                setCurrentMicros(0L);
                execute("INSERT INTO base (ts, sym, x) VALUES " +
                        "('2026-11-01T00:00:10.000000Z', 'a', 1.0), " +
                        "('2026-11-01T00:00:20.000000Z', 'a', 2.0)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                setCurrentMicros(150_000L);
                execute("INSERT INTO base (ts, sym, x) VALUES " +
                        "('2026-11-01T00:00:30.000000Z', 'a', 3.0), " +
                        "('2026-11-01T00:00:40.000000Z', 'a', 4.0)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                LiveViewInstance lv = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(lv);
                LiveViewInMemoryTier tier = lv.getInMemoryTier();
                Assert.assertNotNull("in-mem tier must be allocated after refresh", tier);
                Assert.assertEquals(
                        "in-mem tier holds all four in-order rows before O3",
                        4,
                        tier.getSlot(tier.getPublishedIdx()).rowCount()
                );

                // O3 row at ts=25 sits inside the in-mem-resident range and
                // strictly above headMaxTs=20, so it drives a head-hit replay
                // that rewrites the on-disk tier.
                setCurrentMicros(400_000L);
                execute("INSERT INTO base (ts, sym, x) VALUES " +
                        "('2026-11-01T00:00:25.000000Z', 'a', 5.0)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                // The replay rebuilt the in-mem tier from the rewritten LV table:
                // the published slot holds the full IN MEMORY window (all five
                // rows fit the 1h window), not the pre-O3 four.
                Assert.assertEquals(
                        "O3 replay must rebuild the in-mem tier from disk",
                        5,
                        tier.getSlot(tier.getPublishedIdx()).rowCount()
                );

                // Reads are correct post-O3 (served from the rewritten on-disk
                // tier): cumulative sum across all five rows in ts order.
                assertQuery("SELECT ts, sym, s FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns("ts\tsym\ts\n" +
                        "2026-11-01T00:00:10.000000Z\ta\t1.0\n" +
                        "2026-11-01T00:00:20.000000Z\ta\t3.0\n" +
                        "2026-11-01T00:00:25.000000Z\ta\t8.0\n" +
                        "2026-11-01T00:00:30.000000Z\ta\t11.0\n" +
                        "2026-11-01T00:00:40.000000Z\ta\t15.0\n");

                // A subsequent in-order commit appends onto the rebuilt tier.
                setCurrentMicros(600_000L);
                execute("INSERT INTO base (ts, sym, x) VALUES " +
                        "('2026-11-01T00:00:50.000000Z', 'a', 6.0)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();
                Assert.assertEquals(
                        "next normal cycle appends onto the rebuilt in-mem tier",
                        6,
                        tier.getSlot(tier.getPublishedIdx()).rowCount()
                );
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testO3AtHeadMaxTimestampBoundaryIsNotDropped() throws Exception {
        // Boundary case: an O3 row whose ts is EXACTLY the head's maxTimestamp.
        // Head-hit eligibility must be strict (headMaxTs < lateRowTs): the head
        // state already covers every row up to and including headMaxTs, and a
        // head-hit replay starts at headMaxTs + 1, so a late row at headMaxTs
        // would be excluded from the replay and silently lost. The exact
        // boundary must route to head-miss instead, which re-reads from
        // viewLowerBoundTimestamp and merges the late row in ts order.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, sym SYMBOL, x DOUBLE) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, sym, sum(x) OVER w AS s FROM base " +
                    "WINDOW w AS (PARTITION BY sym ORDER BY ts ANCHOR EXPRESSION timestamp_floor('1d', ts))");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                // Batch 1: two rows. Drain writes a head at maxTs=20.
                setCurrentMicros(0L);
                execute("INSERT INTO base (ts, sym, x) VALUES " +
                        "('2026-11-01T00:00:10.000000Z', 'a', 1.0), " +
                        "('2026-11-01T00:00:20.000000Z', 'a', 2.0)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                LiveViewInstance lv = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(lv);
                final long preO3HeadLvSeqTxn = lv.getHeadCheckpointLvSeqTxn();
                Assert.assertNotEquals(Numbers.LONG_NULL, preO3HeadLvSeqTxn);
                Assert.assertEquals(
                        MicrosFormatUtils.parseUTCTimestamp("2026-11-01T00:00:20.000000Z"),
                        lv.getHeadCheckpointMaxTs()
                );

                // Batch 2: advance latestSeenTs to 40 without rewriting the head
                // (cadence triggers do not fire), so headMaxTs stays at 20 while
                // the watermark moves past it.
                setCurrentMicros(150_000L);
                execute("INSERT INTO base (ts, sym, x) VALUES " +
                        "('2026-11-01T00:00:30.000000Z', 'a', 4.0), " +
                        "('2026-11-01T00:00:40.000000Z', 'a', 8.0)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                Assert.assertEquals(
                        "head metadata unchanged after batch 2 (cadence did not fire)",
                        preO3HeadLvSeqTxn,
                        lv.getHeadCheckpointLvSeqTxn()
                );
                Assert.assertEquals(
                        MicrosFormatUtils.parseUTCTimestamp("2026-11-01T00:00:40.000000Z"),
                        lv.getLatestSeenTs()
                );

                // O3 row at ts=20 == headMaxTs. latestSeenTs=40, so it is O3
                // (20 < 40). Under strict head-hit eligibility it routes to
                // head-miss; the late row tie-sorts after the original ts=20 row
                // and merges into the cumulative sum.
                setCurrentMicros(400_000L);
                execute("INSERT INTO base (ts, sym, x) VALUES " +
                        "('2026-11-01T00:00:20.000000Z', 'a', 100.0)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                // Correct cumulative sum across all rows in ts order, ties by
                // WAL order (original ts=20 before the O3 ts=20):
                //   10 -> 1, 20 -> 3, 20 -> 103, 30 -> 107, 40 -> 115.
                // The pre-fix head-hit path replays from 21 and drops the O3 row
                // entirely, yielding 10->1, 20->3, 30->7, 40->15 (four rows).
                assertQuery("SELECT ts, sym, s FROM lv ORDER BY ts, s").noLeakCheck().timestamp("ts").expectSize().returns("ts\tsym\ts\n" +
                        "2026-11-01T00:00:10.000000Z\ta\t1.0\n" +
                        "2026-11-01T00:00:20.000000Z\ta\t3.0\n" +
                        "2026-11-01T00:00:20.000000Z\ta\t103.0\n" +
                        "2026-11-01T00:00:30.000000Z\ta\t107.0\n" +
                        "2026-11-01T00:00:40.000000Z\ta\t115.0\n");
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testO3StormAtFixedHorizon() throws Exception {
        // Repeated O3 rows at the same historical horizon (well
        // below headMaxTs) fall into the head-miss path each time. Every event triggers a
        // full replay from viewLowerBoundTimestamp and writes one fresh head.
        // After three such events the LV output reflects all rows in ts order.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, sym SYMBOL, x DOUBLE) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, sym, sum(x) OVER w AS s FROM base " +
                    "WINDOW w AS (PARTITION BY sym ORDER BY ts ANCHOR EXPRESSION timestamp_floor('1d', ts))");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                setCurrentMicros(0L);
                execute("INSERT INTO base (ts, sym, x) VALUES " +
                        "('2026-11-01T00:00:50.000000Z', 'a', 1.0)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                LiveViewInstance lv = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(lv);
                long lastHeadLvSeqTxn = lv.getHeadCheckpointLvSeqTxn();
                Assert.assertNotEquals(Numbers.LONG_NULL, lastHeadLvSeqTxn);

                String[] o3Inserts = new String[]{
                        "('2026-11-01T00:00:05.000000Z', 'a', 2.0)",
                        "('2026-11-01T00:00:06.000000Z', 'a', 3.0)",
                        "('2026-11-01T00:00:07.000000Z', 'a', 4.0)",
                };
                long microtime = 200_000L;
                for (int i = 0; i < o3Inserts.length; i++) {
                    setCurrentMicros(microtime);
                    execute("INSERT INTO base (ts, sym, x) VALUES " + o3Inserts[i]);
                    drainWalQueue();
                    drainJob(job);
                    drainWalQueue();
                    microtime += 200_000L;

                    // Each storm event writes a fresh head with a new lvSeqTxn.
                    long head = lv.getHeadCheckpointLvSeqTxn();
                    Assert.assertNotEquals("storm event #" + i + " did not refresh the head", lastHeadLvSeqTxn, head);
                    Assert.assertNotEquals(Numbers.LONG_NULL, head);
                    lastHeadLvSeqTxn = head;
                }

                // Final LV output covers all four rows in ts order with the
                // cumulative sum across the day-anchored bucket.
                assertQuery("SELECT ts, sym, s FROM lv ORDER BY ts").noLeakCheck().timestamp("ts").expectSize().returns("ts\tsym\ts\n" +
                        "2026-11-01T00:00:05.000000Z\ta\t2.0\n" +
                        "2026-11-01T00:00:06.000000Z\ta\t5.0\n" +
                        "2026-11-01T00:00:07.000000Z\ta\t9.0\n" +
                        "2026-11-01T00:00:50.000000Z\ta\t10.0\n");
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testO3WritesFreshCheckpointPostReplay() throws Exception {
        // After the O3 replay path drives an apply commit, the
        // head metadata trio (lvSeqTxn, maxTs, stateBytes) reflects the
        // post-replay state - not the pre-O3 state, and not LONG_NULL.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, sym SYMBOL, x DOUBLE) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, sym, sum(x) OVER w AS s FROM base " +
                    "WINDOW w AS (PARTITION BY sym ORDER BY ts ANCHOR EXPRESSION timestamp_floor('1d', ts))");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                setCurrentMicros(0L);
                execute("INSERT INTO base (ts, sym, x) VALUES " +
                        "('2026-11-01T00:00:10.000000Z', 'a', 1.0), " +
                        "('2026-11-01T00:00:20.000000Z', 'a', 2.0)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                LiveViewInstance lv = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(lv);
                final long preO3HeadLvSeqTxn = lv.getHeadCheckpointLvSeqTxn();
                final long preO3StateBytes = lv.getHeadCheckpointStateBytes();
                Assert.assertNotEquals(Numbers.LONG_NULL, preO3HeadLvSeqTxn);
                Assert.assertTrue(preO3StateBytes > 0L);

                setCurrentMicros(200_000L);
                execute("INSERT INTO base (ts, sym, x) VALUES " +
                        "('2026-11-01T00:00:05.000000Z', 'a', 5.0)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                final long postReplayLvSeqTxn = lv.getHeadCheckpointLvSeqTxn();
                Assert.assertNotEquals(Numbers.LONG_NULL, postReplayLvSeqTxn);
                Assert.assertNotEquals(preO3HeadLvSeqTxn, postReplayLvSeqTxn);
                Assert.assertNotEquals(Numbers.LONG_NULL, lv.getHeadCheckpointMaxTs());
                Assert.assertTrue(
                        "post-replay state_bytes populated",
                        lv.getHeadCheckpointStateBytes() > 0L
                );


            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testO3DetectionFiresForNonAnchoredLv() throws Exception {
        // Non-anchored stamp: the row-loop stamp updates
        // latestSeenTs for LVs without an anchored named window. Pre-fix,
        // only AnchorDispatchingCursor stamped, so non-anchored LVs never
        // drove O3 detection. The test uses row_number() OVER (), which the
        // factory specialises into SequenceRowNumberFunction (no per-partition
        // map). That puts the LV on the not-snapshot-capable branch of the
        // replay path: the O3 cycle invalidates the head, advances the
        // watermarks, and trails for the O3 batch. Detection itself - what
        // the row-loop stamp enables - is the surface this test pins.
        // Head-miss / head-hit content correctness is covered by
        // testO3HeadMissReplaysFromLowerBound and testO3HeadHitReplaysFromHead
        // against anchored snapshot-capable LVs.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x DOUBLE, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                setCurrentMicros(0L);
                execute("INSERT INTO base (ts, x) VALUES " +
                        "('2026-11-01T00:00:10.000000Z', 1.0), " +
                        "('2026-11-01T00:00:20.000000Z', 2.0)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                LiveViewInstance lv = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(lv);
                Assert.assertNull("LV has no anchored window", lv.getAnchorWindow());
                Assert.assertEquals(
                        "row-loop stamp updates latestSeenTs without an anchor cursor",
                        MicrosFormatUtils.parseUTCTimestamp("2026-11-01T00:00:20.000000Z"),
                        lv.getLatestSeenTs()
                );
                final long lastProcessedAfterBatch1 = lv.getLastProcessedSeqTxn();

                // Drop an O3 row. The detect block fires because latestSeenTs
                // is populated; the not-snapshot-capable LV then takes the
                // skip branch in o3Replay.
                setCurrentMicros(200_000L);
                execute("INSERT INTO base (ts, x) VALUES " +
                        "('2026-11-01T00:00:05.000000Z', 3.0)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                // The watermark stays at 20 thanks to the monotonic clamp,
                // and lastProcessedSeqTxn advances so the next cycle does
                // not re-iterate the O3 batch in WAL order.
                Assert.assertEquals(
                        "monotonic clamp keeps latestSeenTs at the pre-O3 high water",
                        MicrosFormatUtils.parseUTCTimestamp("2026-11-01T00:00:20.000000Z"),
                        lv.getLatestSeenTs()
                );
                Assert.assertTrue(
                        "lastProcessedSeqTxn advanced past the O3 base seqTxn",
                        lv.getLastProcessedSeqTxn() > lastProcessedAfterBatch1
                );
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testFreezeBlocksInFlightRefreshCycle() throws Exception {
        // startCheckpoint must force a happens-before edge with any in-flight
        // refresh turn before its file copy begins, so the agent never reads
        // _lv.s mid-rewrite. The fix takes and releases the refresh latch
        // inside startCheckpoint. Here the test stands in for the worker by
        // holding the latch manually and asserts startCheckpoint blocks
        // until the latch is released.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");

            final LiveViewInstance lv = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(lv);

            // Simulate the worker mid-turn by holding the latch on this thread.
            Assert.assertTrue(
                    "test setup must take the refresh latch",
                    lv.tryLockForRefresh()
            );

            final AtomicBoolean returned = new AtomicBoolean(false);
            final Thread agent = new Thread(() -> {
                lv.startCheckpoint(lv.getStateReader().getAppliedWatermark());
                returned.set(true);
            }, "lv-freeze-handshake-test");
            try {
                agent.start();
                // Wait for the agent to publish the freeze flag and start spinning on the latch. A
                // fixed sleep here made this a positive assertion on an unsynchronized thread: on a
                // loaded machine the agent may not be scheduled inside the window, and the assertion
                // below would go red for a reason that has nothing to do with the contract under
                // test. Waiting for the flag instead is safe for the negative assertion that follows
                // it, because this thread holds the refresh latch the whole time - startCheckpoint
                // cannot return however long the agent takes to get going.
                TestUtils.assertEventually(() -> Assert.assertTrue(
                        "freeze flag must be published before the agent blocks on the latch",
                        lv.isFreezeInProgress()
                ), 30);
                Assert.assertFalse(
                        "startCheckpoint must block while the refresh latch is held",
                        returned.get()
                );

                // Release the latch. startCheckpoint should return promptly.
                lv.unlockAfterRefresh();
                agent.join(5_000);
                Assert.assertFalse(
                        "startCheckpoint thread must have completed",
                        agent.isAlive()
                );
                Assert.assertTrue(
                        "startCheckpoint must return after the latch is released",
                        returned.get()
                );
            } finally {
                if (lv.isFreezeInProgress()) {
                    lv.endCheckpoint();
                }
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testFreezeQueuesInvalidationUntilEnd() throws Exception {
        // markInvalid blocks on the freeze. If a base-table schema change
        // happens mid-snapshot, invalidation is queued and applied right
        // after endCheckpoint. The snapshot reflects the pre-invalidation
        // state.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");

            final LiveViewInstance lv = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(lv);

            // Take the freeze. Now an out-of-band invalidate must wait.
            lv.startCheckpoint(lv.getStateReader().getAppliedWatermark());
            Assert.assertTrue(lv.isFreezeInProgress());
            Assert.assertFalse("LV must still be valid pre-freeze", lv.isInvalid());

            final AtomicBoolean returned = new AtomicBoolean(false);
            final Thread invalidator = new Thread(() -> {
                engine.invalidateLiveView(lv, "test queued behind freeze");
                returned.set(true);
            }, "lv-invalidate-freeze-test");
            try {
                invalidator.start();
                // Wait until the invalidator is actually parked inside waitForUnfrozen() before
                // asserting it has not returned. A fixed sleep proved nothing: if the thread had not
                // reached invalidateLiveView yet, the two negative assertions below would hold
                // trivially and the test would pass without the freeze ever having blocked anything.
                // waitForUnfrozen parks in Object.wait(), so WAITING is the fence.
                TestUtils.assertEventually(() -> Assert.assertEquals(
                        "invalidator must park inside waitForUnfrozen",
                        Thread.State.WAITING,
                        invalidator.getState()
                ), 30);
                Assert.assertFalse(
                        "invalidateLiveView must wait until endCheckpoint",
                        returned.get()
                );
                Assert.assertFalse(
                        "LV must still be valid while frozen",
                        lv.isInvalid()
                );

                lv.endCheckpoint();
                invalidator.join(5_000);
                Assert.assertFalse(
                        "invalidate thread must have returned",
                        invalidator.isAlive()
                );
                Assert.assertTrue(
                        "invalidate must complete after endCheckpoint",
                        returned.get()
                );
                Assert.assertTrue(
                        "LV is invalid after endCheckpoint",
                        lv.isInvalid()
                );
                Assert.assertTrue(
                        "invalidation reason persisted",
                        Chars.equals("test queued behind freeze", lv.getStateReader().getInvalidationReason())
                );
            } finally {
                if (lv.isFreezeInProgress()) {
                    lv.endCheckpoint();
                }
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testFreezeGateSkipsRefreshTurn() throws Exception {
        // DatabaseCheckpointAgent toggles freezeInProgress around
        // its per-LV file copy so the refresh worker does not advance _lv.s /
        // the on-disk tier mid-snapshot. This test exercises the gate without
        // running the full agent: set startCheckpoint manually, drive a
        // refresh - the worker must skip and lastProcessedSeqTxn must not
        // advance. After endCheckpoint(), a subsequent refresh processes the
        // pending commit.
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, x, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base WHERE x > 0");

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                setCurrentMicros(0L);

                LiveViewInstance lv = engine.getLiveViewRegistry().getViewInstance("lv");
                Assert.assertNotNull(lv);
                long beforeProcessed = lv.getLastProcessedSeqTxn();

                // Insert a row + ingest the WAL; refresh has NOT run yet.
                execute("INSERT INTO base (ts, x) VALUES ('2026-04-01T00:00:00.000000Z', 1)");
                drainWalQueue();

                // Freeze the LV. The refresh worker's next turn must see the
                // flag, skip, and leave lastProcessedSeqTxn unchanged.
                lv.startCheckpoint(lv.getStateReader().getAppliedWatermark());
                Assert.assertTrue("freeze in progress after startCheckpoint", lv.isFreezeInProgress());
                drainJob(job);
                Assert.assertEquals(
                        "frozen refresh did not advance lastProcessedSeqTxn",
                        beforeProcessed,
                        lv.getLastProcessedSeqTxn()
                );

                // Unfreeze, drive a fresh refresh. The pending commit should
                // land in the LV.
                lv.endCheckpoint();
                Assert.assertFalse("freeze cleared after endCheckpoint", lv.isFreezeInProgress());
                setCurrentMicros(200_000L);
                drainJob(job);
                drainWalQueue();

                Assert.assertTrue(
                        "post-unfreeze refresh advanced lastProcessedSeqTxn",
                        lv.getLastProcessedSeqTxn() > beforeProcessed
                );
                assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n1\n");
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testWorkerYieldsAtTurnBudget() throws Exception {
        // A single refresh turn is bounded by max commits (and max duration) so a
        // long backlog cannot monopolise the worker. With budget = 3 commits per turn
        // and a six-commit backlog, one turn cannot drain it all - the budget forces a
        // yield with the lead only partially refreshed - and repeated turns complete
        // it in order.
        //
        // Every persisted output type is now lead-eligible, so the view runs the
        // decoupled lead path: the refresh drains base commits into the in-mem tier
        // (ungated by FLUSH EVERY, budget-bounded per turn) and the flush materialises
        // them to disk on the FLUSH EVERY cadence. refreshedUpToSeqTxn tracks the
        // budget-bounded lead drain; lastProcessedSeqTxn tracks the flush. The DECIMAL
        // passthrough column exercises the decimal tier storage under the yield.
        setProperty(PropertyKey.CAIRO_LIVE_VIEW_REFRESH_TURN_MAX_COMMITS, 3);
        assertMemoryLeak(() -> {
            setCurrentMicros(0L);
            execute("CREATE TABLE base (ts TIMESTAMP, x INT, d DECIMAL(18, 6), pg SYMBOL) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, x, d, count(*) OVER (PARTITION BY pg ORDER BY ts ROWS BETWEEN 1000000 PRECEDING AND CURRENT ROW) AS rn FROM base");

            // Six separate base WAL commits - one INSERT per row so each
            // becomes its own sequencer txn for the refresh worker to walk.
            execute("INSERT INTO base (ts, x, d) VALUES ('2026-04-01T00:00:01.000000Z', 1, 1.000000m)");
            execute("INSERT INTO base (ts, x, d) VALUES ('2026-04-01T00:00:02.000000Z', 2, 1.000000m)");
            execute("INSERT INTO base (ts, x, d) VALUES ('2026-04-01T00:00:03.000000Z', 3, 1.000000m)");
            execute("INSERT INTO base (ts, x, d) VALUES ('2026-04-01T00:00:04.000000Z', 4, 1.000000m)");
            execute("INSERT INTO base (ts, x, d) VALUES ('2026-04-01T00:00:05.000000Z', 5, 1.000000m)");
            execute("INSERT INTO base (ts, x, d) VALUES ('2026-04-01T00:00:06.000000Z', 6, 1.000000m)");
            drainWalQueue();

            LiveViewInstance lv = engine.getLiveViewRegistry().getViewInstance("lv");
            Assert.assertNotNull(lv);

            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                // One turn makes progress but cannot drain the whole six-commit
                // backlog: the per-turn budget forces a yield with the lead only
                // partially refreshed.
                job.run();
                drainWalQueue();
                long afterOneTurn = lv.getRefreshedUpToSeqTxn();
                Assert.assertTrue(
                        "one turn must make progress but must not drain the whole backlog, was " + afterOneTurn,
                        afterOneTurn > 0 && afterOneTurn < 6
                );

                // Remaining turns - still at clock 0, so the lead refresh runs ungated
                // by FLUSH EVERY - drain the residual commits into the lead in order.
                drainJob(job);
                drainWalQueue();
                Assert.assertEquals(
                        "repeated turns drain the full backlog into the lead",
                        6L,
                        lv.getRefreshedUpToSeqTxn()
                );

                // Advance past FLUSH EVERY so the accumulated lead materialises to
                // disk; lastProcessed catches up and every row is now visible.
                setCurrentMicros(200_000L);
                drainJob(job);
                drainWalQueue();
                Assert.assertEquals(
                        "flush materialises the whole lead",
                        6L,
                        lv.getLastProcessedSeqTxn()
                );
                assertQuery("SELECT count() FROM lv").noLeakCheck().noRandomAccess().expectSize().returns("count\n6\n");
            }

            execute("DROP LIVE VIEW lv");
        });
    }

    @Test
    public void testLiveViewsCatalogueExposesCheckpointTimelineColumns() throws Exception {
        // A view that has published no generation reports NULL across the
        // checkpoint_* group rather than zero: "no timeline" and "a timeline
        // that measures zero" are different statements, and only the counters
        // that genuinely start at zero say so. The first sealed root then fills
        // the group in, which is what makes the NULLs an assertion about the
        // publication seam rather than about a column that is never written.
        // One boundary per flush, so a second commit publishes a second
        // generation rather than riding the default row cadence.
        setProperty(PropertyKey.CAIRO_LIVE_VIEW_CHECKPOINT_ROWS, 1);
        assertMemoryLeak(() -> {
            execute("CREATE TABLE base (ts TIMESTAMP, sym SYMBOL, x DOUBLE) TIMESTAMP(ts) PARTITION BY DAY WAL");
            execute("CREATE LIVE VIEW lv FLUSH EVERY 100ms START FROM NOW AS " +
                    "SELECT ts, sym, sum(x) OVER w AS s FROM base " +
                    "WINDOW w AS (PARTITION BY sym ORDER BY ts RANGE BETWEEN '30' SECOND PRECEDING AND CURRENT ROW)");
            try (LiveViewRefreshJob job = new LiveViewRefreshJob(0, engine, 1)) {
                assertQuery("SELECT checkpoint_timeline_generation, checkpoint_timeline_entries, " +
                        "checkpoint_timeline_logical_bytes, checkpoint_timeline_physical_bytes, " +
                        "checkpoint_timeline_shared_bytes, checkpoint_timeline_sharing_ratio, " +
                        "checkpoint_oldest_pinned_generation, checkpoint_gc_lag_generations, " +
                        "checkpoint_last_write_micros, checkpoint_last_lookup_depth, " +
                        "checkpoint_repair_in_progress, checkpoint_repair_correction_timestamp, " +
                        "checkpoint_repair_roots_versioned, checkpoint_repair_failures FROM live_views()")
                        .noLeakCheck().noRandomAccess()
                        .returns("checkpoint_timeline_generation\tcheckpoint_timeline_entries\t" +
                                "checkpoint_timeline_logical_bytes\tcheckpoint_timeline_physical_bytes\t" +
                                "checkpoint_timeline_shared_bytes\tcheckpoint_timeline_sharing_ratio\t" +
                                "checkpoint_oldest_pinned_generation\tcheckpoint_gc_lag_generations\t" +
                                "checkpoint_last_write_micros\tcheckpoint_last_lookup_depth\t" +
                                "checkpoint_repair_in_progress\tcheckpoint_repair_correction_timestamp\t" +
                                "checkpoint_repair_roots_versioned\tcheckpoint_repair_failures\n" +
                                "null\tnull\tnull\tnull\tnull\tnull\tnull\tnull\tnull\tnull\tfalse\t\t0\t0\n");

                setCurrentMicros(0L);
                execute("INSERT INTO base (ts, sym, x) VALUES " +
                        "('2026-08-01T00:00:00.000000Z', 'a', 1.0), " +
                        "('2026-08-01T00:00:01.000000Z', 'b', 3.0)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                // One generation holding one boundary, valid through base
                // seqTxn 1, and a first publication that wrote every byte the
                // timeline holds. The A/B pair has only one valid slot yet, so
                // the collection floor is the current generation and the lag is
                // zero; it becomes 1 once a second publication leaves the first
                // slot behind as the fallback. The collection columns stay NULL:
                // this view's only reconciliation ran against a directory that
                // held no generation to sweep.
                assertQuery("SELECT checkpoint_timeline_generation, checkpoint_timeline_entries, " +
                        "checkpoint_timeline_normalized_base_seqtxn, " +
                        "checkpoint_timeline_physical_bytes = checkpoint_last_write_new_bytes AS first_write_is_all, " +
                        "checkpoint_timeline_logical_bytes > 0 AS has_logical_bytes, " +
                        "checkpoint_timeline_row_position_delta_bytes, " +
                        "checkpoint_oldest_pinned_generation, checkpoint_gc_lag_generations, " +
                        "checkpoint_data_segment_count, checkpoint_obsolete_segment_bytes FROM live_views()")
                        .noLeakCheck().noRandomAccess()
                        .returns("checkpoint_timeline_generation\tcheckpoint_timeline_entries\t" +
                                "checkpoint_timeline_normalized_base_seqtxn\tfirst_write_is_all\t" +
                                "has_logical_bytes\tcheckpoint_timeline_row_position_delta_bytes\t" +
                                "checkpoint_oldest_pinned_generation\tcheckpoint_gc_lag_generations\t" +
                                "checkpoint_data_segment_count\tcheckpoint_obsolete_segment_bytes\n" +
                                "1\t1\t1\ttrue\ttrue\t0\t1\t0\tnull\tnull\n");

                // A second cadence seal leaves the first generation in the
                // other slot, which is the fallback the WAL floor and the purge
                // guard are both held at.
                setCurrentMicros(200_000L);
                execute("INSERT INTO base (ts, sym, x) VALUES ('2026-08-01T00:00:02.000000Z', 'a', 5.0)");
                drainWalQueue();
                drainJob(job);
                drainWalQueue();

                assertQuery("SELECT checkpoint_timeline_generation, checkpoint_timeline_entries, " +
                        "checkpoint_oldest_pinned_generation, checkpoint_gc_lag_generations, " +
                        "checkpoint_last_write_new_bytes < checkpoint_timeline_physical_bytes AS write_is_marginal " +
                        "FROM live_views()")
                        .noLeakCheck().noRandomAccess()
                        .returns("checkpoint_timeline_generation\tcheckpoint_timeline_entries\t" +
                                "checkpoint_oldest_pinned_generation\tcheckpoint_gc_lag_generations\t" +
                                "write_is_marginal\n" +
                                "2\t2\t1\t1\ttrue\n");
            }

            try {
                // Startup reconciliation is the seam that sweeps the catalogue,
                // so a restart is what fills the collection columns in - off the
                // durable superblock and the sweep beside it, with no seal of its
                // own, which is why the marginal write cost reads NULL again.
                engine.getLiveViewRegistry().clear();
                engine.buildViewGraphs();

                assertQuery("SELECT checkpoint_timeline_generation, checkpoint_timeline_entries, " +
                        "checkpoint_timeline_physical_bytes > 0 AS has_physical_bytes, " +
                        "checkpoint_data_segment_count > 0 AS has_live_segments, " +
                        "checkpoint_obsolete_segment_bytes, checkpoint_last_write_new_bytes FROM live_views()")
                        .noLeakCheck().noRandomAccess()
                        .returns("checkpoint_timeline_generation\tcheckpoint_timeline_entries\t" +
                                "has_physical_bytes\thas_live_segments\t" +
                                "checkpoint_obsolete_segment_bytes\tcheckpoint_last_write_new_bytes\n" +
                                "2\t2\ttrue\ttrue\t0\t0\n");
            } finally {
                execute("DROP LIVE VIEW lv");
            }
        });
    }

